import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

// Message Roles and Types
export type Role = 'user' | 'agent';
export type MessageType = 'text' | 'script_card' | 'storyboard_card' | 'audio_selection' | 'video_card' | 'system_notification';

// Data Structures for Payload
export interface ScriptLine {
  id: string;
  scene: number;
  duration: string;
  visual: string;
  audio: string;
}

export interface ScriptData {
  title: string;
  totalDuration: string;
  sceneCount: number;
  lines: ScriptLine[];
}

export interface StoryboardImage {
  id: string;
  src: string;
  prompt: string;
  description: string;
}

export interface AudioOption {
  id: string;
  name: string;
  description: string;
  previewUrl: string; // Mock URL
  selected?: boolean;
}

// Main Message Interface
export interface Message {
  id: string;
  role: Role;
  type: MessageType;
  text?: string;
  timestamp: number;
  isLoading?: boolean;

  // Specific Payloads
  scriptData?: ScriptData;
  storyboardData?: StoryboardImage[];
  audioOptions?: AudioOption[];
  videoData?: {
    thumbnail: string;
    videoUrl: string;
    duration: string;
  };
}

// Overlay State Management
export type OverlayType = 'none' | 'script_editor' | 'image_viewer' | 'video_player';

export interface OverlayState {
  type: OverlayType;
  data?: any; // Context data for the overlay
}

import { ScriptData, StoryboardImage } from './types';

