      <ImageIcon size={14} className="text-purple-600" />
      <span className="text-xs font-bold text-gray-500 uppercase">Storyboard Preview</span>
    </div>
    <div className="flex overflow-x-auto gap-3 pb-4 no-scrollbar snap-x px-1">
