        <div 
          key={img.id}
          onClick={() => onImageClick(img)}
          className="snap-center shrink-0 w-32 md:w-40 flex flex-col gap-2 cursor-pointer group"
        >
          <div className="relative aspect-[9/16] rounded-xl overflow-hidden shadow-md bg-gray-200">
            <img src={img.src} alt={img.description} className="w-full h-full object-cover" />
            <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors" />
