import React, { useState, useEffect } from 'react';
import { X, Check, ArrowLeft, Send, Sparkles, GripVertical, Trash2 } from 'lucide-react';
import { ScriptData, ScriptLine, StoryboardImage } from '../types';

/* --- BOTTOM SHEET: SCRIPT EDITOR --- */
interface ScriptEditorProps {
  initialData: ScriptData;
  onClose: () => void;
  onConfirm: (newData: ScriptData) => void;
}

export const ScriptEditor: React.FC<ScriptEditorProps> = ({ initialData, onClose, onConfirm }) => {
  const [lines, setLines] = useState<ScriptLine[]>(initialData.lines);
  const [isClosing, setIsClosing] = useState(false);

  // Simple animation handling
  useEffect(() => {
    // Mount animation logic if needed
  }, []);

  const handleClose = () => {
    setIsClosing(true);
    setTimeout(onClose, 300);
  };

  const handleSave = () => {
    setIsClosing(true);
    setTimeout(() => onConfirm({ ...initialData, lines }), 300);
  };

  const handleTextChange = (id: string, field: 'visual' | 'audio', val: string) => {
    setLines(lines.map(l => l.id === id ? { ...l, [field]: val } : l));
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center">
      {/* Backdrop */}
      <div 
        className={`absolute inset-0 bg-black/40 backdrop-blur-sm transition-opacity duration-300 ${isClosing ? 'opacity-0' : 'opacity-100'}`} 
        onClick={handleClose}
      />

      {/* Sheet */}
      <div className={`relative w-full max-w-lg bg-white rounded-t-3xl shadow-2xl flex flex-col max-h-[90vh] transition-transform duration-300 transform ${isClosing ? 'translate-y-full' : 'translate-y-0'}`}>
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-gray-100">
          <button onClick={handleClose} className="p-2 text-gray-500 hover:bg-gray-100 rounded-full">
            <X size={20} />
          </button>
          <span className="font-bold text-gray-900">Edit Script</span>
          <button onClick={handleSave} className="p-2 text-indigo-600 font-medium hover:bg-indigo-50 rounded-full">
            <Check size={20} />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4">
          {lines.map((line, index) => (
            <div key={line.id} className="flex gap-3 items-start group">
              <div className="mt-4 text-gray-300 cursor-move">
                <GripVertical size={20} />
              </div>
              <div className="flex-1 bg-gray-50 rounded-xl p-3 border border-gray-200 focus-within:border-indigo-400 focus-within:ring-1 focus-within:ring-indigo-100 transition-all">
                <div className="flex justify-between text-xs font-bold text-gray-500 mb-2 uppercase tracking-wide">
                  <span>Scene {index + 1}</span>
                  <span>{line.duration}</span>
                </div>

                <div className="space-y-3">
                  <div>
                    <label className="block text-[10px] text-indigo-500 font-semibold mb-1">VISUAL</label>
                    <textarea 
                      value={line.visual}
                      onChange={(e) => handleTextChange(line.id, 'visual', e.target.value)}
                      className="w-full bg-white rounded-lg p-2 text-sm text-gray-800 border-none focus:ring-0 resize-none h-16"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] text-orange-500 font-semibold mb-1">AUDIO</label>
                    <textarea 
                      value={line.audio}
                      onChange={(e) => handleTextChange(line.id, 'audio', e.target.value)}
                      className="w-full bg-white rounded-lg p-2 text-sm text-gray-600 border-none focus:ring-0 resize-none h-12 italic"
                    />
                  </div>
                </div>
              </div>
            </div>
          ))}
          <div className="h-8" /> {/* Spacer */}
        </div>

        {/* Floating Mic for "Natural Language Edit" */}
        <div className="absolute bottom-6 left-1/2 -translate-x-1/2 shadow-xl bg-gray-900 text-white px-4 py-2 rounded-full flex items-center gap-2 text-xs font-medium cursor-pointer active:scale-95 transition-transform">
           <Sparkles size={14} className="text-yellow-400" />
           <span>Use AI to rewrite scene 2...</span>
        </div>
      </div>
    </div>
  );
};

/* --- FULLSCREEN IMAGE EDITOR --- */
interface ImageViewerProps {
  image: StoryboardImage;
  onClose: () => void;
  onUpdate: (newImg: StoryboardImage) => void;
}

export const ImageViewer: React.FC<ImageViewerProps> = ({ image, onClose, onUpdate }) => {
  const [prompt, setPrompt] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [currentImg, setCurrentImg] = useState(image);

  const handleMagicEdit = () => {
    if (!prompt) return;
    setIsLoading(true);
    // Simulate generation
    setTimeout(() => {
      setCurrentImg({
        ...currentImg,
        src: `https://picsum.photos/400/600?random=${Date.now()}` // Force new image
      });
      setIsLoading(false);
      setPrompt('');
    }, 2000);
  };

  return (
    <div className="fixed inset-0 z-50 bg-black flex flex-col animate-in fade-in duration-300">
      {/* Top Bar */}
      <div className="absolute top-0 left-0 right-0 p-4 pt-safe z-10 flex justify-between items-center bg-gradient-to-b from-black/80 to-transparent">
        <button onClick={onClose} className="text-white/80 hover:text-white">
          <ArrowLeft size={24} />
        </button>
        <span className="text-white font-medium text-sm">Storyboard Editor</span>
        <button 
            onClick={() => { onUpdate(currentImg); onClose(); }} 
            className="text-white bg-white/20 px-3 py-1 rounded-full text-xs font-bold backdrop-blur-md"
        >
            Done
        </button>
      </div>

      {/* Main Image Area */}
      <div className="flex-1 flex items-center justify-center relative w-full h-full">
         {isLoading && (
            <div className="absolute inset-0 z-20 flex flex-col items-center justify-center bg-black/60 backdrop-blur-sm">
                <div className="w-10 h-10 border-4 border-white/20 border-t-indigo-500 rounded-full animate-spin mb-4"></div>
                <p className="text-white text-sm font-medium animate-pulse">Regenerating...</p>
            </div>
         )}
         <img 
            src={currentImg.src} 
            alt="Full view" 
            className={`max-w-full max-h-full object-contain transition-opacity duration-500 ${isLoading ? 'opacity-50' : 'opacity-100'}`}
         />
      </div>

      {/* Bottom Floating Input (Magic Edit) */}
      <div className="absolute bottom-0 left-0 right-0 p-4 pb-safe bg-gradient-to-t from-black/90 via-black/50 to-transparent">
        <div className="flex flex-col gap-2">
           {/* Prompt Peek */}
           <div className="text-[10px] text-white/50 px-2 truncate">
              Original: {currentImg.prompt}
           </div>

           <div className="flex items-center gap-2 bg-white/10 backdrop-blur-lg border border-white/20 rounded-full px-1 py-1 pl-4">
              <Sparkles size={16} className="text-indigo-400" />
              <input 
                type="text"
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="Change angle, lighting, style..."
                className="flex-1 bg-transparent border-none text-white text-sm focus:ring-0 placeholder:text-white/40"
              />
              <button 
                onClick={handleMagicEdit}
                disabled={!prompt}
                className={`w-9 h-9 rounded-full flex items-center justify-center transition-colors ${prompt ? 'bg-indigo-600 text-white' : 'bg-white/10 text-white/20'}`}
              >
                <Send size={16} />
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

/* --- FULLSCREEN VIDEO PLAYER --- */
interface VideoPlayerProps {
    thumbnail: string;
    onClose: () => void;
}

export const VideoPlayer: React.FC<VideoPlayerProps> = ({ thumbnail, onClose }) => {
    const [isPlaying, setIsPlaying] = useState(true);
    const [magicInput, setMagicInput] = useState("");
    const [status, setStatus] = useState<'idle' | 'processing'>('idle');

    const handleMagicFix = () => {
        if(!magicInput) return;
        setStatus('processing');
        setTimeout(() => {
            setStatus('idle');
            setMagicInput("");
            alert("Modification applied! (Mock)");
        }, 2000);
    };

    return (
        <div className="fixed inset-0 z-50 bg-black flex flex-col animate-in slide-in-from-bottom duration-300">
             <div className="absolute top-0 left-0 right-0 p-4 pt-safe z-10 flex justify-between items-center">
                <button onClick={onClose} className="bg-black/40 backdrop-blur rounded-full p-2 text-white">
                     <X size={20} />
                </button>
             </div>

             {/* Mock Video Surface */}
             <div className="flex-1 relative bg-gray-900 flex items-center justify-center" onClick={() => setIsPlaying(!isPlaying)}>
                {/* We use an image to simulate the video for this demo */}
                <img src={thumbnail} className="w-full h-full object-cover opacity-80" />

                {!isPlaying && (
                    <div className="absolute inset-0 flex items-center justify-center bg-black/20">
                        <Play size={48} fill="white" className="text-white" />
                    </div>
                )}

                {/* Processing Overlay */}
                {status === 'processing' && (
                     <div className="absolute inset-0 bg-black/80 backdrop-blur-sm flex flex-col items-center justify-center z-20">
                        <div className="w-12 h-12 border-4 border-white/10 border-t-green-500 rounded-full animate-spin mb-4" />
                        <span className="text-white font-medium">Applying Magic Edit...</span>
                     </div>
                )}
             </div>

             {/* Controls & Magic Edit */}
             <div className="absolute bottom-0 w-full p-4 pb-safe bg-gradient-to-t from-black via-black/60 to-transparent">
                 <div className="mb-4">
                     {/* Fake Scrubber */}
                     <div className="h-1 bg-white/30 rounded-full w-full mb-2">
                         <div className="h-full w-1/3 bg-white rounded-full relative">
                             <div className="absolute right-0 top-1/2 -translate-y-1/2 w-3 h-3 bg-white rounded-full shadow" />
                         </div>
                     </div>
                     <div className="flex justify-between text-[10px] text-white/60">
                         <span>0:05</span>
                         <span>0:15</span>
                     </div>
                 </div>

                 <div className="flex items-center gap-3">
                     <div className="flex-1 bg-gray-800/80 backdrop-blur-md rounded-2xl flex items-center p-1 border border-white/10">
                        <input 
                            value={magicInput} 
                            onChange={(e) => setMagicInput(e.target.value)}
                            className="flex-1 bg-transparent border-none text-white text-sm px-3 py-2 placeholder:text-gray-400 focus:ring-0"
                            placeholder="Change red text to blue..."
                        />
                        <button 
                            onClick={handleMagicFix}
                            className="p-2 bg-indigo-600 rounded-xl text-white hover:bg-indigo-500"
                        >
                            <Sparkles size={16} />
                        </button>
                     </div>
                 </div>
             </div>
        </div>
    );
}

import React, { useEffect, useRef } from 'react';
import { Message } from '../types';
import { AVATAR_URL } from '../constants';
import { ScriptCard, StoryboardCard, AudioSelectionCard, VideoCard } from './ImmersiveCards';

interface ChatInterfaceProps {
  messages: Message[];
  onCardClick: (msgId: string, action: string, data?: any) => void;
}

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ messages, onCardClick }) => {
  const bottomRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom on new message
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages.length, messages[messages.length - 1]?.isLoading]);

  return (
    <div className="flex-1 overflow-y-auto px-4 py-4 space-y-6">
      {/* Intro Spacer */}
      <div className="h-4"></div>

      {messages.map((msg) => (
        <div 
          key={msg.id} 
