import React, { useState } from 'react';
import { Mic, Send, Sparkles } from 'lucide-react';
import { INITIAL_CHIPS } from '../constants';

interface InputAreaProps {
  onSendMessage: (text: string) => void;
  disabled?: boolean;
}

export const InputArea: React.FC<InputAreaProps> = ({ onSendMessage, disabled }) => {
  const [inputValue, setInputValue] = useState('');
  const [isRecording, setIsRecording] = useState(false);

  const handleSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (inputValue.trim() && !disabled) {
      onSendMessage(inputValue);
      setInputValue('');
    }
  };

  const handleChipClick = (chip: string) => {
    setInputValue((prev) => prev ? `${prev} ${chip}` : chip);
  };

  return (
    <div className="flex-shrink-0 bg-white border-t border-gray-100 pb-safe safe-area-bottom z-20">
      {/* Chips Carousel */}
      <div className="overflow-x-auto no-scrollbar py-3 px-4 flex gap-2">
        {INITIAL_CHIPS.map((chip) => (
          <button
            key={chip}
            onClick={() => handleChipClick(chip)}
            disabled={disabled}
            className="flex-shrink-0 px-3 py-1.5 bg-gray-50 text-indigo-600 text-xs font-medium rounded-full border border-gray-200 hover:bg-indigo-50 active:scale-95 transition-transform"
          >
            {chip}
          </button>
        ))}
      </div>

      {/* Input Bar */}
      <div className="px-4 pb-4 flex items-end gap-2">
        <div className="flex-1 bg-gray-100 rounded-2xl flex items-center p-2">
           {/* Voice Button (Left/Inside) or separate? Prompt says right, but usually inside or next to input. Let's put Mic next to input for easy thumb access. */}
           <input
            type="text"
            className="flex-1 bg-transparent border-none focus:ring-0 px-2 text-sm max-h-24 py-2"
            placeholder="描述你想制作的视频..."
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSubmit()}
            disabled={disabled}
          />
        </div>

        {/* Action Button */}
        <button
          onClick={inputValue ? () => handleSubmit() : () => setIsRecording(!isRecording)}
          disabled={disabled}
          className={`h-11 w-11 flex items-center justify-center rounded-full text-white shadow-lg transition-all ${
            inputValue 
              ? 'bg-indigo-600 hover:bg-indigo-700' 
              : isRecording 
                ? 'bg-red-500 animate-pulse' 
                : 'bg-gray-800'
          }`}
        >
          {inputValue ? <Send size={20} /> : <Mic size={20} />}
        </button>
      </div>
    </div>
  );
};

