import React, { useEffect, useRef } from 'react';
import { Message } from '../types';
import { AVATAR_URL } from '../constants';
import { ScriptCard, StoryboardCard, AudioSelectionCard, VideoCard } from './ImmersiveCards';

interface ChatInterfaceProps {
  messages: Message[];
  onCardClick: (msgId: string, action: string, data?: any) => void;
}

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ messages, onCardClick }) => {
  const bottomRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom on new message
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages.length, messages[messages.length - 1]?.isLoading]);

  return (
    <div className="flex-1 overflow-y-auto px-4 py-4 space-y-6">
      {/* Intro Spacer */}
      <div className="h-4"></div>

      {messages.map((msg) => (
        <div 
          key={msg.id} 
          className={`flex gap-3 w-full animate-in slide-in-from-bottom-2 duration-500 ${
            msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'
          }`}
        >
          {/* Avatar (Agent Only) */}
          {msg.role === 'agent' && (
            <div className="flex-shrink-0 w-8 h-8 rounded-full overflow-hidden mt-1 shadow-sm border border-gray-200">
              <img src={AVATAR_URL} alt="Agent" className="w-full h-full object-cover" />
            </div>
          )}

          {/* Content Container */}
          <div className={`flex flex-col gap-2 max-w-full ${
            msg.role === 'user' ? 'items-end' : 'items-start'
          } flex-1 min-w-0`}>

            {/* Text Bubble */}
            {msg.text && (
              <div 
                className={`px-4 py-2.5 rounded-2xl text-[15px] leading-relaxed max-w-[85%] shadow-sm ${
                  msg.role === 'user' 
                    ? 'bg-indigo-600 text-white rounded-br-none' 
                    : 'bg-white text-gray-800 border border-gray-100 rounded-bl-none'
                }`}
              >
                {msg.text}
              </div>
            )}

            {/* Loading Indicator */}
            {msg.isLoading && (
               <div className="bg-white px-4 py-3 rounded-2xl rounded-bl-none border border-gray-100 shadow-sm flex items-center gap-1.5">
                  <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                  <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                  <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce"></div>
               </div>
            )}

            {/* Rich Cards based on Type */}
            {!msg.isLoading && msg.type === 'script_card' && msg.scriptData && (
              <ScriptCard 
                data={msg.scriptData} 
                onClick={() => onCardClick(msg.id, 'open_script', msg.scriptData)}
                onConfirm={() => onCardClick(msg.id, 'confirm_script', msg.scriptData)}
              />
            )}

            {!msg.isLoading && msg.type === 'storyboard_card' && msg.storyboardData && (
              <StoryboardCard 
                images={msg.storyboardData} 
                onImageClick={(img) => onCardClick(msg.id, 'view_image', { initialImage: img, allImages: msg.storyboardData })}
              />
            )}

            {!msg.isLoading && msg.type === 'audio_selection' && msg.audioOptions && (
              <AudioSelectionCard 
                options={msg.audioOptions} 
                onSelect={(id) => onCardClick(msg.id, 'select_audio', id)}
              />
            )}

            {!msg.isLoading && msg.type === 'video_card' && msg.videoData && (
                <VideoCard 
                    thumbnail={msg.videoData.thumbnail}
                    duration={msg.videoData.duration}
                    onClick={() => onCardClick(msg.id, 'play_video', msg.videoData)}
                />
            )}
          </div>
        </div>
      ))}
      <div ref={bottomRef} />
    </div>
  );
};

import React, { useState, useCallback } from 'react';
import { Message, MessageType, OverlayState, ScriptData, StoryboardImage } from './types';
import { ChatInterface } from './components/ChatInterface';
import { InputArea } from './components/InputArea';
import { ScriptEditor, ImageViewer, VideoPlayer } from './components/Overlays';
import { MOCK_SCRIPT, MOCK_STORYBOARD } from './constants';

export default function App() {
  const [messages, setMessages] = useState<Message[]>([
    { 
      id: 'init', 
      role: 'agent', 
      type: 'text', 
      text: '嗨！今天想制作什么视频？', 
      timestamp: Date.now() 
    }
  ]);
  const [overlay, setOverlay] = useState<OverlayState>({ type: 'none' });
  const [isAgentThinking, setIsAgentThinking] = useState(false);

  // --- Helper to add message ---
  const addMsg = (msg: Partial<Message>) => {
    setMessages(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      role: 'agent',
      type: 'text',
      ...msg
    } as Message]);
  };

  // --- AGENT STATE MACHINE (MOCK) ---
  const handleUserMessage = async (text: string) => {
    // 1. Add User Message
    addMsg({ role: 'user', text, type: 'text' });

    // 2. Simulate Thinking
    setIsAgentThinking(true);

    // Add a temporary loading bubble
    const loadingId = 'loading-' + Date.now();
    setMessages(prev => [...prev, { id: loadingId, role: 'agent', type: 'text', isLoading: true, timestamp: Date.now() }]);

    // 3. Determine Response based on context (Simple sequential flow for demo)
    setTimeout(() => {
      // Remove loading bubble
      setMessages(prev => prev.filter(m => m.id !== loadingId));
      setIsAgentThinking(false);

      const lastType = messages.filter(m => m.role === 'agent' && m.type !== 'text').pop()?.type;

      if (!lastType) {
        // Step 1: Generate Script
        addMsg({ role: 'agent', text: '我为你草拟了一份赛博朋克风格的脚本，点击查看详情。' });
        addMsg({ role: 'agent', type: 'script_card', scriptData: MOCK_SCRIPT });
      } else if (lastType === 'script_card') {
          // Fallback if they type after script
          addMsg({ role: 'agent', text: '请先确认上方的脚本，以便生成分镜。' });
      } else if (lastType === 'storyboard_card') {
          addMsg({ role: 'agent', text: '我可以更新图片。长按查看详情或点击进行魔法编辑。' });
      } else {
         addMsg({ role: 'agent', text: '正在处理！' });
      }

    }, 1500);
  };

  // --- INTERACTION HANDLERS ---
  const handleCardClick = useCallback((msgId: string, action: string, data?: any) => {
    if (action === 'open_script') {
      setOverlay({ type: 'script_editor', data: data });
    } else if (action === 'confirm_script') {
        const scriptData = data as ScriptData;
        // Proceed to Storyboard Generation
        setIsAgentThinking(true);
        setTimeout(() => {
             setIsAgentThinking(false);
             addMsg({ role: 'agent', text: '脚本已确认。正在生成分镜...' });

             // Generate Storyboard Data based on Script Lines
            const generatedStoryboard: StoryboardImage[] = scriptData.lines.map((line) => ({
                id: `img-${line.id}`,
                src: `https://picsum.photos/400/600?random=${line.id}-${Date.now()}`, 
                prompt: line.visual,
                description: line.visual.length > 50 ? line.visual.substring(0, 47) + '...' : line.visual
            }));

            setTimeout(() => {
                addMsg({ 
                    role: 'agent', 
                    type: 'storyboard_card', 
                    storyboardData: generatedStoryboard.length > 0 ? generatedStoryboard : MOCK_STORYBOARD 
                });

                setTimeout(() => {
                    addMsg({ role: 'agent', text: '哪种氛围最合适？' });
                    addMsg({ 
                        role: 'agent', 
                        type: 'audio_selection',
                        audioOptions: [
                            { id: '1', name: '霓虹脉冲', description: '合成波，充满活力', previewUrl: '' },
                            { id: '2', name: '夜雨', description: '低保真，氛围感', previewUrl: '' },
                            { id: '3', name: '未来贝斯', description: '重节奏，律动', previewUrl: '' }
                        ]
                    });
                }, 1000);
            }, 1500);
        }, 500);
    } else if (action === 'view_image') {
      // Data contains { initialImage, allImages }
      setOverlay({ type: 'image_viewer', data: data });
    } else if (action === 'select_audio') {
        // User selected audio, move to Video Generation
        setMessages(prev => prev.map(m => 
             m.type === 'audio_selection' 
             ? { ...m, audioOptions: m.audioOptions?.map(o => ({...o, selected: o.id === data}))} 
             : m
        ));

        // Trigger Video Generation
        setTimeout(() => {
            addMsg({ role: 'agent', text: '很好的选择！正在渲染最终视频...' });
            // Simulate waiting
            setTimeout(() => {
                addMsg({ 
                    role: 'agent', 
                    type: 'video_card', 
                    videoData: {
                        thumbnail: MOCK_STORYBOARD[0].src, 
                        videoUrl: '#',
                        duration: '0:30'
                    } 
                });
            }, 2500);
        }, 500);
    } else if (action === 'play_video') {
        setOverlay({ type: 'video_player', data: data });
    }
  }, [messages]);

  // Rename this to represent SAVING data, not next step
  const handleScriptSave = (newData: ScriptData) => {
    setOverlay({ type: 'none' });

    // Only update the message in chat history to reflect changes
    // Do NOT trigger storyboard generation here
    setMessages(prev => prev.map(m => 
       m.type === 'script_card' ? { ...m, scriptData: newData } : m
    ));
  };

  const handleImageUpdate = (updatedImg: StoryboardImage) => {
     // Persist changes from ImageViewer back to the main chat
     setMessages(prev => prev.map(msg => {
         if (msg.type === 'storyboard_card' && msg.storyboardData) {
             return {
                 ...msg,
                 storyboardData: msg.storyboardData.map(img => 
                     img.id === updatedImg.id ? updatedImg : img
                 )
             };
         }
         return msg;
     }));
  };

  return (
    <div className="flex justify-center bg-gray-100 h-screen w-screen overflow-hidden">
      {/* Mobile Container */}
      <div className="w-full max-w-md h-full bg-gray-50 flex flex-col relative shadow-2xl overflow-hidden md:border-x border-gray-200">

        {/* Header */}
        <header className="flex items-center justify-center p-4 bg-white/80 backdrop-blur-md sticky top-0 z-10 border-b border-gray-200/50">
           <h1 className="font-bold text-gray-800 tracking-tight">AI 导演</h1>
        </header>

        {/* Chat Area */}
        <ChatInterface 
          messages={messages} 
          onCardClick={handleCardClick} 
        />

        {/* Input Area */}
        <InputArea 
            onSendMessage={handleUserMessage} 
            disabled={isAgentThinking} 
        />

        {/* --- OVERLAYS --- */}
        {overlay.type === 'script_editor' && (
          <ScriptEditor 
            initialData={overlay.data} 
            onClose={() => setOverlay({ type: 'none' })}
            onConfirm={handleScriptSave} 
          />
        )}

        {overlay.type === 'image_viewer' && (
          <ImageViewer
            initialImage={overlay.data.initialImage}
            allImages={overlay.data.allImages}
            onClose={() => setOverlay({ type: 'none' })}
            onUpdate={handleImageUpdate}
          />
        )}

        {overlay.type === 'video_player' && (
            <VideoPlayer
                thumbnail={overlay.data.thumbnail}
                onClose={() => setOverlay({ type: 'none' })}
            />
        )}

      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { X, Check, ArrowLeft, Send, Sparkles, GripVertical, Trash2, Play, RefreshCw, Wand2 } from 'lucide-react';
import { ScriptData, ScriptLine, StoryboardImage } from '../types';

/* --- BOTTOM SHEET: SCRIPT EDITOR --- */
interface ScriptEditorProps {
  initialData: ScriptData;
  onClose: () => void;
  onConfirm: (newData: ScriptData) => void;
}

export const ScriptEditor: React.FC<ScriptEditorProps> = ({ initialData, onClose, onConfirm }) => {
  const [lines, setLines] = useState<ScriptLine[]>(initialData.lines);
  const [isClosing, setIsClosing] = useState(false);
  const [aiPrompt, setAiPrompt] = useState('');
  const [isAiProcessing, setIsAiProcessing] = useState(false);

  const handleClose = () => {
    setIsClosing(true);
    setTimeout(onClose, 300);
  };

  const handleSave = () => {
    setIsClosing(true);
    setTimeout(() => onConfirm({ ...initialData, lines }), 300);
  };

  const handleTextChange = (id: string, field: 'visual' | 'audio', val: string) => {
    setLines(lines.map(l => l.id === id ? { ...l, [field]: val } : l));
  };

  const handleDeleteLine = (id: string) => {
    setLines(lines.filter(l => l.id !== id));
  };

  const handleAiEdit = () => {
      if (!aiPrompt.trim()) return;
      setIsAiProcessing(true);

      // Simulate AI processing delay
      setTimeout(() => {
          // Mock logic: modify the second line if it exists, or the first
          setLines(prev => prev.map((line, idx) => {
              if (idx === 1 || (prev.length === 1 && idx === 0)) {
                  return {
                      ...line,
                      visual: line.visual + " (AI 已根据指令优化)"
                  };
              }
              return line;
          }));
          setIsAiProcessing(false);
          setAiPrompt('');
      }, 1500);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center">
      {/* Backdrop */}
      <div 
        className={`absolute inset-0 bg-black/40 backdrop-blur-sm transition-opacity duration-300 ${isClosing ? 'opacity-0' : 'opacity-100'}`} 
        onClick={handleClose}
      />

      {/* Sheet */}
      <div className={`relative w-full max-w-lg bg-white rounded-t-3xl shadow-2xl flex flex-col max-h-[90vh] transition-transform duration-300 transform ${isClosing ? 'translate-y-full' : 'translate-y-0'}`}>
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-gray-100">
          <div className="w-9" /> {/* Spacer to keep title centered */}
          <span className="font-bold text-gray-900">编辑脚本</span>
          <button onClick={handleSave} className="p-2 text-indigo-600 font-medium hover:bg-indigo-50 rounded-full">
            <Check size={20} />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 pb-24">
          {lines.map((line, index) => (
            <div key={line.id} className="flex gap-3 items-start group relative">
              <div className="mt-4 text-gray-300 cursor-move">
                <GripVertical size={20} />
              </div>
              <div className="flex-1 bg-gray-50 rounded-xl p-3 border border-gray-200 focus-within:border-indigo-400 focus-within:ring-1 focus-within:ring-indigo-100 transition-all">
                <div className="flex justify-between items-center mb-2">
                    <div className="flex gap-2 text-xs font-bold text-gray-500 uppercase tracking-wide">
                        <span>分镜 {index + 1}</span>
                        <span className="bg-gray-200 px-1.5 rounded text-gray-600">{line.duration}</span>
                    </div>
                    {/* Delete Button */}
                    <button 
                        onClick={() => handleDeleteLine(line.id)}
                        className="text-gray-400 hover:text-red-500 p-1 rounded-full transition-colors"
                    >
                        <Trash2 size={14} />
                    </button>
                </div>

                <div className="space-y-3">
                  <div>
                    <label className="block text-[10px] text-indigo-500 font-semibold mb-1">画面</label>
                    <textarea 
                      value={line.visual}
                      onChange={(e) => handleTextChange(line.id, 'visual', e.target.value)}
                      className="w-full bg-white rounded-lg p-2 text-sm text-gray-800 border-none focus:ring-0 resize-none h-16 shadow-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] text-orange-500 font-semibold mb-1">声音</label>
                    <textarea 
                      value={line.audio}
                      onChange={(e) => handleTextChange(line.id, 'audio', e.target.value)}
                      className="w-full bg-white rounded-lg p-2 text-sm text-gray-600 border-none focus:ring-0 resize-none h-12 italic shadow-sm"
                    />
                  </div>
                </div>
              </div>
            </div>
          ))}
          {lines.length === 0 && (
             <div className="text-center py-10 text-gray-400 text-sm">没有分镜了。添加一个？</div>
          )}
        </div>

        {/* AI Input Area */}
        <div className="absolute bottom-0 left-0 right-0 p-4 bg-white/95 backdrop-blur border-t border-gray-100 rounded-b-3xl">
           <div className={`flex items-center gap-2 bg-gray-50 border border-gray-200 rounded-full px-2 py-1.5 pl-4 transition-all ${isAiProcessing ? 'opacity-80' : ''}`}>
              <Wand2 size={16} className={`text-indigo-500 ${isAiProcessing ? 'animate-spin' : ''}`} />
              <input 
                 type="text"
                 value={aiPrompt}
                 onChange={(e) => setAiPrompt(e.target.value)}
                 onKeyDown={(e) => e.key === 'Enter' && handleAiEdit()}
                 placeholder={isAiProcessing ? "AI 正在思考..." : "告诉 AI 如何修改脚本 (例如: 把第二段更具动感)..."}
                 disabled={isAiProcessing}
                 className="flex-1 bg-transparent border-none text-sm text-gray-800 placeholder:text-gray-400 focus:ring-0 p-0 h-9"
              />
              <button 
                onClick={handleAiEdit}
                disabled={!aiPrompt || isAiProcessing}
                className={`w-9 h-9 rounded-full flex items-center justify-center transition-colors ${aiPrompt && !isAiProcessing ? 'bg-indigo-600 text-white shadow-md' : 'bg-gray-200 text-gray-400'}`}
              >
                 <Send size={16} className={aiPrompt && !isAiProcessing ? "ml-0.5" : ""} />
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

/* --- FULLSCREEN IMAGE EDITOR --- */
interface ImageViewerProps {
  initialImage: StoryboardImage;
  allImages?: StoryboardImage[];
  onClose: () => void;
  onUpdate: (newImg: StoryboardImage) => void;
}

export const ImageViewer: React.FC<ImageViewerProps> = ({ initialImage, allImages = [], onClose, onUpdate }) => {
  const [prompt, setPrompt] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  // Track the full list locally so we can update other thumbnails if needed, though mostly for display navigation
  const [sessionImages, setSessionImages] = useState<StoryboardImage[]>(allImages.length ? allImages : [initialImage]);
  const [currentIdx, setCurrentIdx] = useState(0);

  // Init index
  useEffect(() => {
    const idx = sessionImages.findIndex(img => img.id === initialImage.id);
    if (idx !== -1) setCurrentIdx(idx);
  }, []);

  const currentImg = sessionImages[currentIdx];

  const handleMagicEdit = () => {
    if (!prompt) return;
    setIsLoading(true);
    // Simulate generation
    setTimeout(() => {
      const newImg = {
        ...currentImg,
        src: `https://picsum.photos/400/600?random=${Date.now()}`, // Force new image
        description: prompt // Update description to match user intent
      };

      // Update local session state
      const newSessionImages = [...sessionImages];
      newSessionImages[currentIdx] = newImg;
      setSessionImages(newSessionImages);

      // Persist to parent
      onUpdate(newImg);

      setIsLoading(false);
      setPrompt('');
    }, 1500);
  };

  const handleSwitchImage = (idx: number) => {
      setCurrentIdx(idx);
      setPrompt(''); // Clear prompt input on switch
  };

  return (
    <div className="fixed inset-0 z-50 bg-black flex flex-col animate-in fade-in duration-300">
      {/* Top Bar */}
      <div className="absolute top-0 left-0 right-0 p-4 pt-safe z-10 flex justify-between items-center bg-gradient-to-b from-black/80 to-transparent">
        <button onClick={onClose} className="text-white/80 hover:text-white p-2">
          <ArrowLeft size={24} />
        </button>
        <span className="text-white font-medium text-sm">分镜编辑器</span>
        <button 
            onClick={onClose} 
            className="text-black bg-white px-4 py-1.5 rounded-full text-xs font-bold hover:bg-gray-200 transition-colors"
        >
            完成
        </button>
      </div>

      {/* Main Image Area */}
      <div className="flex-1 flex items-center justify-center relative w-full h-full bg-gray-900 pb-20">
         {isLoading && (
            <div className="absolute inset-0 z-20 flex flex-col items-center justify-center bg-black/60 backdrop-blur-sm">
                <RefreshCw className="w-8 h-8 text-indigo-500 animate-spin mb-3" />
                <p className="text-white text-sm font-medium animate-pulse">正在重新生成...</p>
            </div>
         )}
         <img 
            src={currentImg?.src} 
            alt="Full view" 
            className={`max-w-full max-h-full object-contain transition-opacity duration-500 ${isLoading ? 'opacity-50' : 'opacity-100'}`}
         />
      </div>

      {/* Bottom Floating Input (Magic Edit) */}
      <div className="absolute bottom-0 left-0 right-0 p-4 pb-safe bg-gradient-to-t from-black/90 via-black/50 to-transparent">
        <div className="flex flex-col gap-2 max-w-md mx-auto">
            {/* Thumbnails Navigation */}
            {sessionImages.length > 1 && (
                <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2 justify-center">
                    {sessionImages.map((img, idx) => (
                        <div 
                            key={img.id}
                            onClick={() => handleSwitchImage(idx)}
                            className={`relative w-10 h-16 flex-shrink-0 rounded-md overflow-hidden border-2 cursor-pointer transition-all ${currentIdx === idx ? 'border-indigo-500 scale-105' : 'border-white/20 opacity-60 hover:opacity-100'}`}
                        >
                            <img src={img.src} className="w-full h-full object-cover" />
                        </div>
                    ))}
                </div>
            )}

           {/* Prompt Peek */}
           <div className="text-[10px] text-white/50 px-2 truncate flex items-center gap-1">
              <span className="bg-white/10 px-1 rounded">提示词</span> 
              {currentImg?.prompt}
           </div>

           <div className="flex items-center gap-2 bg-white/10 backdrop-blur-xl border border-white/20 rounded-full px-1 py-1 pl-4 shadow-lg">
              <Sparkles size={16} className="text-indigo-400" />
              <input 
                type="text"
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="修改角度、光照、风格..."
                className="flex-1 bg-transparent border-none text-white text-sm focus:ring-0 placeholder:text-white/40 h-10"
              />
              <button 
                onClick={handleMagicEdit}
                disabled={!prompt || isLoading}
                className={`w-9 h-9 rounded-full flex items-center justify-center transition-colors ${prompt ? 'bg-indigo-600 text-white' : 'bg-white/5 text-white/20'}`}
              >
                <Send size={16} />
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

