/* --- AUDIO SELECTION CARD --- */
interface AudioSelectionCardProps {
  options: AudioOption[];
  onSelect: (id: string) => void;
}

export const AudioSelectionCard: React.FC<AudioSelectionCardProps> = ({ options, onSelect }) => {
  const [playingId, setPlayingId] = React.useState<string | null>(null);

  const togglePlay = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setPlayingId(playingId === id ? null : id);
    // In real app, would handle Audio object here
  };

  return (
    <div className="flex flex-col gap-2 w-full max-w-[85%]">
      {options.map((opt) => (
        <div 
          key={opt.id}
