import React, { useState, useEffect } from 'react';
import { X, Check, ArrowLeft, Send, Sparkles, GripVertical, Trash2, Play, RefreshCw, Wand2 } from 'lucide-react';
import { ScriptData, ScriptLine, StoryboardImage } from '../types';

/* --- BOTTOM SHEET: SCRIPT EDITOR --- */
interface ScriptEditorProps {
  initialData: ScriptData;
  onClose: () => void;
  onConfirm: (newData: ScriptData) => void;
}

export const ScriptEditor: React.FC<ScriptEditorProps> = ({ initialData, onClose, onConfirm }) => {
  const [lines, setLines] = useState<ScriptLine[]>(initialData.lines);
  const [isClosing, setIsClosing] = useState(false);
  const [aiPrompt, setAiPrompt] = useState('');
  const [isAiProcessing, setIsAiProcessing] = useState(false);

  const handleClose = () => {
    setIsClosing(true);
    setTimeout(onClose, 300);
  };

  const handleSave = () => {
    setIsClosing(true);
    setTimeout(() => onConfirm({ ...initialData, lines }), 300);
  };

  const handleTextChange = (id: string, field: 'visual' | 'audio', val: string) => {
    setLines(lines.map(l => l.id === id ? { ...l, [field]: val } : l));
  };

  const handleDeleteLine = (id: string) => {
    setLines(lines.filter(l => l.id !== id));
  };

  const handleAiEdit = () => {
      if (!aiPrompt.trim()) return;
      setIsAiProcessing(true);

      // Simulate AI processing delay
      setTimeout(() => {
          // Mock logic: modify the second line if it exists, or the first
          setLines(prev => prev.map((line, idx) => {
              if (idx === 1 || (prev.length === 1 && idx === 0)) {
                  return {
                      ...line,
                      visual: line.visual + " (AI 已根据指令优化)"
                  };
              }
              return line;
          }));
          setIsAiProcessing(false);
          setAiPrompt('');
      }, 1500);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center">
      {/* Backdrop */}
      <div 
        className={`absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity duration-300 ${isClosing ? 'opacity-0' : 'opacity-100'}`} 
        onClick={handleClose}
      />

      {/* Sheet */}
      <div className={`relative w-full max-w-lg bg-gray-900 rounded-t-3xl shadow-2xl flex flex-col max-h-[90vh] transition-transform duration-300 transform ${isClosing ? 'translate-y-full' : 'translate-y-0'} border border-white/10`}>
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-white/5">
          <div className="w-9" /> {/* Spacer to keep title centered */}
          <span className="font-bold text-gray-100">编辑脚本</span>
          <button onClick={handleSave} className="p-2 text-indigo-400 font-medium hover:bg-indigo-900/30 rounded-full">
            <Check size={20} />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 pb-24">
          {lines.map((line, index) => (
            <div key={line.id} className="flex gap-3 items-start group relative">
              <div className="mt-4 text-gray-600 cursor-move hover:text-gray-400">
                <GripVertical size={20} />
              </div>
              <div className="flex-1 bg-gray-800 rounded-xl p-3 border border-white/5 focus-within:border-indigo-500/50 focus-within:ring-1 focus-within:ring-indigo-500/20 transition-all">
                <div className="flex justify-between items-center mb-2">
                    <div className="flex gap-2 text-xs font-bold text-gray-400 uppercase tracking-wide">
                        <span>分镜 {index + 1}</span>
                        <span className="bg-gray-700 px-1.5 rounded text-gray-300">{line.duration}</span>
                    </div>
                    {/* Delete Button */}
                    <button 
                        onClick={() => handleDeleteLine(line.id)}
                        className="text-gray-500 hover:text-red-400 p-1 rounded-full transition-colors"
                    >
                        <Trash2 size={14} />
                    </button>
                </div>

                <div className="space-y-3">
                  <div>
                    <label className="block text-[10px] text-indigo-400 font-semibold mb-1">画面</label>
                    <textarea 
                      value={line.visual}
                      onChange={(e) => handleTextChange(line.id, 'visual', e.target.value)}
                      className="w-full bg-gray-700 rounded-lg p-2 text-sm text-gray-200 border-none focus:ring-0 resize-none h-16 shadow-inner placeholder-gray-500"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] text-orange-400 font-semibold mb-1">声音</label>
                    <textarea 
                      value={line.audio}
                      onChange={(e) => handleTextChange(line.id, 'audio', e.target.value)}
                      className="w-full bg-gray-700 rounded-lg p-2 text-sm text-gray-400 border-none focus:ring-0 resize-none h-12 italic shadow-inner placeholder-gray-500"
                    />
                  </div>
                </div>
              </div>
            </div>
          ))}
          {lines.length === 0 && (
             <div className="text-center py-10 text-gray-500 text-sm">没有分镜了。添加一个？</div>
          )}
        </div>

        {/* AI Input Area */}
        <div className="absolute bottom-0 left-0 right-0 p-4 bg-gray-900/95 backdrop-blur border-t border-white/5 rounded-b-3xl">
           <div className={`flex items-center gap-2 bg-gray-800 border border-white/10 rounded-full px-2 py-1.5 pl-4 transition-all ${isAiProcessing ? 'opacity-80' : ''}`}>
              <Wand2 size={16} className={`text-indigo-400 ${isAiProcessing ? 'animate-spin' : ''}`} />
              <input 
                 type="text"
                 value={aiPrompt}
                 onChange={(e) => setAiPrompt(e.target.value)}
                 onKeyDown={(e) => e.key === 'Enter' && handleAiEdit()}
                 placeholder={isAiProcessing ? "AI 正在思考..." : "告诉 AI 如何修改脚本..."}
                 disabled={isAiProcessing}
                 className="flex-1 bg-transparent border-none text-sm text-gray-200 placeholder:text-gray-500 focus:ring-0 p-0 h-9"
              />
              <button 
                onClick={handleAiEdit}
                disabled={!aiPrompt || isAiProcessing}
                className={`w-9 h-9 rounded-full flex items-center justify-center transition-colors ${aiPrompt && !isAiProcessing ? 'bg-indigo-600 text-white shadow-md' : 'bg-gray-700 text-gray-500'}`}
              >
                 <Send size={16} className={aiPrompt && !isAiProcessing ? "ml-0.5" : ""} />
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

/* --- FULLSCREEN IMAGE EDITOR --- */
interface ImageViewerProps {
  initialImage: StoryboardImage;
  allImages?: StoryboardImage[];
  onClose: () => void;
  onUpdate: (newImg: StoryboardImage) => void;
}

export const ImageViewer: React.FC<ImageViewerProps> = ({ initialImage, allImages = [], onClose, onUpdate }) => {
  const [prompt, setPrompt] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  // Track the full list locally so we can update other thumbnails if needed, though mostly for display navigation
  const [sessionImages, setSessionImages] = useState<StoryboardImage[]>(allImages.length ? allImages : [initialImage]);
  const [currentIdx, setCurrentIdx] = useState(0);

  // Init index
  useEffect(() => {
    const idx = sessionImages.findIndex(img => img.id === initialImage.id);
    if (idx !== -1) setCurrentIdx(idx);
  }, []);

  const currentImg = sessionImages[currentIdx];

  const handleMagicEdit = () => {
    if (!prompt) return;
    setIsLoading(true);
    // Simulate generation
    setTimeout(() => {
      const newImg = {
        ...currentImg,
        src: `https://picsum.photos/400/600?random=${Date.now()}`, // Force new image
        description: prompt // Update description to match user intent
      };

      // Update local session state
      const newSessionImages = [...sessionImages];
      newSessionImages[currentIdx] = newImg;
      setSessionImages(newSessionImages);

      // Persist to parent
      onUpdate(newImg);

      setIsLoading(false);
      setPrompt('');
    }, 1500);
  };

  const handleSwitchImage = (idx: number) => {
      setCurrentIdx(idx);
      setPrompt(''); // Clear prompt input on switch
  };

  return (
    <div className="fixed inset-0 z-50 bg-black flex flex-col animate-in fade-in duration-300">
      {/* Top Bar */}
      <div className="absolute top-0 left-0 right-0 p-4 pt-safe z-10 flex justify-between items-center bg-gradient-to-b from-black/80 to-transparent">
        <button onClick={onClose} className="text-white/80 hover:text-white p-2">
          <ArrowLeft size={24} />
        </button>
        <span className="text-white font-medium text-sm">分镜编辑器</span>
        <button 
            onClick={onClose} 
            className="text-black bg-white px-4 py-1.5 rounded-full text-xs font-bold hover:bg-gray-200 transition-colors"
        >
            完成
        </button>
      </div>

      {/* Main Image Area */}
      <div className="flex-1 flex items-center justify-center relative w-full h-full bg-gray-900 pb-20">
         {isLoading && (
            <div className="absolute inset-0 z-20 flex flex-col items-center justify-center bg-black/60 backdrop-blur-sm">
                <RefreshCw className="w-8 h-8 text-indigo-500 animate-spin mb-3" />
                <p className="text-white text-sm font-medium animate-pulse">正在重新生成...</p>
            </div>
         )}
         <img 
            src={currentImg?.src} 
            alt="Full view" 
            className={`max-w-full max-h-full object-contain transition-opacity duration-500 ${isLoading ? 'opacity-50' : 'opacity-100'}`}
         />
      </div>

      {/* Bottom Floating Input (Magic Edit) */}
      <div className="absolute bottom-0 left-0 right-0 p-4 pb-safe bg-gradient-to-t from-black/90 via-black/50 to-transparent">
        <div className="flex flex-col gap-2 max-w-md mx-auto">
            {/* Thumbnails Navigation */}
            {sessionImages.length > 1 && (
                <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2 justify-center">
                    {sessionImages.map((img, idx) => (
                        <div 
                            key={img.id}
                            onClick={() => handleSwitchImage(idx)}
                            className={`relative w-10 h-16 flex-shrink-0 rounded-md overflow-hidden border-2 cursor-pointer transition-all ${currentIdx === idx ? 'border-indigo-500 scale-105' : 'border-white/20 opacity-60 hover:opacity-100'}`}
                        >
                            <img src={img.src} className="w-full h-full object-cover" />
                        </div>
                    ))}
                </div>
            )}

           {/* Prompt Peek */}
           <div className="text-[10px] text-white/50 px-2 truncate flex items-center gap-1">
              <span className="bg-white/10 px-1 rounded">提示词</span> 
              {currentImg?.prompt}
           </div>

           <div className="flex items-center gap-2 bg-white/10 backdrop-blur-xl border border-white/20 rounded-full px-1 py-1 pl-4 shadow-lg">
              <Sparkles size={16} className="text-indigo-400" />
              <input 
                type="text"
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="修改角度、光照、风格..."
                className="flex-1 bg-transparent border-none text-white text-sm focus:ring-0 placeholder:text-white/40 h-10"
              />
              <button 
                onClick={handleMagicEdit}
                disabled={!prompt || isLoading}
                className={`w-9 h-9 rounded-full flex items-center justify-center transition-colors ${prompt ? 'bg-indigo-600 text-white' : 'bg-white/5 text-white/20'}`}
              >
                <Send size={16} />
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

/* --- FULLSCREEN VIDEO PLAYER --- */
interface VideoPlayerProps {
    thumbnail: string;
    onClose: () => void;
}

export const VideoPlayer: React.FC<VideoPlayerProps> = ({ thumbnail, onClose }) => {
    const [isPlaying, setIsPlaying] = useState(true);
    const [magicInput, setMagicInput] = useState("");
    const [status, setStatus] = useState<'idle' | 'processing'>('idle');

    const handleMagicFix = () => {
        if(!magicInput) return;
        setStatus('processing');
        setTimeout(() => {
            setStatus('idle');
            setMagicInput("");
        }, 2000);
    };

    return (
        <div className="fixed inset-0 z-50 bg-black flex flex-col animate-in slide-in-from-bottom duration-300">
             <div className="absolute top-0 left-0 right-0 p-4 pt-safe z-10 flex justify-between items-center pointer-events-none">
                <button onClick={onClose} className="bg-black/20 backdrop-blur-lg border border-white/10 rounded-full p-2 text-white pointer-events-auto hover:bg-black/40">
                     <X size={20} />
                </button>
             </div>

             {/* Mock Video Surface */}
             <div className="flex-1 relative bg-gray-900 flex items-center justify-center" onClick={() => setIsPlaying(!isPlaying)}>
                {/* We use an image to simulate the video for this demo */}
                <img src={thumbnail} className="w-full h-full object-cover opacity-80" />

                {!isPlaying && (
                    <div className="absolute inset-0 flex items-center justify-center bg-black/20 backdrop-blur-[2px]">
                        <div className="w-16 h-16 bg-white/20 rounded-full flex items-center justify-center backdrop-blur-md">
                            <Play size={32} fill="white" className="text-white ml-1" />
                        </div>
                    </div>
                )}

                {/* Processing Overlay */}
                {status === 'processing' && (
                     <div className="absolute inset-0 bg-black/80 backdrop-blur-sm flex flex-col items-center justify-center z-20">
                        <div className="w-12 h-12 border-4 border-white/10 border-t-green-500 rounded-full animate-spin mb-4" />
                        <span className="text-white font-medium">正在应用魔法修改...</span>
                     </div>
                )}
             </div>

             {/* Controls & Magic Edit */}
             <div className="absolute bottom-0 w-full p-4 pb-safe bg-gradient-to-t from-black via-black/60 to-transparent">
                 <div className="mb-4">
                     {/* Fake Scrubber */}
                     <div className="h-1 bg-white/30 rounded-full w-full mb-2 cursor-pointer">
                         <div className="h-full w-1/3 bg-white rounded-full relative">
                             <div className="absolute right-0 top-1/2 -translate-y-1/2 w-3 h-3 bg-white rounded-full shadow" />
                         </div>
                     </div>
                     <div className="flex justify-between text-[10px] text-white/60 font-mono">
                         <span>0:05</span>
                         <span>0:30</span>
                     </div>
                 </div>

                 <div className="flex items-center gap-3">
                     <div className="flex-1 bg-gray-800/80 backdrop-blur-md rounded-2xl flex items-center p-1 border border-white/10 shadow-lg">
                        <input 
                            value={magicInput} 
                            onChange={(e) => setMagicInput(e.target.value)}
                            className="flex-1 bg-transparent border-none text-white text-sm px-3 py-2 placeholder:text-gray-400 focus:ring-0"
                            placeholder="修改字幕颜色..."
                        />
                        <button 
                            onClick={handleMagicFix}
                            disabled={!magicInput}
                            className={`p-2 rounded-xl text-white transition-colors ${magicInput ? 'bg-indigo-600 hover:bg-indigo-500' : 'bg-white/5 text-white/30'}`}
                        >
                            <Sparkles size={16} />
                        </button>
                     </div>
                 </div>
             </div>
        </div>
    );
}

