  { id: 'img3', src: 'https://picsum.photos/400/600?random=3', description: '赛博筷子', prompt: 'Mechanical hand holding chopsticks, food close up, macro lens, cyberpunk' },
];

export const AVATAR_URL = "https://picsum.photos/100/100?grayscale";

import React, { useState } from 'react';
import { Play, FileText, Clock, Layers, Music, Image as ImageIcon, Sparkles, ArrowRight, CheckCircle2, Mic, Users, RefreshCw } from 'lucide-react';
import { ScriptData, StoryboardImage, AudioOption, CharacterDesign } from '../types';

/* --- CHARACTER CARD --- */
interface CharacterSelectionCardProps {
  characters: CharacterDesign[];
  onConfirm: () => void;
}

export const CharacterSelectionCard: React.FC<CharacterSelectionCardProps> = ({ characters, onConfirm }) => {
  const [items, setItems] = useState(characters);
  const [regeneratingId, setRegeneratingId] = useState<string | null>(null);

  const handleRegenerate = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setRegeneratingId(id);
    setTimeout(() => {
        setItems(prev => prev.map(c => 
            c.id === id ? { ...c, imageUrl: `https://picsum.photos/200/200?random=${Date.now()}` } : c
        ));
        setRegeneratingId(null);
    }, 1000);
  };

  return (
    <div className="w-full max-w-[90%] flex flex-col gap-2">
      <div className="bg-gray-900 rounded-2xl p-4 shadow-sm border border-white/10">
        <div className="flex items-center gap-2 mb-4">
            <div className="p-1.5 bg-pink-900/30 rounded-lg">
                <Users size={18} className="text-pink-400" />
            </div>
            <span className="text-xs font-bold text-gray-300 uppercase tracking-wide">角色定妆</span>
        </div>

        <div className="flex gap-3 overflow-x-auto no-scrollbar pb-2">
            {items.map(char => (
                <div key={char.id} className="flex flex-col gap-2 w-28 shrink-0">
                    <div className="relative aspect-square rounded-xl overflow-hidden bg-gray-800 border border-white/5 group">
                        <img 
                            src={char.imageUrl} 
                            alt={char.name} 
                            className={`w-full h-full object-cover transition-all duration-500 ${regeneratingId === char.id ? 'opacity-50 scale-90 blur-sm' : ''}`} 
                        />
                        <button 
                            onClick={(e) => handleRegenerate(e, char.id)}
                            className="absolute inset-0 flex items-center justify-center bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity backdrop-blur-[1px]"
                        >
                            <RefreshCw size={20} className={`text-white ${regeneratingId === char.id ? 'animate-spin' : ''}`} />
                        </button>
                    </div>
                    <div>
                        <div className="text-xs font-bold text-gray-200 truncate">{char.name}</div>
                        <div className="text-[10px] text-gray-500 truncate">{char.description}</div>
                    </div>
                </div>
            ))}
        </div>
      </div>

       <button 
        onClick={onConfirm}
        className="self-end flex items-center gap-2 bg-pink-600 hover:bg-pink-700 text-white text-xs font-bold px-4 py-2.5 rounded-xl shadow-md transition-all active:scale-95 border border-transparent"
      >
        <span>确认角色设定</span>
        <ArrowRight size={14} />
      </button>
    </div>
  );
};

/* --- SCRIPT CARD --- */
interface ScriptCardProps {
  data: ScriptData;
  onClick: () => void;
  onConfirm: () => void;
}

export const ScriptCard: React.FC<ScriptCardProps> = ({ data, onClick, onConfirm }) => (
  <div className="w-full max-w-[85%] flex flex-col gap-2">
    <div 
      onClick={onClick}
      className="bg-gray-900 rounded-2xl p-4 shadow-sm border border-white/10 cursor-pointer active:scale-98 transition-transform group relative overflow-hidden"
    >
      <div className="flex items-start justify-between mb-3">
        <div className="flex items-center gap-2 text-indigo-400">
          <div className="p-1.5 bg-indigo-900/30 rounded-lg">
            <FileText size={18} />
          </div>
          <span className="text-xs font-bold uppercase tracking-wide">脚本已生成</span>
        </div>
        <div className="text-[10px] bg-gray-800 px-2 py-1 rounded-full text-gray-400 font-medium group-hover:bg-indigo-900/40 group-hover:text-indigo-400 transition-colors">
          点击编辑
        </div>
      </div>

      <h3 className="text-base font-bold text-gray-100 mb-1 leading-tight">{data.title}</h3>

      <div className="flex items-center gap-4 text-xs text-gray-500 mt-3">
        <div className="flex items-center gap-1">
          <Clock size={14} />
          <span>{data.totalDuration}</span>
        </div>
        <div className="flex items-center gap-1">
          <Layers size={14} />
          <span>{data.sceneCount} 个分镜</span>
        </div>
      </div>
    </div>

    {/* Confirm Action Button - Outside the edit card to separate concerns */}
    <button 
      onClick={(e) => { e.stopPropagation(); onConfirm(); }}
      className="self-end flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white text-xs font-bold px-4 py-2.5 rounded-xl shadow-md transition-all active:scale-95 border border-transparent"
    >
      <span>确认并生成分镜</span>
      <ArrowRight size={14} />
    </button>
  </div>
);

/* --- CAROUSEL / STORYBOARD CARD --- */
interface StoryboardCardProps {
  images: StoryboardImage[];
  onImageClick: (img: StoryboardImage) => void;
}

export const StoryboardCard: React.FC<StoryboardCardProps> = ({ images, onImageClick }) => (
  <div className="bg-gray-900 rounded-2xl p-3 shadow-sm border border-white/10 w-full max-w-[95%] overflow-hidden">
    <div className="flex items-center gap-2 mb-3 px-1">
      <div className="p-1.5 bg-purple-900/30 rounded-lg">
        <ImageIcon size={14} className="text-purple-400" />
      </div>
      <span className="text-xs font-bold text-gray-400 uppercase tracking-wide">分镜预览</span>
    </div>
    <div className="flex overflow-x-auto gap-3 pb-2 no-scrollbar snap-x px-1">
      {images.map((img) => (
        <div 
          key={img.id}
          onClick={() => onImageClick(img)}
          className="snap-center shrink-0 w-32 flex flex-col gap-2 cursor-pointer group"
        >
          <div className="relative aspect-[9/16] rounded-xl overflow-hidden shadow-sm bg-gray-800 border border-white/5">
            <img src={img.src} alt={img.description} className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition-opacity" />
            <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors" />
            <div className="absolute bottom-2 right-2 bg-black/60 p-1 rounded-full text-white backdrop-blur-sm">
              <Sparkles size={10} />
            </div>
          </div>
          <p className="text-[10px] leading-tight text-gray-400 font-medium line-clamp-2 px-0.5">{img.description}</p>
        </div>
      ))}
    </div>
  </div>
);

/* --- AUDIO SELECTION CARD --- */
interface AudioSelectionCardProps {
  options: AudioOption[];
  onSelect: (id: string) => void;
}

export const AudioSelectionCard: React.FC<AudioSelectionCardProps> = ({ options, onSelect }) => {
  const [playingId, setPlayingId] = React.useState<string | null>(null);

  const togglePlay = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setPlayingId(playingId === id ? null : id);
    // In real app, would handle Audio object here
  };

  return (
    <div className="bg-gray-900 rounded-2xl p-3 shadow-sm border border-white/10 w-full max-w-[85%]">
      <div className="flex items-center gap-2 mb-3 px-1">
        <div className="p-1.5 bg-orange-900/30 rounded-lg">
          <Mic size={14} className="text-orange-400" />
        </div>
        <span className="text-xs font-bold text-gray-400 uppercase tracking-wide">配音选择</span>
      </div>

      <div className="flex flex-col gap-2">
        {options.map((opt) => (
          <div 
            key={opt.id}
            onClick={() => onSelect(opt.id)}
            className={`relative flex items-center gap-3 p-3 rounded-xl border transition-all cursor-pointer ${
              opt.selected 
                ? 'bg-indigo-900/20 border-indigo-500/50 ring-1 ring-indigo-500/30' 
                : 'bg-gray-800/50 border-white/5 hover:border-indigo-500/30'
            }`}
          >
            <button
              onClick={(e) => togglePlay(e, opt.id)}
              className={`flex-shrink-0 w-10 h-10 rounded-full flex items-center justify-center transition-colors ${
                playingId === opt.id ? 'bg-indigo-600 text-white' : 'bg-gray-800 text-gray-400 border border-white/10'
              }`}
            >
              {playingId === opt.id ? (
                <div className="flex gap-0.5 items-end h-3">
                  <div className="w-1 bg-white animate-[pulse_0.5s_ease-in-out_infinite] h-full" />
                  <div className="w-1 bg-white animate-[pulse_0.7s_ease-in-out_infinite] h-2/3" />
                  <div className="w-1 bg-white animate-[pulse_0.6s_ease-in-out_infinite] h-full" />
                </div>
              ) : (
                <Play size={18} fill="currentColor" />
              )}
            </button>

            <div className="flex-1 min-w-0">
              <h4 className={`text-sm font-semibold ${opt.selected ? 'text-indigo-300' : 'text-gray-200'}`}>
                {opt.name}
              </h4>
              <p className="text-xs text-gray-500 truncate">{opt.description}</p>
            </div>

            {opt.selected && (
              <div className="w-4 h-4 rounded-full bg-indigo-600 flex items-center justify-center">
                <div className="w-1.5 h-1.5 bg-white rounded-full" />
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

/* --- VIDEO RESULT CARD --- */
interface VideoCardProps {
  thumbnail: string;
  duration: string;
  onClick: () => void;
}

export const VideoCard: React.FC<VideoCardProps> = ({ thumbnail, duration, onClick }) => (
  <div onClick={onClick} className="w-full max-w-[70%] cursor-pointer group">
    <div className="relative aspect-[9/16] rounded-2xl overflow-hidden shadow-lg bg-black border border-gray-800">
      <img src={thumbnail} alt="Video Result" className="w-full h-full object-cover opacity-80 group-hover:opacity-60 transition-opacity" />
      <div className="absolute inset-0 flex items-center justify-center">
        <div className="w-16 h-16 rounded-full bg-white/20 backdrop-blur-md flex items-center justify-center group-hover:scale-110 transition-transform">
           <Play size={32} fill="white" className="text-white ml-1" />
        </div>
      </div>
      <div className="absolute bottom-3 right-3 bg-black/60 px-2 py-1 rounded text-xs text-white font-mono">
        {duration}
      </div>
      <div className="absolute top-3 left-3 bg-green-500 px-2 py-1 rounded-full text-[10px] text-white font-bold uppercase tracking-wider shadow-sm">
        完成
      </div>
    </div>
  </div>
);

import React, { useEffect, useRef } from 'react';
import { Message } from '../types';
import { AVATAR_URL } from '../constants';
import { ScriptCard, StoryboardCard, AudioSelectionCard, VideoCard, CharacterSelectionCard } from './ImmersiveCards';

interface ChatInterfaceProps {
  messages: Message[];
  onCardClick: (msgId: string, action: string, data?: any) => void;
}

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ messages, onCardClick }) => {
  const bottomRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom on new message
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages.length, messages[messages.length - 1]?.isLoading]);

  return (
    <div className="flex-1 overflow-y-auto px-4 py-4 space-y-6">
      {/* Intro Spacer */}
      <div className="h-4"></div>

      {messages.map((msg) => (
        <div 
          key={msg.id} 
          className={`flex gap-3 w-full animate-in slide-in-from-bottom-2 duration-500 ${
            msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'
          }`}
        >
          {/* Avatar (Agent Only) */}
          {msg.role === 'agent' && (
            <div className="flex-shrink-0 w-8 h-8 rounded-full overflow-hidden mt-1 shadow-sm border border-white/10">
              <img src={AVATAR_URL} alt="Agent" className="w-full h-full object-cover" />
            </div>
          )}

          {/* Content Container */}
          <div className={`flex flex-col gap-2 max-w-full ${
            msg.role === 'user' ? 'items-end' : 'items-start'
          } flex-1 min-w-0`}>

            {/* Text Bubble */}
            {msg.text && (
              <div 
                className={`px-4 py-2.5 rounded-2xl text-[15px] leading-relaxed max-w-[85%] shadow-sm border ${
                  msg.role === 'user' 
                    ? 'bg-indigo-600 text-white border-transparent rounded-br-none' 
                    : 'bg-gray-900 text-gray-100 border-white/10 rounded-bl-none'
                }`}
              >
                {msg.text}
              </div>
            )}

            {/* Loading Indicator */}
            {msg.isLoading && (
               <div className="bg-gray-900 px-4 py-3 rounded-2xl rounded-bl-none border border-white/10 shadow-sm flex items-center gap-1.5">
                  <div className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                  <div className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                  <div className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce"></div>
               </div>
            )}

            {/* Rich Cards based on Type */}
            {!msg.isLoading && msg.type === 'character_card' && msg.characterData && (
              <CharacterSelectionCard 
                characters={msg.characterData} 
                onConfirm={() => onCardClick(msg.id, 'confirm_characters')}
              />
            )}

            {!msg.isLoading && msg.type === 'script_card' && msg.scriptData && (
              <ScriptCard 
                data={msg.scriptData} 
                onClick={() => onCardClick(msg.id, 'open_script', msg.scriptData)}
                onConfirm={() => onCardClick(msg.id, 'confirm_script', msg.scriptData)}
              />
            )}

            {!msg.isLoading && msg.type === 'storyboard_card' && msg.storyboardData && (
              <StoryboardCard 
                images={msg.storyboardData} 
                onImageClick={(img) => onCardClick(msg.id, 'view_image', { initialImage: img, allImages: msg.storyboardData })}
              />
            )}

            {!msg.isLoading && msg.type === 'audio_selection' && msg.audioOptions && (
              <AudioSelectionCard 
                options={msg.audioOptions} 
                onSelect={(id) => onCardClick(msg.id, 'select_audio', id)}
              />
            )}

            {!msg.isLoading && msg.type === 'video_card' && msg.videoData && (
                <VideoCard 
                    thumbnail={msg.videoData.thumbnail}
                    duration={msg.videoData.duration}
                    onClick={() => onCardClick(msg.id, 'play_video', msg.videoData)}
                />
            )}
          </div>
        </div>
      ))}
      <div ref={bottomRef} />
    </div>
  );
};

import React, { useState, useCallback } from 'react';
import { Message, MessageType, OverlayState, ScriptData, StoryboardImage, VideoSegment } from './types';
import { ChatInterface } from './components/ChatInterface';
import { InputArea } from './components/InputArea';
import { ScriptEditor, ImageViewer, VideoPlayer } from './components/Overlays';
import { MOCK_SCRIPT, MOCK_STORYBOARD, MOCK_CHARACTERS } from './constants';

export default function App() {
  const [messages, setMessages] = useState<Message[]>([
    { 
      id: 'init', 
      role: 'agent', 
      type: 'text', 
      text: '嗨！今天想制作什么视频？', 
      timestamp: Date.now() 
    }
  ]);
  const [overlay, setOverlay] = useState<OverlayState>({ type: 'none' });
  const [isAgentThinking, setIsAgentThinking] = useState(false);

  // --- Helper to add message ---
  const addMsg = (msg: Partial<Message>) => {
    setMessages(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      role: 'agent',
      type: 'text',
      ...msg
    } as Message]);
  };

  // --- AGENT STATE MACHINE (MOCK) ---
  const handleUserMessage = async (text: string) => {
    // 1. Add User Message
    addMsg({ role: 'user', text, type: 'text' });

    // 2. Simulate Thinking
    setIsAgentThinking(true);

    // Add a temporary loading bubble
    const loadingId = 'loading-' + Date.now();
    setMessages(prev => [...prev, { id: loadingId, role: 'agent', type: 'text', isLoading: true, timestamp: Date.now() }]);

    // 3. Determine Response based on context (Simple sequential flow for demo)
    setTimeout(() => {
      // Remove loading bubble
      setMessages(prev => prev.filter(m => m.id !== loadingId));
      setIsAgentThinking(false);

      const lastType = messages.filter(m => m.role === 'agent' && m.type !== 'text').pop()?.type;

      if (!lastType) {
        // Step 1: Character Extraction & Design (New Flow)
        addMsg({ role: 'agent', text: '我提取了主要角色设定，点击图片可重新生成，确认后继续。' });
        addMsg({ role: 'agent', type: 'character_card', characterData: MOCK_CHARACTERS });
      } else if (lastType === 'character_card') {
          // Fallback if user chats after characters without clicking confirm
          addMsg({ role: 'agent', text: '请先确认角色设定，我们将根据角色生成脚本。' });
      } else if (lastType === 'script_card') {
          // Fallback if they type after script
          addMsg({ role: 'agent', text: '请先确认上方的脚本，以便生成分镜。' });
      } else if (lastType === 'storyboard_card') {
          addMsg({ role: 'agent', text: '我可以更新图片。长按查看详情或点击进行魔法编辑。' });
      } else {
         addMsg({ role: 'agent', text: '正在处理！' });
      }

    }, 1500);
  };

  // --- INTERACTION HANDLERS ---
  const handleCardClick = useCallback((msgId: string, action: string, data?: any) => {
    if (action === 'confirm_characters') {
        // Step 2: Proceed to Script Generation after Characters are confirmed
        setIsAgentThinking(true);
        setTimeout(() => {
            setIsAgentThinking(false);
            addMsg({ role: 'agent', text: '角色已确认！基于此设定，我草拟了一份脚本：' });
            addMsg({ role: 'agent', type: 'script_card', scriptData: MOCK_SCRIPT });
        }, 1000);
    } else if (action === 'open_script') {
      setOverlay({ type: 'script_editor', data: data });
    } else if (action === 'confirm_script') {
        const scriptData = data as ScriptData;
        // Proceed to Storyboard Generation
        setIsAgentThinking(true);
        setTimeout(() => {
             setIsAgentThinking(false);
             addMsg({ role: 'agent', text: '脚本已确认。正在生成分镜...' });

             // Generate Storyboard Data based on Script Lines
            const generatedStoryboard: StoryboardImage[] = scriptData.lines.map((line) => ({
                id: `img-${line.id}`,
                src: `https://picsum.photos/400/600?random=${line.id}-${Date.now()}`, 
                prompt: line.visual,
                description: line.visual.length > 50 ? line.visual.substring(0, 47) + '...' : line.visual
            }));

            setTimeout(() => {
                addMsg({ 
                    role: 'agent', 
                    type: 'storyboard_card', 
                    storyboardData: generatedStoryboard.length > 0 ? generatedStoryboard : MOCK_STORYBOARD 
                });

                setTimeout(() => {
                    addMsg({ role: 'agent', text: '分镜已就绪。请选择配音风格：' });
                    addMsg({ 
                        role: 'agent', 
                        type: 'audio_selection',
                        audioOptions: [
                            { id: '1', name: '磁性男声', description: '深沉稳重，适合电影叙事', previewUrl: '' },
                            { id: '2', name: '活力少女', description: '明快活泼，适合 Vlog', previewUrl: '' },
                            { id: '3', name: '赛博 AI', description: '电子合成音，冷酷未来感', previewUrl: '' }
                        ]
                    });
                }, 1000);
            }, 1500);
        }, 500);
    } else if (action === 'view_image') {
      // Data contains { initialImage, allImages }
      setOverlay({ type: 'image_viewer', data: data });
    } else if (action === 'select_audio') {
        // User selected audio, move to Video Generation
        setMessages(prev => prev.map(m => 
             m.type === 'audio_selection' 
             ? { ...m, audioOptions: m.audioOptions?.map(o => ({...o, selected: o.id === data}))} 
             : m
        ));

        // Trigger Video Generation
        setTimeout(() => {
            addMsg({ role: 'agent', text: '很好的选择！正在渲染最终视频...' });
            // Simulate waiting
            setTimeout(() => {
                // Mock segments based on existing storyboard or script lines
                const segments: VideoSegment[] = MOCK_STORYBOARD.map((img, idx) => ({
                    id: `seg-${idx}`,
                    thumbnail: img.src,
                    duration: ['5s', '10s', '8s'][idx] || '5s',
                    description: img.description
                }));

                addMsg({ 
                    role: 'agent', 
                    type: 'video_card', 
                    videoData: {
                        thumbnail: MOCK_STORYBOARD[0].src, 
                        videoUrl: '#',
                        duration: '23s',
                        segments: segments
                    } 
                });
            }, 2500);
        }, 500);
    } else if (action === 'play_video') {
        setOverlay({ type: 'video_player', data: data });
    }
  }, [messages]);

  // Rename this to represent SAVING data, not next step
  const handleScriptSave = (newData: ScriptData) => {
    setOverlay({ type: 'none' });

    // Only update the message in chat history to reflect changes
    // Do NOT trigger storyboard generation here
    setMessages(prev => prev.map(m => 
       m.type === 'script_card' ? { ...m, scriptData: newData } : m
    ));
  };

  const handleImageUpdate = (updatedImg: StoryboardImage) => {
     // Persist changes from ImageViewer back to the main chat
     setMessages(prev => prev.map(msg => {
         if (msg.type === 'storyboard_card' && msg.storyboardData) {
             return {
                 ...msg,
                 storyboardData: msg.storyboardData.map(img => 
                     img.id === updatedImg.id ? updatedImg : img
                 )
             };
         }
         return msg;
     }));
  };

  return (
    <div className="flex justify-center bg-black h-screen w-screen overflow-hidden">
      {/* Mobile Container */}
      <div className="w-full max-w-md h-full bg-gray-950 flex flex-col relative shadow-2xl overflow-hidden md:border-x border-gray-800">

        {/* Header */}
        <header className="flex items-center justify-center p-4 bg-gray-900/80 backdrop-blur-md sticky top-0 z-10 border-b border-white/5">
           <h1 className="font-bold text-gray-100 tracking-tight">AI 导演</h1>
        </header>

        {/* Chat Area */}
        <ChatInterface 
          messages={messages} 
          onCardClick={handleCardClick} 
        />

        {/* Input Area */}
        <InputArea 
            onSendMessage={handleUserMessage} 
            disabled={isAgentThinking} 
        />

        {/* --- OVERLAYS --- */}
        {overlay.type === 'script_editor' && (
          <ScriptEditor 
            initialData={overlay.data} 
            onClose={() => setOverlay({ type: 'none' })}
            onConfirm={handleScriptSave} 
          />
        )}

        {overlay.type === 'image_viewer' && (
          <ImageViewer
            initialImage={overlay.data.initialImage}
            allImages={overlay.data.allImages}
            onClose={() => setOverlay({ type: 'none' })}
            onUpdate={handleImageUpdate}
          />
        )}

        {overlay.type === 'video_player' && (
            <VideoPlayer
                thumbnail={overlay.data.thumbnail}
                segments={overlay.data.segments}
                onClose={() => setOverlay({ type: 'none' })}
            />
        )}

      </div>
    </div>
  );
}

