<change>
<file>components/VideoPlayer.tsx</file>
<description>Update VideoPlayer to correctly display video segments and thumbnails.</description>
<content><![CDATA[import React, { useState, useEffect } from 'react';
import { VideoSegment } from '../types';
import './VideoPlayer.css';

interface VideoPlayerProps {
    thumbnail: string;
    segments: VideoSegment[];
    onClose: () => void;
}

const VideoPlayer: React.FC<VideoPlayerProps> = ({ thumbnail, segments, onClose }) => {
    const [currentSegmentIndex, setCurrentSegmentIndex] = useState(0);
    const [currentTime, setCurrentTime] = useState(0);
    const [isPlaying, setIsPlaying] = useState(false);
    const [videoElement, setVideoElement] = useState<HTMLVideoElement | null>(null);

    useEffect(() => {
        if (videoElement) {
            videoElement.addEventListener('timeupdate', handleTimeUpdate);
            videoElement.addEventListener('ended', handleVideoEnd);
            return () => {
                videoElement.removeEventListener('timeupdate', handleTimeUpdate);
                videoElement.removeEventListener('ended', handleVideoEnd);
            };
        }
    }, [videoElement]);

    const handleTimeUpdate = () => {
        if (videoElement) {
            setCurrentTime(videoElement.currentTime);
        }
    };

    const handleVideoEnd = () => {
        if(currentSegmentIndex < segments.length - 1) {
            setCurrentSegmentIndex(currentSegmentIndex + 1);
        } else {
            setIsPlaying(false); // Stop playing when all segments are finished
        }
    };

    const togglePlay = () => {
        if (!videoElement) return;
        if (isPlaying) {
            videoElement.pause();
        } else {
            videoElement.play();
        }
        setIsPlaying(!isPlaying);
    };

    const handleSegmentClick = (index: number) => {
        setCurrentSegmentIndex(index);
        setCurrentTime(0); // Reset time to the start of the selected segment
        if (videoElement) {
            videoElement.currentTime = 0; // Reset video to the beginning
            videoElement.play(); // Play from the start of the clicked segment
        }
    };

    const handleCloseClick = () => {
        onClose();
    };

    const currentSegment = segments[currentSegmentIndex];

    const formatTime = (timeInSeconds: number) => {
        const minutes = Math.floor(timeInSeconds / 60);
        const seconds = Math.floor(timeInSeconds % 60);
        return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
    };

    return (
        <div className="video-player-overlay">
            <div className="video-player-content">
                <button className="close-button" onClick={handleCloseClick}>X</button>
                <h2>Video Player</h2>
                <div className="video-container">
                <video
                    ref={setVideoElement}
                    controls
                    style={{ width: '100%', height: 'auto' }}
                    poster={currentSegment?.thumbnail || thumbnail} // Use the thumbnail from the current segment
                >
                  {/* Provide sources for the video (replace with your video sources) */}
                    <source src={currentSegment?.video_url} type="video/mp4" />
                    Your browser does not support the video tag.
                </video>
                  </div>
                <div className="controls">
                    <button onClick={togglePlay}>{isPlaying ? 'Pause' : 'Play'}</button>
                    <span>{formatTime(currentTime)} / {formatTime(currentSegment?.duration || 0)}</span>
                </div>
                <div className="segment-list">
                    {segments.map((segment, index) => (
                        <div key={index} className="segment-item" onClick={() => handleSegmentClick(index)}>
                          <img src={segment.thumbnail} alt={`Segment ${index}`} style={{width: '50px', height: 'auto'}} />
                          <span>{`Segment ${index + 1}`}</span>


**Reviewing Mock Segments**

I'm now revising the `VideoPlayer` component, especially to display the mock video segments and thumbnails. The plan involves making the thumbnails and the interface more responsive to the user's actions, and I'm currently focusing on the parameters `duration` and `segments`. I'll be implementing the changes specified in the `VideoPlayer.tsx` file to get started.


