// Message Roles and Types
export type Role = 'user' | 'agent';
export type MessageType = 'text' | 'character_card' | 'script_card' | 'storyboard_card' | 'audio_selection' | 'video_card' | 'system_notification';

// Data Structures for Payload
export interface CharacterDesign {
  id: string;
  name: string;
  description: string;
  imageUrl: string;
}

export interface ScriptLine {
  id: string;
  scene: number;
  duration: string;
  visual: string;
  audio: string;
}

export interface ScriptData {
  title: string;
  totalDuration: string;
  sceneCount: number;
  lines: ScriptLine[];
}

export interface StoryboardImage {
  id: string;
  src: string;
  prompt: string;
  description: string;
}

export interface AudioOption {
  id: string;
  name: string;
  description: string;
  previewUrl: string; // Mock URL
  selected?: boolean;
}

export interface VideoSegment {
  id: string;
  thumbnail: string;
  duration: string;
  description: string;
}

// Main Message Interface
export interface Message {
  id: string;
  role: Role;
  type: MessageType;
  text?: string;
  timestamp: number;
  isLoading?: boolean;

  // Specific Payloads
  characterData?: CharacterDesign[];
  scriptData?: ScriptData;
  storyboardData?: StoryboardImage[];
  audioOptions?: AudioOption[];
  videoData?: {
    thumbnail: string;
    videoUrl: string;
    duration: string;
    segments?: VideoSegment[];
  };
}

// Overlay State Management
export type OverlayType = 'none' | 'script_editor' | 'image_viewer' | 'video_player' | 'character_viewer';

export interface OverlayState {
  type: OverlayType;
  data?: any; // Context data for the overlay
}

import React, { useState, useEffect } from 'react';
import { Play, FileText, Clock, Layers, Music, Image as ImageIcon, Sparkles, ArrowRight, CheckCircle2, Mic, Users, RefreshCw, ChevronDown, ChevronUp, Maximize2 } from 'lucide-react';
import { ScriptData, StoryboardImage, AudioOption, CharacterDesign } from '../types';

/* --- CHARACTER CARD --- */
interface CharacterSelectionCardProps {
  characters: CharacterDesign[];
  onConfirm: () => void;
  onCharacterClick: (char: CharacterDesign) => void;
}

export const CharacterSelectionCard: React.FC<CharacterSelectionCardProps> = ({ characters, onConfirm, onCharacterClick }) => {
  const [items, setItems] = useState(characters);
  const [regeneratingId, setRegeneratingId] = useState<string | null>(null);

  // Sync internal state if props change (e.g. after editing in overlay)
  useEffect(() => {
      setItems(characters);
  }, [characters]);

  const handleRegenerate = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setRegeneratingId(id);
    setTimeout(() => {
        setItems(prev => prev.map(c => 
            c.id === id ? { ...c, imageUrl: `https://picsum.photos/200/200?random=${Date.now()}` } : c
        ));
        setRegeneratingId(null);
    }, 1000);
  };

  return (
    <div className="w-full max-w-[90%] flex flex-col gap-2">
      <div className="bg-gray-900 rounded-2xl p-4 shadow-sm border border-white/10">
        <div className="flex items-center gap-2 mb-4">
            <div className="p-1.5 bg-pink-900/30 rounded-lg">
                <Users size={18} className="text-pink-400" />
            </div>
            <span className="text-xs font-bold text-gray-300 uppercase tracking-wide">角色定妆</span>
        </div>

        <div className="flex gap-3 overflow-x-auto no-scrollbar pb-2">
            {items.map(char => (
                <div key={char.id} className="flex flex-col gap-2 w-28 shrink-0">
                    <div 
                        className="relative aspect-square rounded-xl overflow-hidden bg-gray-800 border border-white/5 group cursor-pointer"
                        onClick={() => onCharacterClick(char)}
                    >
                        <img 
                            src={char.imageUrl} 
                            alt={char.name} 
                            className={`w-full h-full object-cover transition-all duration-500 group-hover:scale-105 ${regeneratingId === char.id ? 'opacity-50 scale-90 blur-sm' : ''}`} 
                        />

                        {/* View Indicator */}
                        <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-colors flex items-center justify-center opacity-0 group-hover:opacity-100">
                             <Maximize2 size={20} className="text-white drop-shadow-md" />
                        </div>

                        {/* Quick Regenerate Button (Corner) */}
                        <button 
                            onClick={(e) => handleRegenerate(e, char.id)}
                            className="absolute top-1.5 right-1.5 p-1.5 bg-black/50 hover:bg-black/70 rounded-full text-white/80 hover:text-white backdrop-blur-sm opacity-0 group-hover:opacity-100 transition-all transform active:scale-90"
                        >
                            <RefreshCw size={12} className={regeneratingId === char.id ? 'animate-spin' : ''} />
                        </button>
                    </div>
                    <div>
                        <div className="text-xs font-bold text-gray-200 truncate">{char.name}</div>
                        <div className="text-[10px] text-gray-500 truncate">{char.description}</div>
                    </div>
                </div>
            ))}
        </div>
      </div>

       <button 
        onClick={onConfirm}
        className="self-end flex items-center gap-2 bg-pink-600 hover:bg-pink-700 text-white text-xs font-bold px-4 py-2.5 rounded-xl shadow-md transition-all active:scale-95 border border-transparent"
      >
        <span>确认并生成主体角色</span>
        <ArrowRight size={14} />
      </button>
    </div>
  );
};

/* --- SCRIPT CARD --- */
interface ScriptCardProps {
  data: ScriptData;
  onClick?: () => void;
  onConfirm: () => void;
  onSave: (newData: ScriptData) => void;
}

export const ScriptCard: React.FC<ScriptCardProps> = ({ data, onClick, onConfirm, onSave }) => {
  const [expanded, setExpanded] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [localLines, setLocalLines] = useState(data.lines);

  // Sync if data changes externally
  useEffect(() => {
    setLocalLines(data.lines);
  }, [data]);

  const handleToggleEdit = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (isEditing) {
      // Save changes
      onSave({ ...data, lines: localLines });
      setIsEditing(false);
    } else {
      // Enter edit mode
      setIsEditing(true);
      setExpanded(true); // Auto-expand when editing
    }
  };

  const handleLineChange = (id: string, field: 'visual' | 'audio', val: string) => {
    setLocalLines(prev => prev.map(l => l.id === id ? { ...l, [field]: val } : l));
  };

  return (
    <div className="w-full max-w-[90%] flex flex-col gap-2">
      <div className={`bg-gray-900 rounded-2xl p-4 shadow-sm border border-white/10 relative transition-all duration-300 ${isEditing ? 'ring-1 ring-indigo-500/50 bg-gray-900/95' : ''}`}>

        {/* Header */}
        <div className="flex items-start justify-between mb-3">
          <div className="flex flex-col gap-1">
            <div className="flex items-center gap-2 text-indigo-400">
              <div className="p-1.5 bg-indigo-900/30 rounded-lg">
                <FileText size={18} />
              </div>
              <span className="text-xs font-bold uppercase tracking-wide">
                {isEditing ? '编辑脚本' : '脚本已生成'}
              </span>
            </div>
            <h3 className="text-base font-bold text-gray-100 mt-1">{data.title}</h3>

            {!isEditing && (
              <div className="flex items-center gap-3 text-[10px] text-gray-500">
                <div className="flex items-center gap-1">
                  <Clock size={12} />
                  <span>{data.totalDuration}</span>
                </div>
                <div className="flex items-center gap-1">
                  <Layers size={12} />
                  <span>{data.sceneCount} 个分镜</span>
                </div>
              </div>
            )}
          </div>

          <button 
             onClick={handleToggleEdit}
             className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full font-medium transition-colors border ${
                 isEditing 
                 ? 'bg-indigo-600 text-white border-transparent hover:bg-indigo-500 shadow-lg' 
                 : 'bg-gray-800 text-gray-300 border-white/5 hover:bg-indigo-900/40 hover:text-indigo-400'
             }`}
           >
             {isEditing ? (
                 <>
                    <CheckCircle2 size={14} />
                    <span className="text-[10px] font-bold">完成</span>
                 </>
             ) : (
                 <span className="text-[10px]">点击编辑</span>
             )}
           </button>
        </div>

        {/* Script Content Lines */}
        <div className={`relative flex flex-col gap-2 transition-all duration-500 ease-in-out ${expanded || isEditing ? 'max-h-[1000px]' : 'max-h-[120px] overflow-hidden'}`}>
           {localLines.map((line, idx) => (
             <div key={line.id} className="flex gap-3 bg-gray-800/40 p-3 rounded-xl border border-white/5 group">
                <div className="text-xs font-bold text-gray-600 pt-0.5 min-w-[20px]">
                    {idx + 1}.
                </div>
                <div className="flex flex-col gap-2 flex-1 min-w-0">
                    <div className="flex items-start gap-2">
                         <span className="text-[10px] text-indigo-400 font-medium bg-indigo-900/20 px-1.5 py-0.5 rounded shrink-0 mt-0.5">画面</span>
                         {isEditing ? (
                             <textarea 
                                value={line.visual}
                                onChange={(e) => handleLineChange(line.id, 'visual', e.target.value)}
                                className="flex-1 bg-gray-900 border border-white/10 rounded-lg p-2 text-xs text-gray-200 focus:outline-none focus:border-indigo-500/50 resize-none h-[50px] leading-relaxed"
                             />
                         ) : (
                             <p className="text-xs text-gray-300 leading-relaxed pt-0.5">{line.visual}</p>
                         )}
                    </div>
                    <div className="flex items-start gap-2">
                         <span className="text-[10px] text-orange-400 font-medium bg-orange-900/20 px-1.5 py-0.5 rounded shrink-0 mt-0.5">声音</span>
                         {isEditing ? (
                             <textarea 
                                value={line.audio}
                                onChange={(e) => handleLineChange(line.id, 'audio', e.target.value)}
                                className="flex-1 bg-gray-900 border border-white/10 rounded-lg p-2 text-xs text-gray-300 focus:outline-none focus:border-orange-500/50 resize-none h-[50px] italic leading-relaxed"
                             />
                         ) : (
                             <p className="text-xs text-gray-400 leading-relaxed italic pt-0.5">{line.audio}</p>
                         )}
                    </div>
                </div>
             </div>
           ))}

           {/* Fade Out Mask (Only when NOT expanded and NOT editing) */}
           {!expanded && !isEditing && (
             <div className="absolute inset-x-0 bottom-0 h-16 bg-gradient-to-t from-gray-900 via-gray-900/90 to-transparent pointer-events-none" />
           )}
        </div>

        {/* Expand Toggle */}
        {!isEditing && (
            <div 
                onClick={() => setExpanded(!expanded)}
                className="flex justify-center mt-2 -mb-1 cursor-pointer text-gray-500 hover:text-gray-300 transition-colors py-1 active:scale-95"
            >
                {expanded ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
            </div>
        )}
      </div>

      {/* Confirm Action Button */}
      {!isEditing && (
        <button 
            onClick={(e) => { e.stopPropagation(); onConfirm(); }}
            className="self-end flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white text-xs font-bold px-4 py-2.5 rounded-xl shadow-md transition-all active:scale-95 border border-transparent"
        >
            <span>确认并生成主体角色</span>
            <ArrowRight size={14} />
        </button>
      )}
    </div>
  );
};

