import React, { useEffect, useRef } from 'react';
import { Message } from '../types';
import { AVATAR_URL } from '../constants';
import { ScriptCard, StoryboardCard, AudioSelectionCard, VideoCard, CharacterSelectionCard } from './ImmersiveCards';

interface ChatInterfaceProps {
  messages: Message[];
  onCardClick: (msgId: string, action: string, data?: any) => void;
}

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ messages, onCardClick }) => {
  const bottomRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom on new message
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages.length, messages[messages.length - 1]?.isLoading]);

  return (
    <div className="flex-1 overflow-y-auto px-4 py-4 space-y-6 custom-scrollbar">
      {/* Intro Spacer */}
      <div className="h-4"></div>

      {messages.map((msg) => (
        <div 
          key={msg.id} 
          className={`flex gap-3 w-full animate-in slide-in-from-bottom-2 duration-500 ${
            msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'
          }`}
        >
          {/* Avatar (Agent Only) */}
          {msg.role === 'agent' && (
            <div className="flex-shrink-0 w-8 h-8 rounded-full overflow-hidden mt-1 shadow-sm border border-white/10">
              <img src={AVATAR_URL} alt="Agent" className="w-full h-full object-cover" />
            </div>
          )}

          {/* Content Container */}
          <div className={`flex flex-col gap-2 max-w-full ${
            msg.role === 'user' ? 'items-end' : 'items-start'
          } flex-1 min-w-0`}>

            {/* Text Bubble */}
            {msg.text && (
              <div 
                className={`px-4 py-2.5 rounded-2xl text-[15px] leading-relaxed max-w-[85%] shadow-sm border ${
                  msg.role === 'user' 
                    ? 'bg-indigo-600 text-white border-transparent rounded-br-none' 
                    : 'bg-gray-900 text-gray-100 border-white/10 rounded-bl-none'
                }`}
              >
                {msg.text}
              </div>
            )}

            {/* Loading Indicator */}
            {msg.isLoading && (
               <div className="bg-gray-900 px-4 py-3 rounded-2xl rounded-bl-none border border-white/10 shadow-sm flex items-center gap-1.5">
                  <div className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                  <div className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                  <div className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce"></div>
               </div>
            )}

            {/* Rich Cards based on Type */}
            {!msg.isLoading && msg.type === 'character_card' && msg.characterData && (
              <CharacterSelectionCard 
                characters={msg.characterData} 
                onConfirm={() => onCardClick(msg.id, 'confirm_characters')}
                onCharacterClick={(char) => onCardClick(msg.id, 'view_character', { initialCharacter: char, allCharacters: msg.characterData })}
              />
            )}

            {!msg.isLoading && msg.type === 'script_card' && msg.scriptData && (
              <ScriptCard 
                data={msg.scriptData} 
                onConfirm={() => onCardClick(msg.id, 'confirm_script', msg.scriptData)}
                onSave={(newData) => onCardClick(msg.id, 'save_script', newData)}
              />
            )}

            {!msg.isLoading && msg.type === 'storyboard_card' && msg.storyboardData && (
              <StoryboardCard 
                images={msg.storyboardData} 
                onImageClick={(img) => onCardClick(msg.id, 'view_image', { initialImage: img, allImages: msg.storyboardData })}
              />
            )}

            {!msg.isLoading && msg.type === 'audio_selection' && msg.audioOptions && (
              <AudioSelectionCard 
                options={msg.audioOptions} 
                onSelect={(id) => onCardClick(msg.id, 'select_audio', id)}
              />
            )}

            {!msg.isLoading && msg.type === 'video_card' && msg.videoData && (
                <VideoCard 
                    thumbnail={msg.videoData.thumbnail}
                    duration={msg.videoData.duration}
                    onClick={() => onCardClick(msg.id, 'play_video', msg.videoData)}
                />
            )}
          </div>
        </div>
      ))}
      <div ref={bottomRef} />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { X, Check, ArrowLeft, Send, Sparkles, GripVertical, Trash2, Play, RefreshCw, Wand2, Film, MessageSquare, ChevronRight, ChevronLeft } from 'lucide-react';
import { ScriptData, ScriptLine, StoryboardImage, VideoSegment, CharacterDesign } from '../types';

/* --- BOTTOM SHEET: SCRIPT EDITOR --- */
interface ScriptEditorProps {
  initialData: ScriptData;
  onClose: () => void;
  onConfirm: (newData: ScriptData) => void;
}

export const ScriptEditor: React.FC<ScriptEditorProps> = ({ initialData, onClose, onConfirm }) => {
  const [lines, setLines] = useState<ScriptLine[]>(initialData.lines);
  const [isClosing, setIsClosing] = useState(false);
  const [aiPrompt, setAiPrompt] = useState('');
  const [isAiProcessing, setIsAiProcessing] = useState(false);

  const handleClose = () => {
    setIsClosing(true);
    setTimeout(onClose, 300);
  };

  const handleSave = () => {
    setIsClosing(true);
    setTimeout(() => onConfirm({ ...initialData, lines }), 300);
  };

  const handleTextChange = (id: string, field: 'visual' | 'audio', val: string) => {
    setLines(lines.map(l => l.id === id ? { ...l, [field]: val } : l));
  };

  const handleDeleteLine = (id: string) => {
    setLines(lines.filter(l => l.id !== id));
  };

  const handleAiEdit = () => {
      if (!aiPrompt.trim()) return;
      setIsAiProcessing(true);

      // Simulate AI processing delay
      setTimeout(() => {
          // Mock logic: modify the second line if it exists, or the first
          setLines(prev => prev.map((line, idx) => {
              if (idx === 1 || (prev.length === 1 && idx === 0)) {
                  return {
                      ...line,
                      visual: line.visual + " (AI 已根据指令优化)"
                  };
              }
              return line;
          }));
          setIsAiProcessing(false);
          setAiPrompt('');
      }, 1500);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center">
      {/* Backdrop */}
      <div 
        className={`absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity duration-300 ${isClosing ? 'opacity-0' : 'opacity-100'}`} 
        onClick={handleClose}
      />

      {/* Sheet */}
      <div className={`relative w-full max-w-lg bg-gray-900 rounded-t-3xl shadow-2xl flex flex-col max-h-[90vh] transition-transform duration-300 transform ${isClosing ? 'translate-y-full' : 'translate-y-0'} border border-white/10`}>
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-white/5">
          <div className="w-9" /> {/* Spacer to keep title centered */}
          <span className="font-bold text-gray-100">编辑脚本</span>
          <button onClick={handleSave} className="p-2 text-indigo-400 font-medium hover:bg-indigo-900/30 rounded-full">
            <Check size={20} />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 pb-24">
          {lines.map((line, index) => (
            <div key={line.id} className="flex gap-3 items-start group relative">
              <div className="mt-4 text-gray-600 cursor-move hover:text-gray-400">
                <GripVertical size={20} />
              </div>
              <div className="flex-1 bg-gray-800 rounded-xl p-3 border border-white/5 focus-within:border-indigo-500/50 focus-within:ring-1 focus-within:ring-indigo-500/20 transition-all">
                <div className="flex justify-between items-center mb-2">
                    <div className="flex gap-2 text-xs font-bold text-gray-400 uppercase tracking-wide">
                        <span>分镜 {index + 1}</span>
                        <span className="bg-gray-700 px-1.5 rounded text-gray-300">{line.duration}</span>
                    </div>
                    {/* Delete Button */}
                    <button 
                        onClick={() => handleDeleteLine(line.id)}
                        className="text-gray-500 hover:text-red-400 p-1 rounded-full transition-colors"
                    >
                        <Trash2 size={14} />
                    </button>
                </div>

                <div className="space-y-3">
                  <div>
                    <label className="block text-[10px] text-indigo-400 font-semibold mb-1">画面</label>
                    <textarea 
                      value={line.visual}
                      onChange={(e) => handleTextChange(line.id, 'visual', e.target.value)}
