                            src={char.imageUrl} 
                            alt={char.name} 
                            className={`w-full h-full object-cover transition-all duration-500 group-hover:scale-105 ${regeneratingId === char.id ? 'opacity-50 scale-90 blur-sm' : ''}`} 
                        />

                        {/* View Indicator */}
                        <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-colors flex items-center justify-center opacity-0 group-hover:opacity-100">
                             <Maximize2 size={20} className="text-white drop-shadow-md" />
                        </div>

                        {/* Quick Regenerate Button (Corner) */}
