/* --- FULLSCREEN CHARACTER VIEWER (SWIPE & AI EDIT) --- */
interface CharacterViewerProps {
  initialCharacter: CharacterDesign;
  allCharacters?: CharacterDesign[];
  onClose: () => void;
  onUpdate: (newChar: CharacterDesign) => void;
}

export const CharacterViewer: React.FC<CharacterViewerProps> = ({ initialCharacter, allCharacters = [], onClose, onUpdate }) => {
  const [prompt, setPrompt] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [sessionChars, setSessionChars] = useState<CharacterDesign[]>(allCharacters.length ? allCharacters : [initialCharacter]);
  const [currentIdx, setCurrentIdx] = useState(0);

  // Swipe State
  const [touchStart, setTouchStart] = useState(0);
  const [touchEnd, setTouchEnd] = useState(0);

  // Init index
  useEffect(() => {
    const idx = sessionChars.findIndex(c => c.id === initialCharacter.id);
    if (idx !== -1) setCurrentIdx(idx);
  }, []);

  const currentChar = sessionChars[currentIdx];

  const handleAiModification = () => {
      if (!prompt) return;
      setIsLoading(true);

      // Simulate AI Processing
      setTimeout(() => {
          const newChar = {
              ...currentChar,
              imageUrl: `https://picsum.photos/200/200?random=${Date.now()}`,
              description: currentChar.description + ` (Modified: ${prompt})`
          };

          const newSessionChars = [...sessionChars];
          newSessionChars[currentIdx] = newChar;
          setSessionChars(newSessionChars);
          onUpdate(newChar);

          setIsLoading(false);
          setPrompt('');
      }, 1500);
  };

  // Navigation Logic
  const handlePrev = () => {
      if (currentIdx > 0) setCurrentIdx(currentIdx - 1);
  };
  const handleNext = () => {
      if (currentIdx < sessionChars.length - 1) setCurrentIdx(currentIdx + 1);
  };

  // Touch Handlers for Swipe
  const handleTouchStart = (e: React.TouchEvent) => setTouchStart(e.targetTouches[0].clientX);
  const handleTouchMove = (e: React.TouchEvent) => setTouchEnd(e.targetTouches[0].clientX);
  const handleTouchEnd = () => {
      if (!touchStart || !touchEnd) return;
      const distance = touchStart - touchEnd;
      const minSwipeDistance = 50;

      if (distance > minSwipeDistance) handleNext(); // Swipe Left -> Next
      if (distance < -minSwipeDistance) handlePrev(); // Swipe Right -> Prev

      setTouchStart(0);
      setTouchEnd(0);
  };

  return (
    <div className="fixed inset-0 z-50 bg-black flex flex-col animate-in zoom-in-95 duration-300">
      {/* Top Bar */}
      <div className="absolute top-0 left-0 right-0 p-4 pt-safe z-10 flex justify-between items-center bg-gradient-to-b from-black/80 to-transparent">
        <button onClick={onClose} className="text-white/80 hover:text-white p-2">
          <ArrowLeft size={24} />
        </button>
        <span className="text-white font-medium text-sm">角色定妆详情</span>
        <button 
            onClick={onClose} 
            className="text-black bg-white px-4 py-1.5 rounded-full text-xs font-bold hover:bg-gray-200 transition-colors"
        >
            完成
        </button>
      </div>

      {/* Main Content Area (Swipeable) */}
      <div 
         className="flex-1 flex flex-col items-center justify-center relative w-full h-full bg-gray-900 pb-20"
         onTouchStart={handleTouchStart}
         onTouchMove={handleTouchMove}
         onTouchEnd={handleTouchEnd}
      >
         {/* Navigation Arrows (Desktop/Visual Hint) */}
         {currentIdx > 0 && (
             <button onClick={handlePrev} className="absolute left-2 top-1/2 -translate-y-1/2 p-2 bg-black/30 rounded-full text-white/50 hover:bg-black/50 hover:text-white z-20">
                 <ChevronLeft size={24} />
             </button>
         )}
         {currentIdx < sessionChars.length - 1 && (
             <button onClick={handleNext} className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-black/30 rounded-full text-white/50 hover:bg-black/50 hover:text-white z-20">
                 <ChevronRight size={24} />
             </button>
         )}

         {/* Image */}
         <div className="relative w-full max-w-sm aspect-square px-4">
             {isLoading && (
                <div className="absolute inset-4 z-20 flex flex-col items-center justify-center bg-black/60 backdrop-blur-sm rounded-2xl">
                    <RefreshCw className="w-8 h-8 text-pink-500 animate-spin mb-3" />
                    <p className="text-white text-sm font-medium animate-pulse">正在调整妆造...</p>
                </div>
             )}
             <img 
                src={currentChar.imageUrl} 
                alt={currentChar.name}
                className={`w-full h-full object-cover rounded-2xl shadow-2xl border border-white/10 transition-opacity duration-500 ${isLoading ? 'opacity-50' : 'opacity-100'}`}
             />
         </div>

         {/* Info */}
         <div className="mt-6 px-6 text-center">
             <h2 className="text-2xl font-bold text-white mb-1">{currentChar.name}</h2>
             <p className="text-gray-400 text-sm">{currentChar.description}</p>
         </div>
      </div>

      {/* Bottom Area: Thumbnails + AI Chat */}
      <div className="absolute bottom-0 left-0 right-0 p-4 pb-safe bg-gradient-to-t from-black/95 via-black/80 to-transparent">
        <div className="flex flex-col gap-3 max-w-md mx-auto">

            {/* Thumbnails */}
            {sessionChars.length > 1 && (
                <div className="flex gap-3 overflow-x-auto no-scrollbar pb-1 justify-center">
                    {sessionChars.map((c, idx) => (
                        <div 
                            key={c.id}
                            onClick={() => { setCurrentIdx(idx); setPrompt(''); }}
                            className={`w-12 h-12 flex-shrink-0 rounded-lg overflow-hidden border-2 cursor-pointer transition-all ${currentIdx === idx ? 'border-pink-500 scale-110' : 'border-white/10 opacity-60'}`}
                        >
                            <img src={c.imageUrl} className="w-full h-full object-cover" />
                        </div>
                    ))}
                </div>
            )}

           {/* AI Chat Input */}
           <div className="flex items-center gap-2 bg-white/10 backdrop-blur-xl border border-white/20 rounded-full px-1 py-1 pl-4 shadow-lg">
              <MessageSquare size={16} className="text-pink-400" />
              <input 
                type="text"
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="告诉 AI 调整发型、服饰..."
                className="flex-1 bg-transparent border-none text-white text-sm focus:ring-0 placeholder:text-white/40 h-10"
              />
              <button 
                onClick={handleAiModification}
                disabled={!prompt || isLoading}
                className={`w-9 h-9 rounded-full flex items-center justify-center transition-colors ${prompt ? 'bg-pink-600 text-white' : 'bg-white/5 text-white/20'}`}
              >
                <Send size={16} />
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

/* --- FULLSCREEN VIDEO PLAYER --- */
interface VideoPlayerProps {
    thumbnail: string;
    segments?: VideoSegment[];
    onClose: () => void;
}

export const VideoPlayer: React.FC<VideoPlayerProps> = ({ thumbnail, segments = [], onClose }) => {
    const [isPlaying, setIsPlaying] = useState(true);
    const [magicInput, setMagicInput] = useState("");
    const [status, setStatus] = useState<'idle' | 'processing'>('idle');
    const [currentSegIdx, setCurrentSegIdx] = useState(0);

    // If no segments provided, create a dummy one based on the main thumbnail
    const activeSegments = segments.length > 0 ? segments : [{
        id: 'main', 
        thumbnail: thumbnail, 
        duration: '0:30', 
        description: 'Main Video'
    }];

    const currentSegment = activeSegments[currentSegIdx];

    const handleMagicFix = () => {
        if(!magicInput) return;
        setStatus('processing');
        // Simulate "fixing" the current segment
        setTimeout(() => {
            setStatus('idle');
            setMagicInput("");
        }, 2000);
    };

    return (
        <div className="fixed inset-0 z-50 bg-black flex flex-col animate-in slide-in-from-bottom duration-300">
             <div className="absolute top-0 left-0 right-0 p-4 pt-safe z-10 flex justify-between items-center pointer-events-none">
                <button onClick={onClose} className="bg-black/20 backdrop-blur-lg border border-white/10 rounded-full p-2 text-white pointer-events-auto hover:bg-black/40">
                     <X size={20} />
                </button>
             </div>

             {/* Mock Video Surface */}
             <div className="flex-1 relative bg-gray-900 flex items-center justify-center overflow-hidden" onClick={() => setIsPlaying(!isPlaying)}>
                {/* We use an image to simulate the video for this demo */}
                <div key={currentSegment.id} className="w-full h-full relative animate-in fade-in duration-500">
                     <img src={currentSegment.thumbnail} className="w-full h-full object-cover opacity-80" />
                </div>

                {!isPlaying && (
                    <div className="absolute inset-0 flex items-center justify-center bg-black/20 backdrop-blur-[2px]">
                        <div className="w-16 h-16 bg-white/20 rounded-full flex items-center justify-center backdrop-blur-md">
                            <Play size={32} fill="white" className="text-white ml-1" />
                        </div>
                    </div>
                )}

                {/* Processing Overlay */}
                {status === 'processing' && (
                     <div className="absolute inset-0 bg-black/80 backdrop-blur-sm flex flex-col items-center justify-center z-20">
                        <div className="w-12 h-12 border-4 border-white/10 border-t-green-500 rounded-full animate-spin mb-4" />
                        <span className="text-white font-medium">正在修改分镜 {currentSegIdx + 1}...</span>
                     </div>
                )}

                {/* Segment Indicator Overlay */}
                <div className="absolute top-20 left-4 bg-black/50 backdrop-blur-md px-3 py-1 rounded-full text-xs text-white/80 border border-white/10 font-mono">
                    Segment {currentSegIdx + 1} / {activeSegments.length} • {currentSegment.duration}
                </div>
             </div>

             {/* Controls & Timeline */}
             <div className="absolute bottom-0 w-full p-4 pb-safe bg-gradient-to-t from-black via-black/80 to-transparent">

                 {/* Timeline Segments */}
                 <div className="mb-6 overflow-x-auto no-scrollbar">
                     <div className="flex gap-2 px-1 min-w-max">
                        {activeSegments.map((seg, idx) => (
                            <div 
                                key={seg.id}
                                onClick={(e) => { e.stopPropagation(); setCurrentSegIdx(idx); }}
                                className={`group relative flex-shrink-0 cursor-pointer flex flex-col gap-1 transition-all ${
                                    currentSegIdx === idx ? 'w-24 opacity-100' : 'w-16 opacity-50 hover:opacity-80'
                                }`}
                            >
                                {/* Thumbnail */}
                                <div className={`h-12 rounded-lg overflow-hidden border-2 ${currentSegIdx === idx ? 'border-indigo-500' : 'border-white/20'}`}>
                                    <img src={seg.thumbnail} className="w-full h-full object-cover" />
                                </div>
                                {/* Label */}
                                <div className="flex justify-between items-center px-0.5">
                                    <span className="text-[9px] text-white/70 font-mono">#{idx + 1}</span>
                                    <span className="text-[9px] text-white/50">{seg.duration}</span>
                                </div>
                            </div>
                        ))}
                     </div>
                 </div>

                 {/* Magic Edit Context Aware */}
                 <div className="flex items-center gap-3">
                     <div className="flex-1 bg-gray-800/80 backdrop-blur-md rounded-2xl flex items-center p-1 border border-white/10 shadow-lg transition-colors focus-within:border-indigo-500/50">
                        <div className="pl-3 pr-1 text-indigo-400">
                             <Sparkles size={14} />
                        </div>
                        <input 
                            value={magicInput} 
                            onChange={(e) => setMagicInput(e.target.value)}
                            className="flex-1 bg-transparent border-none text-white text-sm px-2 py-2 placeholder:text-gray-500 focus:ring-0"
                            placeholder={`调整第 ${currentSegIdx + 1} 个分镜...`}
                        />
                        <button 
                            onClick={handleMagicFix}
                            disabled={!magicInput}
                            className={`p-2 rounded-xl text-white transition-colors ${magicInput ? 'bg-indigo-600 hover:bg-indigo-500' : 'bg-white/5 text-white/30'}`}
                        >
                            <Send size={14} />
                        </button>
                     </div>
                 </div>
             </div>
        </div>
    );
}

