  allImages?: StoryboardImage[];
  onClose: () => void;
  onUpdate: (newImg: StoryboardImage) => void;
}

export const ImageViewer: React.FC<ImageViewerProps> = ({ initialImage, allImages = [], onClose, onUpdate }) => {
  const [prompt, setPrompt] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showSubtitles, setShowSubtitles] = useState(true);

  // Track the full list locally so we can update other thumbnails if needed, though mostly for display navigation
  const [sessionImages, setSessionImages] = useState<StoryboardImage[]>(allImages.length ? allImages : [initialImage]);
  const [currentIdx, setCurrentIdx] = useState(0);

  // Init index
  useEffect(() => {
    const idx = sessionImages.findIndex(img => img.id === initialImage.id);
    if (idx !== -1) setCurrentIdx(idx);
  }, []);

  const currentImg = sessionImages[currentIdx];

  const handleMagicEdit = () => {
    if (!prompt) return;
    setIsLoading(true);
    // Simulate generation
    setTimeout(() => {
      const newImg = {
        ...currentImg,
        src: `https://picsum.photos/400/600?random=${Date.now()}`, // Force new image
        description: prompt // Update description to match user intent
      };

      // Update local session state
      const newSessionImages = [...sessionImages];
      newSessionImages[currentIdx] = newImg;
      setSessionImages(newSessionImages);

      // Persist to parent
      onUpdate(newImg);

      setIsLoading(false);
      setPrompt('');
    }, 1500);
  };

  const handleSwitchImage = (idx: number) => {
      setCurrentIdx(idx);
      setPrompt(''); // Clear prompt input on switch
  };

  return (
    <div className="fixed inset-0 z-50 bg-black flex flex-col animate-in fade-in duration-300">
      {/* Top Bar */}
      <div className="absolute top-0 left-0 right-0 p-4 pt-safe z-10 flex justify-between items-center bg-gradient-to-b from-black/80 to-transparent">
