                onClick={() => setShowSubtitles(!showSubtitles)}
                className={`p-2 rounded-full transition-colors ${showSubtitles ? 'text-white' : 'text-white/50 hover:text-white'}`}
            >
                <Type size={20} />
            </button>
            <button 
                onClick={onClose} 
                className="text-black bg-white px-4 py-1.5 rounded-full text-xs font-bold hover:bg-gray-200 transition-colors ml-1"
            >
                完成
            </button>
        </div>
      </div>

      {/* Main Image Area */}
      <div className="flex-1 flex items-center justify-center relative w-full h-full bg-gray-900 pb-20">
