         {/* Subtitle Overlay - Positioned above the bottom gradient area */}
         {showSubtitles && currentImg.subtitle && (
            <div className="absolute bottom-28 left-4 right-4 text-center pointer-events-none z-20 animate-in fade-in slide-in-from-bottom-2">
                <span className="inline-block bg-black/50 backdrop-blur-[2px] px-4 py-2 rounded-lg text-white text-base font-medium shadow-sm leading-relaxed border border-white/5">
                    {currentImg.subtitle}
                </span>
            </div>
