/* --- FULLSCREEN CHARACTER VIEWER (SWIPE & AI EDIT) --- */
interface CharacterViewerProps {
  initialCharacter: CharacterDesign;
  allCharacters?: CharacterDesign[];
  onClose: () => void;
  onUpdate: (newChar: CharacterDesign) => void;
}

export const CharacterViewer: React.FC<CharacterViewerProps> = ({ initialCharacter, allCharacters = [], onClose, onUpdate }) => {
  const [prompt, setPrompt] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [sessionChars, setSessionChars] = useState<CharacterDesign[]>(allCharacters.length ? allCharacters : [initialCharacter]);
  const [currentIdx, setCurrentIdx] = useState(0);

  // Swipe State
  const [touchStart, setTouchStart] = useState(0);
  const [touchEnd, setTouchEnd] = useState(0);

  // Init index
  useEffect(() => {
    const idx = sessionChars.findIndex(c => c.id === initialCharacter.id);
    if (idx !== -1) setCurrentIdx(idx);
  }, []);

  const currentChar = sessionChars[currentIdx];

  const handleAiModification = () => {
      if (!prompt) return;
      setIsLoading(true);

      // Simulate AI Processing
      setTimeout(() => {
          const newChar = {
              ...currentChar,
              imageUrl: `https://picsum.photos/200/200?random=${Date.now()}`,
              description: currentChar.description + ` (Modified: ${prompt})`
          };

          const newSessionChars = [...sessionChars];
          newSessionChars[currentIdx] = newChar;
          setSessionChars(newSessionChars);
          onUpdate(newChar);

          setIsLoading(false);
          setPrompt('');
      }, 1500);
  };

  // Navigation Logic
  const handlePrev = () => {
      if (currentIdx > 0) setCurrentIdx(currentIdx - 1);
  };
  const handleNext = () => {
      if (currentIdx < sessionChars.length - 1) setCurrentIdx(currentIdx + 1);
  };

  // Touch Handlers for Swipe
  const handleTouchStart = (e: React.TouchEvent) => setTouchStart(e.targetTouches[0].clientX);
  const handleTouchMove = (e: React.TouchEvent) => setTouchEnd(e.targetTouches[0].clientX);
  const handleTouchEnd = () => {
      if (!touchStart || !touchEnd) return;
      const distance = touchStart - touchEnd;
      const minSwipeDistance = 50;

      if (distance > minSwipeDistance) handleNext(); // Swipe Left -> Next
      if (distance < -minSwipeDistance) handlePrev(); // Swipe Right -> Prev

      setTouchStart(0);
      setTouchEnd(0);
  };

  return (
    <div className="fixed inset-0 z-50 bg-black flex flex-col animate-in zoom-in-95 duration-300">
      {/* Top Bar */}
      <div className="absolute top-0 left-0 right-0 p-4 pt-safe z-10 flex justify-between items-center bg-gradient-to-b from-black/80 to-transparent">
        <button onClick={onClose} className="text-white/80 hover:text-white p-2">
          <ArrowLeft size={24} />
        </button>
        <span className="text-white font-medium text-sm">角色定妆详情</span>
        <button 
            onClick={onClose} 
            className="text-black bg-white px-4 py-1.5 rounded-full text-xs font-bold hover:bg-gray-200 transition-colors"
        >
            完成
        </button>
      </div>

      {/* Main Content Area (Swipeable) */}
      <div 
         className="flex-1 flex flex-col items-center justify-center relative w-full h-full bg-gray-900 pb-20"
         onTouchStart={handleTouchStart}
         onTouchMove={handleTouchMove}
         onTouchEnd={handleTouchEnd}
      >
         {/* Navigation Arrows (Desktop/Visual Hint) */}
         {currentIdx > 0 && (
             <button onClick={handlePrev} className="absolute left-2 top-1/2 -translate-y-1/2 p-2 bg-black/30 rounded-full text-white/50 hover:bg-black/50 hover:text-white z-20">
                 <ChevronLeft size={24} />
             </button>
         )}
         {currentIdx < sessionChars.length - 1 && (
             <button onClick={handleNext} className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-black/30 rounded-full text-white/50 hover:bg-black/50 hover:text-white z-20">
                 <ChevronRight size={24} />
             </button>
         )}

         {/* Image */}
         <div className="relative w-full max-w-sm aspect-square px-4">
             {isLoading && (
                <div className="absolute inset-4 z-20 flex flex-col items-center justify-center bg-black/60 backdrop-blur-sm rounded-2xl">
                    <RefreshCw className="w-8 h-8 text-pink-500 animate-spin mb-3" />
                    <p className="text-white text-sm font-medium animate-pulse">正在调整妆造...</p>
                </div>
             )}
             <img 
                src={currentChar.imageUrl} 
                alt={currentChar.name}
                className={`w-full h-full object-cover rounded-2xl shadow-2xl border border-white/10 transition-opacity duration-500 ${isLoading ? 'opacity-50' : 'opacity-100'}`}
             />
         </div>

         {/* Info */}
         <div className="mt-6 px-6 text-center">
             <h2 className="text-2xl font-bold text-white mb-1">{currentChar.name}</h2>
             <p className="text-gray-400 text-sm">{currentChar.description}</p>
         </div>
      </div>

      {/* Bottom Area: Thumbnails + AI Chat */}
      <div className="absolute bottom-0 left-0 right-0 p-4 pb-safe bg-gradient-to-t from-black/95 via-black/80 to-transparent">
        <div className="flex flex-col gap-3 max-w-md mx-auto">

            {/* Thumbnails */}
            {sessionChars.length > 1 && (
                <div className="flex gap-3 overflow-x-auto no-scrollbar pb-1 justify-center">
                    {sessionChars.map((c, idx) => (
                        <div 
                            key={c.id}
                            onClick={() => { setCurrentIdx(idx); setPrompt(''); }}
                            className={`w-12 h-12 flex-shrink-0 rounded-lg overflow-hidden border-2 cursor-pointer transition-all ${currentIdx === idx ? 'border-pink-500 scale-110' : 'border-white/10 opacity-60'}`}
                        >
                            <img src={c.imageUrl} className="w-full h-full object-cover" />
                        </div>
                    ))}
                </div>
            )}

           {/* AI Chat Input */}
           <div className="flex items-center gap-2 bg-white/10 backdrop-blur-xl border border-white/20 rounded-full px-1 py-1 pl-4 shadow-lg">
              <MessageSquare size={16} className="text-pink-400" />
              <input 
                type="text"
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="告诉 AI 调整发型、服饰..."
                className="flex-1 bg-transparent border-none text-white text-sm focus:ring-0 placeholder:text-white/40 h-10"
              />
              <button 
                onClick={handleAiModification}
                disabled={!prompt || isLoading}
                className={`w-9 h-9 rounded-full flex items-center justify-center transition-colors ${prompt ? 'bg-pink-600 text-white' : 'bg-white/5 text-white/20'}`}
              >
                <Send size={16} />
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

/* --- FULLSCREEN VIDEO PLAYER --- */
interface VideoPlayerProps {
    thumbnail: string;
    segments?: VideoSegment[];
    onClose: () => void;
}

export const VideoPlayer: React.FC<VideoPlayerProps> = ({ thumbnail, segments = [], onClose }) => {
    const [isPlaying, setIsPlaying] = useState(true);
    const [magicInput, setMagicInput] = useState("");
    const [status, setStatus] = useState<'idle' | 'processing'>('idle');
    const [currentSegIdx, setCurrentSegIdx] = useState(0);

    // If no segments provided, create a dummy one based on the main thumbnail
    const activeSegments = segments.length > 0 ? segments : [{
        id: 'main', 
        thumbnail: thumbnail, 
        duration: '0:30', 
        description: 'Main Video'
    }];

    const currentSegment = activeSegments[currentSegIdx];

    const handleMagicFix = () => {
        if(!magicInput) return;
        setStatus('processing');
        // Simulate "fixing" the current segment
        setTimeout(() => {
            setStatus('idle');
            setMagicInput("");
        }, 2000);
    };

    return (
        <div className="fixed inset-0 z-50 bg-black flex flex-col animate-in slide-in-from-bottom duration-300">
             <div className="absolute top-0 left-0 right-0 p-4 pt-safe z-10 flex justify-between items-center pointer-events-none">
                <button onClick={onClose} className="bg-black/20 backdrop-blur-lg border border-white/10 rounded-full p-2 text-white pointer-events-auto hover:bg-black/40">
                     <X size={20} />
                </button>
             </div>

             {/* Mock Video Surface */}
             <div className="flex-1 relative bg-gray-900 flex items-center justify-center overflow-hidden" onClick={() => setIsPlaying(!isPlaying)}>
                {/* We use an image to simulate the video for this demo */}
                <div key={currentSegment.id} className="w-full h-full relative animate-in fade-in duration-500">
                     <img src={currentSegment.thumbnail} className="w-full h-full object-cover opacity-80" />
                </div>

                {!isPlaying && (
                    <div className="absolute inset-0 flex items-center justify-center bg-black/20 backdrop-blur-[2px]">
                        <div className="w-16 h-16 bg-white/20 rounded-full flex items-center justify-center backdrop-blur-md">
                            <Play size={32} fill="white" className="text-white ml-1" />
                        </div>
                    </div>
                )}

                {/* Processing Overlay */}
                {status === 'processing' && (
                     <div className="absolute inset-0 bg-black/80 backdrop-blur-sm flex flex-col items-center justify-center z-20">
                        <div className="w-12 h-12 border-4 border-white/10 border-t-green-500 rounded-full animate-spin mb-4" />
                        <span className="text-white font-medium">正在修改分镜 {currentSegIdx + 1}...</span>
                     </div>
                )}

                {/* Segment Indicator Overlay */}
                <div className="absolute top-20 left-4 bg-black/50 backdrop-blur-md px-3 py-1 rounded-full text-xs text-white/80 border border-white/10 font-mono">
                    Segment {currentSegIdx + 1} / {activeSegments.length} • {currentSegment.duration}
                </div>
             </div>

             {/* Controls & Timeline */}
             <div className="absolute bottom-0 w-full p-4 pb-safe bg-gradient-to-t from-black via-black/80 to-transparent">

                 {/* Timeline Segments */}
                 <div className="mb-6 overflow-x-auto no-scrollbar">
                     <div className="flex gap-2 px-1 min-w-max">
                        {activeSegments.map((seg, idx) => (
                            <div 
                                key={seg.id}
                                onClick={(e) => { e.stopPropagation(); setCurrentSegIdx(idx); }}
                                className={`group relative flex-shrink-0 cursor-pointer flex flex-col gap-1 transition-all ${
                                    currentSegIdx === idx ? 'w-24 opacity-100' : 'w-16 opacity-50 hover:opacity-80'
                                }`}
                            >
                                {/* Thumbnail */}
                                <div className={`h-12 rounded-lg overflow-hidden border-2 ${currentSegIdx === idx ? 'border-indigo-500' : 'border-white/20'}`}>
                                    <img src={seg.thumbnail} className="w-full h-full object-cover" />
                                </div>
                                {/* Label */}
                                <div className="flex justify-between items-center px-0.5">
                                    <span className="text-[9px] text-white/70 font-mono">#{idx + 1}</span>
                                    <span className="text-[9px] text-white/50">{seg.duration}</span>
                                </div>
                            </div>
                        ))}
                     </div>
                 </div>

                 {/* Magic Edit Context Aware */}
                 <div className="flex items-center gap-3">
                     <div className="flex-1 bg-gray-800/80 backdrop-blur-md rounded-2xl flex items-center p-1 border border-white/10 shadow-lg transition-colors focus-within:border-indigo-500/50">
                        <div className="pl-3 pr-1 text-indigo-400">
                             <Sparkles size={14} />
                        </div>
                        <input 
                            value={magicInput} 
                            onChange={(e) => setMagicInput(e.target.value)}
                            className="flex-1 bg-transparent border-none text-white text-sm px-2 py-2 placeholder:text-gray-500 focus:ring-0"
                            placeholder={`调整第 ${currentSegIdx + 1} 个分镜...`}
                        />
                        <button 
                            onClick={handleMagicFix}
                            disabled={!magicInput}
                            className={`p-2 rounded-xl text-white transition-colors ${magicInput ? 'bg-indigo-600 hover:bg-indigo-500' : 'bg-white/5 text-white/30'}`}
                        >
                            <Send size={14} />
                        </button>
                     </div>
                 </div>
             </div>
        </div>
    );
}

import React, { useState, useCallback } from 'react';
import { ChevronLeft, Lightbulb } from 'lucide-react';
import { Message, OverlayState, ScriptData, StoryboardImage, VideoSegment, CharacterDesign } from './types';
import { ChatInterface } from './components/ChatInterface';
import { InputArea } from './components/InputArea';
import { ScriptEditor, ImageViewer, VideoPlayer, CharacterViewer } from './components/Overlays';
import { MOCK_SCRIPT, MOCK_STORYBOARD, MOCK_CHARACTERS } from './constants';

export default function App() {
  const [messages, setMessages] = useState<Message[]>([
    { 
      id: 'init', 
      role: 'agent', 
      type: 'text', 
      text: '嗨！今天想制作什么视频？', 
      timestamp: Date.now() 
    }
  ]);
  const [overlay, setOverlay] = useState<OverlayState>({ type: 'none' });
  const [isAgentThinking, setIsAgentThinking] = useState(false);

  // --- Helper to add message ---
  const addMsg = (msg: Partial<Message>) => {
    setMessages(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      role: 'agent',
      type: 'text',
      ...msg
    } as Message]);
  };

  // --- AGENT STATE MACHINE (MOCK) ---
  const handleUserMessage = async (text: string) => {
    // 1. Add User Message
    addMsg({ role: 'user', text, type: 'text' });

    // 2. Simulate Thinking
    setIsAgentThinking(true);

    // Add a temporary loading bubble
    const loadingId = 'loading-' + Date.now();
    setMessages(prev => [...prev, { id: loadingId, role: 'agent', type: 'text', isLoading: true, timestamp: Date.now() }]);

    // 3. Determine Response based on context (Simple sequential flow for demo)
    setTimeout(() => {
      // Remove loading bubble
      setMessages(prev => prev.filter(m => m.id !== loadingId));
      setIsAgentThinking(false);

      const lastType = messages.filter(m => m.role === 'agent' && m.type !== 'text').pop()?.type;

      if (!lastType) {
        // Step 1: Script Generation (Changed from Character first)
        addMsg({ role: 'agent', text: '收到！根据你的描述，我草拟了以下脚本结构：' });
        addMsg({ role: 'agent', type: 'script_card', scriptData: MOCK_SCRIPT });
      } else if (lastType === 'script_card') {
          // Fallback if they type after script
          addMsg({ role: 'agent', text: '请先确认上方的脚本，以便提取核心角色。' });
      } else if (lastType === 'character_card') {
          // Fallback if user chats after characters
          addMsg({ role: 'agent', text: '请确认角色定妆照，确认后我们将生成分镜。' });
      } else if (lastType === 'storyboard_card') {
          addMsg({ role: 'agent', text: '我可以更新图片。长按查看详情或点击进行魔法编辑。' });
      } else {
         addMsg({ role: 'agent', text: '正在处理！' });
      }

    }, 1500);
  };

  // --- INTERACTION HANDLERS ---
  const handleCardClick = useCallback((msgId: string, action: string, data?: any) => {
    if (action === 'confirm_script') {
        // Step 2: Script Confirmed -> Proceed to Character Extraction
        const scriptData = data as ScriptData; // We could use this to tailor characters in a real app

        setIsAgentThinking(true);
        setTimeout(() => {
            setIsAgentThinking(false);
            addMsg({ role: 'agent', text: '脚本已确认！基于此脚本，我提取了以下核心角色，请确认定妆照：' });
            addMsg({ role: 'agent', type: 'character_card', characterData: MOCK_CHARACTERS });
        }, 1000);

    } else if (action === 'confirm_characters') {
        // Step 3: Characters Confirmed -> Proceed to Storyboard Generation
        setIsAgentThinking(true);
        setTimeout(() => {
             setIsAgentThinking(false);

             // Retrieve the confirmed script to generate storyboards
             // In a real app we'd likely store this in a 'project context' state
             const scriptMsg = [...messages].reverse().find(m => m.type === 'script_card');
             const scriptData = scriptMsg?.scriptData || MOCK_SCRIPT;

             addMsg({ role: 'agent', text: '角色已确认。正在根据脚本和角色设定生成分镜...' });

             // Generate Storyboard Data based on Script Lines
            const generatedStoryboard: StoryboardImage[] = scriptData.lines.map((line) => ({
                id: `img-${line.id}`,
                src: `https://picsum.photos/400/600?random=${line.id}-${Date.now()}`, 
                prompt: line.visual,
                description: line.visual.length > 50 ? line.visual.substring(0, 47) + '...' : line.visual,
                subtitle: line.audio // Map audio to subtitle
            }));

            setTimeout(() => {
                addMsg({ 
                    role: 'agent', 
                    type: 'storyboard_card', 
                    storyboardData: generatedStoryboard.length > 0 ? generatedStoryboard : MOCK_STORYBOARD 
                });

                setTimeout(() => {
                    addMsg({ role: 'agent', text: '分镜已就绪。请选择配音风格：' });
                    addMsg({ 
                        role: 'agent', 
                        type: 'audio_selection',
                        audioOptions: [
                            { id: '1', name: '磁性男声', description: '深沉稳重，适合电影叙事', previewUrl: '' },
                            { id: '2', name: '活力少女', description: '明快活泼，适合 Vlog', previewUrl: '' },
                            { id: '3', name: '赛博 AI', description: '电子合成音，冷酷未来感', previewUrl: '' }
                        ]
                    });
                }, 1000);
            }, 1500);
        }, 500);

    } else if (action === 'open_script') {
      // Legacy action, kept just in case but likely replaced by inline edit
      setOverlay({ type: 'script_editor', data: data });

    } else if (action === 'save_script') {
        // Handle inline script save
        setMessages(prev => prev.map(m => 
            m.id === msgId && m.type === 'script_card' ? { ...m, scriptData: data } : m
        ));

    } else if (action === 'view_image') {
      // Data contains { initialImage, allImages }
      setOverlay({ type: 'image_viewer', data: data });

    } else if (action === 'view_character') {
        // Data contains { initialCharacter, allCharacters }
        setOverlay({ type: 'character_viewer', data: data });

    } else if (action === 'select_audio') {
        // User selected audio, move to Video Generation
        setMessages(prev => prev.map(m => 
             m.type === 'audio_selection' 
             ? { ...m, audioOptions: m.audioOptions?.map(o => ({...o, selected: o.id === data}))} 
             : m
        ));

        // Trigger Video Generation
        setTimeout(() => {
            addMsg({ role: 'agent', text: '很好的选择！正在渲染最终视频...' });
            // Simulate waiting
            setTimeout(() => {
                // Mock segments based on existing storyboard or script lines
                const segments: VideoSegment[] = MOCK_STORYBOARD.map((img, idx) => ({
                    id: `seg-${idx}`,
                    thumbnail: img.src,
                    duration: ['5s', '10s', '8s'][idx] || '5s',
                    description: img.description
                }));

                addMsg({ 
                    role: 'agent', 
                    type: 'video_card', 
                    videoData: {
                        thumbnail: MOCK_STORYBOARD[0].src, 
                        videoUrl: '#',
                        duration: '23s',
                        segments: segments
                    } 
                });
            }, 2500);
        }, 500);
    } else if (action === 'play_video') {
        setOverlay({ type: 'video_player', data: data });
    }
  }, [messages]);

  // Rename this to represent SAVING data, not next step
  const handleScriptSave = (newData: ScriptData) => {
    setOverlay({ type: 'none' });

    // Only update the message in chat history to reflect changes
    setMessages(prev => prev.map(m => 
       m.type === 'script_card' ? { ...m, scriptData: newData } : m
    ));
  };

  const handleAiScriptModification = (prompt: string, currentScript: ScriptData) => {
      setOverlay({ type: 'none' }); // Ensure overlay is closed

      // 1. Add User Message
      addMsg({ role: 'user', text: prompt, type: 'text' });

      // 2. Simulate Thinking
      setIsAgentThinking(true);
      const loadingId = 'loading-' + Date.now();
      setMessages(prev => [...prev, { id: loadingId, role: 'agent', type: 'text', isLoading: true, timestamp: Date.now() }]);

      // 3. Simulate Agent Response
      setTimeout(() => {
          setMessages(prev => prev.filter(m => m.id !== loadingId));
          setIsAgentThinking(false);

          // Create modified script data
          const newScript = {
              ...currentScript,
              lines: currentScript.lines.map((line, idx) => {
                  if (idx === 0) {
                      return { ...line, visual: line.visual + ` (根据"${prompt}"进行了优化)` };
                  }
                  return line;
              })
          };

          addMsg({ role: 'agent', text: '没问题，根据您的反馈，我优化了脚本内容：' });
          addMsg({ role: 'agent', type: 'script_card', scriptData: newScript });

      }, 2000);
  };

  const handleImageUpdate = (updatedImg: StoryboardImage) => {
     // Persist changes from ImageViewer back to the main chat
     setMessages(prev => prev.map(msg => {
         if (msg.type === 'storyboard_card' && msg.storyboardData) {
             return {
                 ...msg,
                 storyboardData: msg.storyboardData.map(img => 
                     img.id === updatedImg.id ? updatedImg : img
                 )
             };
         }
         return msg;
     }));
  };

  const handleCharacterUpdate = (updatedChar: CharacterDesign) => {
    // Persist changes from CharacterViewer back to the main chat
    setMessages(prev => prev.map(msg => {
        if (msg.type === 'character_card' && msg.characterData) {
            return {
                ...msg,
                characterData: msg.characterData.map(c => 
                    c.id === updatedChar.id ? updatedChar : c
                )
            };
        }
        return msg;
    }));
  };

  return (
    <div className="flex justify-center bg-black h-screen w-screen overflow-hidden">
      {/* Mobile Container */}
      <div className="w-full max-w-md h-full bg-black flex flex-col relative shadow-2xl overflow-hidden md:border-x border-gray-800">

        {/* Header */}
        <header className="flex items-center justify-between p-4 pt-6 bg-transparent absolute top-0 left-0 right-0 z-10">
           <button className="text-white/80 hover:text-white p-1 rounded-full active:bg-white/10 transition-colors">
              <ChevronLeft size={28} />
           </button>
           <button className="text-white/80 hover:text-white p-1 rounded-full active:bg-white/10 transition-colors">
              <Lightbulb size={24} />
           </button>
        </header>

        {/* Chat Area */}
        <ChatInterface 
          messages={messages} 
          onCardClick={handleCardClick} 
        />

        {/* Input Area */}
        <InputArea 
            onSendMessage={handleUserMessage} 
            disabled={isAgentThinking} 
        />

        {/* --- OVERLAYS --- */}
        {overlay.type === 'script_editor' && (
          <ScriptEditor 
            initialData={overlay.data} 
            onClose={() => setOverlay({ type: 'none' })}
            onConfirm={handleScriptSave} 
            onAiEditRequest={(prompt) => handleAiScriptModification(prompt, overlay.data)}
          />
        )}

        {overlay.type === 'image_viewer' && (
          <ImageViewer
            initialImage={overlay.data.initialImage}
            allImages={overlay.data.allImages}
            onClose={() => setOverlay({ type: 'none' })}
            onUpdate={handleImageUpdate}
          />
        )}

        {overlay.type === 'character_viewer' && (
            <CharacterViewer
                initialCharacter={overlay.data.initialCharacter}
                allCharacters={overlay.data.allCharacters}
                onClose={() => setOverlay({ type: 'none' })}
                onUpdate={handleCharacterUpdate}
            />
        )}

        {overlay.type === 'video_player' && (
            <VideoPlayer
                thumbnail={overlay.data.thumbnail}
                segments={overlay.data.segments}
                onClose={() => setOverlay({ type: 'none' })}
            />
        )}

      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { X, Check, ArrowLeft, Send, Sparkles, GripVertical, Trash2, Play, RefreshCw, Wand2, Film, MessageSquare, ChevronRight, ChevronLeft, Type } from 'lucide-react';
import { ScriptData, ScriptLine, StoryboardImage, VideoSegment, CharacterDesign } from '../types';

/* --- BOTTOM SHEET: SCRIPT EDITOR --- */
interface ScriptEditorProps {
  initialData: ScriptData;
  onClose: () => void;
  onConfirm: (newData: ScriptData) => void;
  onAiEditRequest: (prompt: string) => void;
}

export const ScriptEditor: React.FC<ScriptEditorProps> = ({ initialData, onClose, onConfirm, onAiEditRequest }) => {
  const [lines, setLines] = useState<ScriptLine[]>(initialData.lines);
  const [isClosing, setIsClosing] = useState(false);
  const [aiPrompt, setAiPrompt] = useState('');
  const [isAiProcessing, setIsAiProcessing] = useState(false);

  const handleClose = () => {
    setIsClosing(true);
    setTimeout(onClose, 300);
  };

  const handleSave = () => {
    setIsClosing(true);
    setTimeout(() => onConfirm({ ...initialData, lines }), 300);
  };

  const handleTextChange = (id: string, field: 'visual' | 'audio', val: string) => {
    setLines(lines.map(l => l.id === id ? { ...l, [field]: val } : l));
  };

  const handleDeleteLine = (id: string) => {
    setLines(lines.filter(l => l.id !== id));
  };

  const handleAiEdit = () => {
      if (!aiPrompt.trim()) return;

      // Animate close first
      setIsClosing(true);

      // Trigger parent callback after animation matches the visual close
      setTimeout(() => {
          onClose(); // Clean up overlay state
          onAiEditRequest(aiPrompt); // Send prompt to chat
      }, 300);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center">
      {/* Backdrop */}
      <div 
        className={`absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity duration-300 ${isClosing ? 'opacity-0' : 'opacity-100'}`} 
        onClick={handleClose}
      />

      {/* Sheet */}
      <div className={`relative w-full max-w-lg bg-gray-900 rounded-t-3xl shadow-2xl flex flex-col max-h-[90vh] transition-transform duration-300 transform ${isClosing ? 'translate-y-full' : 'translate-y-0'} border border-white/10`}>
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-white/5">
          <div className="w-9" /> {/* Spacer to keep title centered */}
          <span className="font-bold text-gray-100">编辑脚本</span>
          <button onClick={handleSave} className="p-2 text-indigo-400 font-medium hover:bg-indigo-900/30 rounded-full">
            <Check size={20} />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 pb-24 custom-scrollbar">
          {lines.map((line, index) => (
            <div key={line.id} className="flex gap-3 items-start group relative">
              <div className="mt-4 text-gray-600 cursor-move hover:text-gray-400">
                <GripVertical size={20} />
              </div>
              <div className="flex-1 bg-gray-800 rounded-xl p-3 border border-white/5 focus-within:border-indigo-500/50 focus-within:ring-1 focus-within:ring-indigo-500/20 transition-all">
                <div className="flex justify-between items-center mb-2">
                    <div className="flex gap-2 text-xs font-bold text-gray-400 uppercase tracking-wide">
                        <span>分镜 {index + 1}</span>
                        <span className="bg-gray-700 px-1.5 rounded text-gray-300">{line.duration}</span>
                    </div>
                    {/* Delete Button */}
                    <button 
                        onClick={() => handleDeleteLine(line.id)}
                        className="text-gray-500 hover:text-red-400 p-1 rounded-full transition-colors"
                    >
                        <Trash2 size={14} />
                    </button>
                </div>

                <div className="space-y-3">
                  <div>
                    <label className="block text-[10px] text-indigo-400 font-semibold mb-1">画面</label>
                    <textarea 
                      value={line.visual}
                      onChange={(e) => handleTextChange(line.id, 'visual', e.target.value)}
                      className="w-full bg-gray-700 rounded-lg p-2 text-sm text-gray-200 border-none focus:ring-0 resize-none h-16 shadow-inner placeholder-gray-500"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] text-orange-400 font-semibold mb-1">声音</label>
                    <textarea 
                      value={line.audio}
                      onChange={(e) => handleTextChange(line.id, 'audio', e.target.value)}
                      className="w-full bg-gray-700 rounded-lg p-2 text-sm text-gray-400 border-none focus:ring-0 resize-none h-12 italic shadow-inner placeholder-gray-500"
                    />
                  </div>
                </div>
              </div>
            </div>
          ))}
          {lines.length === 0 && (
             <div className="text-center py-10 text-gray-500 text-sm">没有分镜了。添加一个？</div>
          )}
        </div>

        {/* AI Input Area */}
        <div className="absolute bottom-0 left-0 right-0 p-4 bg-gray-900/95 backdrop-blur border-t border-white/5 rounded-b-3xl">
           <div className={`flex items-center gap-2 bg-gray-800 border border-white/10 rounded-full px-2 py-1.5 pl-4 transition-all ${isAiProcessing ? 'opacity-80' : ''}`}>
              <Wand2 size={16} className={`text-indigo-400 ${isAiProcessing ? 'animate-spin' : ''}`} />
              <input 
                 type="text"
                 value={aiPrompt}
                 onChange={(e) => setAiPrompt(e.target.value)}
                 onKeyDown={(e) => e.key === 'Enter' && handleAiEdit()}
                 placeholder={isAiProcessing ? "AI 正在思考..." : "告诉 AI 如何修改脚本..."}
                 disabled={isAiProcessing}
                 className="flex-1 bg-transparent border-none text-sm text-gray-200 placeholder:text-gray-500 focus:ring-0 p-0 h-9"
              />
              <button 
                onClick={handleAiEdit}
                disabled={!aiPrompt || isAiProcessing}
                className={`w-9 h-9 rounded-full flex items-center justify-center transition-colors ${aiPrompt && !isAiProcessing ? 'bg-indigo-600 text-white shadow-md' : 'bg-gray-700 text-gray-500'}`}
              >
                 <Send size={16} className={aiPrompt && !isAiProcessing ? "ml-0.5" : ""} />
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

/* --- FULLSCREEN IMAGE EDITOR --- */
interface ImageViewerProps {
  initialImage: StoryboardImage;
  allImages?: StoryboardImage[];
  onClose: () => void;
  onUpdate: (newImg: StoryboardImage) => void;
}

export const ImageViewer: React.FC<ImageViewerProps> = ({ initialImage, allImages = [], onClose, onUpdate }) => {
  const [prompt, setPrompt] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showSubtitles, setShowSubtitles] = useState(true);

  // Track the full list locally so we can update other thumbnails if needed, though mostly for display navigation
  const [sessionImages, setSessionImages] = useState<StoryboardImage[]>(allImages.length ? allImages : [initialImage]);
