import React, { useState, useEffect } from 'react';
import { X, Check, ArrowLeft, Send, Sparkles, GripVertical, Trash2, Play, RefreshCw, Wand2, Film, MessageSquare, ChevronRight, ChevronLeft, Type } from 'lucide-react';
import { ScriptData, ScriptLine, StoryboardImage, VideoSegment, CharacterDesign } from '../types';

/* --- BOTTOM SHEET: SCRIPT EDITOR --- */
interface ScriptEditorProps {
  initialData: ScriptData;
  onClose: () => void;
  onConfirm: (newData: ScriptData) => void;
  onAiEditRequest: (prompt: string) => void;
}

export const ScriptEditor: React.FC<ScriptEditorProps> = ({ initialData, onClose, onConfirm, onAiEditRequest }) => {
  const [lines, setLines] = useState<ScriptLine[]>(initialData.lines);
  const [isClosing, setIsClosing] = useState(false);
  const [aiPrompt, setAiPrompt] = useState('');
  const [isAiProcessing, setIsAiProcessing] = useState(false);

  const handleClose = () => {
    setIsClosing(true);
    setTimeout(onClose, 300);
  };

  const handleSave = () => {
    setIsClosing(true);
    setTimeout(() => onConfirm({ ...initialData, lines }), 300);
  };

  const handleTextChange = (id: string, field: 'visual' | 'audio', val: string) => {
    setLines(lines.map(l => l.id === id ? { ...l, [field]: val } : l));
  };

  const handleDeleteLine = (id: string) => {
    setLines(lines.filter(l => l.id !== id));
  };

  const handleAiEdit = () => {
      if (!aiPrompt.trim()) return;

      // Animate close first
      setIsClosing(true);

      // Trigger parent callback after animation matches the visual close
      setTimeout(() => {
          onClose(); // Clean up overlay state
          onAiEditRequest(aiPrompt); // Send prompt to chat
      }, 300);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center">
      {/* Backdrop */}
      <div 
        className={`absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity duration-300 ${isClosing ? 'opacity-0' : 'opacity-100'}`} 
        onClick={handleClose}
      />

      {/* Sheet */}
      <div className={`relative w-full max-w-lg bg-gray-900 rounded-t-3xl shadow-2xl flex flex-col max-h-[90vh] transition-transform duration-300 transform ${isClosing ? 'translate-y-full' : 'translate-y-0'} border border-white/10`}>
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-white/5">
          <div className="w-9" /> {/* Spacer to keep title centered */}
          <span className="font-bold text-gray-100">编辑脚本</span>
          <button onClick={handleSave} className="p-2 text-indigo-400 font-medium hover:bg-indigo-900/30 rounded-full">
            <Check size={20} />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 pb-24 custom-scrollbar">
          {lines.map((line, index) => (
            <div key={line.id} className="flex gap-3 items-start group relative">
              <div className="mt-4 text-gray-600 cursor-move hover:text-gray-400">
                <GripVertical size={20} />
              </div>
              <div className="flex-1 bg-gray-800 rounded-xl p-3 border border-white/5 focus-within:border-indigo-500/50 focus-within:ring-1 focus-within:ring-indigo-500/20 transition-all">
                <div className="flex justify-between items-center mb-2">
                    <div className="flex gap-2 text-xs font-bold text-gray-400 uppercase tracking-wide">
                        <span>分镜 {index + 1}</span>
                        <span className="bg-gray-700 px-1.5 rounded text-gray-300">{line.duration}</span>
                    </div>
                    {/* Delete Button */}
                    <button 
                        onClick={() => handleDeleteLine(line.id)}
                        className="text-gray-500 hover:text-red-400 p-1 rounded-full transition-colors"
                    >
                        <Trash2 size={14} />
                    </button>
                </div>

                <div className="space-y-3">
                  <div>
                    <label className="block text-[10px] text-indigo-400 font-semibold mb-1">画面</label>
                    <textarea 
                      value={line.visual}
                      onChange={(e) => handleTextChange(line.id, 'visual', e.target.value)}
                      className="w-full bg-gray-700 rounded-lg p-2 text-sm text-gray-200 border-none focus:ring-0 resize-none h-16 shadow-inner placeholder-gray-500"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] text-orange-400 font-semibold mb-1">声音</label>
                    <textarea 
                      value={line.audio}
                      onChange={(e) => handleTextChange(line.id, 'audio', e.target.value)}
                      className="w-full bg-gray-700 rounded-lg p-2 text-sm text-gray-400 border-none focus:ring-0 resize-none h-12 italic shadow-inner placeholder-gray-500"
                    />
                  </div>
                </div>
              </div>
            </div>
          ))}
          {lines.length === 0 && (
             <div className="text-center py-10 text-gray-500 text-sm">没有分镜了。添加一个？</div>
          )}
        </div>

        {/* AI Input Area */}
        <div className="absolute bottom-0 left-0 right-0 p-4 bg-gray-900/95 backdrop-blur border-t border-white/5 rounded-b-3xl">
           <div className={`flex items-center gap-2 bg-gray-800 border border-white/10 rounded-full px-2 py-1.5 pl-4 transition-all ${isAiProcessing ? 'opacity-80' : ''}`}>
              <Wand2 size={16} className={`text-indigo-400 ${isAiProcessing ? 'animate-spin' : ''}`} />
              <input 
                 type="text"
                 value={aiPrompt}
                 onChange={(e) => setAiPrompt(e.target.value)}
                 onKeyDown={(e) => e.key === 'Enter' && handleAiEdit()}
                 placeholder={isAiProcessing ? "AI 正在思考..." : "告诉 AI 如何修改脚本..."}
                 disabled={isAiProcessing}
                 className="flex-1 bg-transparent border-none text-sm text-gray-200 placeholder:text-gray-500 focus:ring-0 p-0 h-9"
              />
              <button 
                onClick={handleAiEdit}
                disabled={!aiPrompt || isAiProcessing}
                className={`w-9 h-9 rounded-full flex items-center justify-center transition-colors ${aiPrompt && !isAiProcessing ? 'bg-indigo-600 text-white shadow-md' : 'bg-gray-700 text-gray-500'}`}
              >
                 <Send size={16} className={aiPrompt && !isAiProcessing ? "ml-0.5" : ""} />
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

