  };

  return (
    <div className="bg-gray-900 rounded-2xl p-3 shadow-sm border border-white/10 w-full max-w-[85%]">
      <div className="flex items-center gap-2 mb-3 px-1">
        <div className="p-1.5 bg-orange-900/30 rounded-lg">
          <Mic size={14} className="text-orange-400" />
        </div>
        <span className="text-xs font-bold text-gray-400 uppercase tracking-wide">配音选择</span>
      </div>

      <div className="flex flex-col gap-2">
        {options.map((opt) => (
          <div 
            key={opt.id}
            onClick={() => onSelect(opt.id)}
            className={`relative flex items-center gap-3 p-3 rounded-xl border transition-all cursor-pointer ${
              opt.selected 
                ? 'bg-indigo-900/20 border-indigo-500/50 ring-1 ring-indigo-500/30' 
                : 'bg-gray-800/50 border-white/5 hover:border-indigo-500/30'
            }`}
          >
            <button
              onClick={(e) => togglePlay(e, opt.id)}
              className={`flex-shrink-0 w-10 h-10 rounded-full flex items-center justify-center transition-colors ${
                playingId === opt.id ? 'bg-indigo-600 text-white' : 'bg-gray-800 text-gray-400 border border-white/10'
              }`}
            >
              {playingId === opt.id ? (
                <div className="flex gap-0.5 items-end h-3">
                  <div className="w-1 bg-white animate-[pulse_0.5s_ease-in-out_infinite] h-full" />
                  <div className="w-1 bg-white animate-[pulse_0.7s_ease-in-out_infinite] h-2/3" />
                  <div className="w-1 bg-white animate-[pulse_0.6s_ease-in-out_infinite] h-full" />
                </div>
              ) : (
                <Play size={18} fill="currentColor" />
              )}
            </button>

            <div className="flex-1 min-w-0">
              <h4 className={`text-sm font-semibold ${opt.selected ? 'text-indigo-300' : 'text-gray-200'}`}>
                {opt.name}
              </h4>
              <p className="text-xs text-gray-500 truncate">{opt.description}</p>
            </div>

            {opt.selected && (
              <div className="w-4 h-4 rounded-full bg-indigo-600 flex items-center justify-center">
                <div className="w-1.5 h-1.5 bg-white rounded-full" />
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

/* --- VIDEO RESULT CARD --- */
interface VideoCardProps {
  thumbnail: string;
  duration: string;
  segments?: VideoSegment[];
  onEdit: () => void;
}

export const VideoCard: React.FC<VideoCardProps> = ({ thumbnail, duration, segments = [], onEdit }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentThumb, setCurrentThumb] = useState(thumbnail);

  // Use provided segments or fallback to single thumbnail
  const slides = segments.length > 0 ? segments.map(s => s.thumbnail) : [thumbnail];

  useEffect(() => {
    let interval: any;
    if (isPlaying && slides.length > 1) {
      let idx = slides.indexOf(currentThumb);
      if (idx === -1) idx = 0;

      interval = setInterval(() => {
        idx = (idx + 1) % slides.length;
        setCurrentThumb(slides[idx]);
      }, 600);
    } else {
        // Reset to main thumbnail when stopped
        setCurrentThumb(thumbnail);
    }
    return () => clearInterval(interval);
  }, [isPlaying, slides, thumbnail]);

  return (
    <div className="w-full max-w-[70%] relative group select-none">
      <div 
        onClick={() => setIsPlaying(!isPlaying)}
        className="relative aspect-[9/16] rounded-2xl overflow-hidden shadow-lg bg-black border border-gray-800 cursor-pointer"
      >
        <img 
            src={currentThumb} 
            alt="Video Preview" 
            className="w-full h-full object-cover transition-all duration-300" 
        />

        {/* Play Button Overlay */}
        {!isPlaying && (
          <div className="absolute inset-0 flex items-center justify-center bg-black/10">
            <div className="w-14 h-14 rounded-full bg-white/20 backdrop-blur-md flex items-center justify-center border border-white/20 shadow-xl scale-100 active:scale-95 transition-all">
               <Play size={28} fill="white" className="text-white ml-1" />
            </div>
          </div>
        )}

        {/* Status Badge */}
        <div className="absolute top-3 left-3 bg-[#10B981] px-2.5 py-1 rounded-lg text-[10px] text-white font-bold tracking-wide shadow-sm flex items-center gap-1">
             <span>完成</span>
        </div>

        {/* Duration */}
        <div className="absolute bottom-3 right-3 bg-black/60 px-2 py-1 rounded-md text-xs text-white/90 font-mono backdrop-blur-sm border border-white/10">
          {duration}
        </div>
      </div>

      {/* Edit Button (Top Right) */}
      <button 
        onClick={(e) => {
            e.stopPropagation(); 
            onEdit();
        }}
        className="absolute top-3 right-3 p-2 bg-black/30 hover:bg-black/50 text-white backdrop-blur-md border border-white/10 rounded-full transition-all active:scale-95 z-10"
      >
        <Edit3 size={16} />
      </button>
    </div>
  );
};

