};

import React, { useState, useCallback } from 'react';
import { ChevronLeft, Lightbulb } from 'lucide-react';
import { Message, OverlayState, ScriptData, StoryboardImage, VideoSegment, CharacterDesign } from './types';
import { ChatInterface } from './components/ChatInterface';
import { InputArea } from './components/InputArea';
import { ScriptEditor, ImageViewer, VideoPlayer, CharacterViewer } from './components/Overlays';
import { MOCK_SCRIPT, MOCK_STORYBOARD, MOCK_CHARACTERS } from './constants';

export default function App() {
  const [messages, setMessages] = useState<Message[]>([
    { 
      id: 'init', 
      role: 'agent', 
      type: 'text', 
      text: '嗨！今天想制作什么视频？', 
      timestamp: Date.now() 
    }
  ]);
  const [overlay, setOverlay] = useState<OverlayState>({ type: 'none' });
  const [isAgentThinking, setIsAgentThinking] = useState(false);

  // --- Helper to add message ---
  const addMsg = (msg: Partial<Message>) => {
    setMessages(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      role: 'agent',
      type: 'text',
      ...msg
    } as Message]);
  };

  // --- AGENT STATE MACHINE (MOCK) ---
  const handleUserMessage = async (text: string) => {
    // 1. Add User Message
    addMsg({ role: 'user', text, type: 'text' });

    // 2. Simulate Thinking
    setIsAgentThinking(true);

    // Add a temporary loading bubble
    const loadingId = 'loading-' + Date.now();
    setMessages(prev => [...prev, { id: loadingId, role: 'agent', type: 'text', isLoading: true, timestamp: Date.now() }]);

    // 3. Determine Response based on context (Simple sequential flow for demo)
    setTimeout(() => {
      // Remove loading bubble
      setMessages(prev => prev.filter(m => m.id !== loadingId));
      setIsAgentThinking(false);

      const lastType = messages.filter(m => m.role === 'agent' && m.type !== 'text').pop()?.type;

      if (!lastType) {
        // Step 1: Script Generation (Changed from Character first)
        addMsg({ role: 'agent', text: '收到！根据你的描述，我草拟了以下脚本结构：' });
        addMsg({ role: 'agent', type: 'script_card', scriptData: MOCK_SCRIPT });
      } else if (lastType === 'script_card') {
          // Fallback if they type after script
          addMsg({ role: 'agent', text: '请先确认上方的脚本，以便提取核心角色。' });
      } else if (lastType === 'character_card') {
          // Fallback if user chats after characters
          addMsg({ role: 'agent', text: '请确认角色定妆照，确认后我们将生成分镜。' });
      } else if (lastType === 'storyboard_card') {
          // Handle storyboard modification request
          const lastStoryboardMsg = [...messages].reverse().find(m => m.type === 'storyboard_card');
          const currentStoryboard = lastStoryboardMsg?.storyboardData || MOCK_STORYBOARD;

          // Simulate modification based on user input
          const updatedStoryboard = currentStoryboard.map((img, idx) => {
             // Heuristic: update if user mentions specific index or just the first one for the demo
             if (idx === 0) { 
                 return {
                     ...img,
                     src: `https://picsum.photos/400/600?random=${Date.now() + idx}`, // Force new image
                     description: img.description + ` (已修改)`
                 };
             }
             return img;
          });

          addMsg({ role: 'agent', text: '没问题，正在根据您的要求调整分镜画面...' });
          addMsg({ role: 'agent', type: 'storyboard_card', storyboardData: updatedStoryboard });

      } else {
         addMsg({ role: 'agent', text: '正在处理！' });
      }

    }, 1500);
  };

  // --- INTERACTION HANDLERS ---
  const handleCardClick = useCallback((msgId: string, action: string, data?: any) => {
    if (action === 'confirm_script') {
        // Step 2: Script Confirmed -> Proceed to Character Extraction
        const scriptData = data as ScriptData; // We could use this to tailor characters in a real app

        setIsAgentThinking(true);
        setTimeout(() => {
            setIsAgentThinking(false);
            addMsg({ role: 'agent', text: '脚本已确认！基于此脚本，我提取了以下核心角色，请确认定妆照：' });
            addMsg({ role: 'agent', type: 'character_card', characterData: MOCK_CHARACTERS });
        }, 1000);

    } else if (action === 'confirm_characters') {
        // Step 3: Characters Confirmed -> Proceed to Storyboard Generation
        setIsAgentThinking(true);
        setTimeout(() => {
             setIsAgentThinking(false);

             // Retrieve the confirmed script to generate storyboards
             // In a real app we'd likely store this in a 'project context' state
             const scriptMsg = [...messages].reverse().find(m => m.type === 'script_card');
             const scriptData = scriptMsg?.scriptData || MOCK_SCRIPT;

             addMsg({ role: 'agent', text: '角色已确认。正在根据脚本和角色设定生成分镜...' });

             // Generate Storyboard Data based on Script Lines
            const generatedStoryboard: StoryboardImage[] = scriptData.lines.map((line) => ({
                id: `img-${line.id}`,
                src: `https://picsum.photos/400/600?random=${line.id}-${Date.now()}`, 
                prompt: line.visual,
                description: line.visual.length > 50 ? line.visual.substring(0, 47) + '...' : line.visual,
                subtitle: line.audio // Map audio to subtitle
            }));

            setTimeout(() => {
                addMsg({ 
                    role: 'agent', 
                    type: 'storyboard_card', 
                    storyboardData: generatedStoryboard.length > 0 ? generatedStoryboard : MOCK_STORYBOARD 
                });
            }, 1500);
        }, 500);

    } else if (action === 'confirm_storyboard') {
        // Step 4: Storyboard Confirmed -> Proceed to Video Generation
         const finalStoryboard = (data as StoryboardImage[]) || MOCK_STORYBOARD;

         setIsAgentThinking(true);
         setTimeout(() => {
             setIsAgentThinking(false);
             addMsg({ role: 'agent', text: '分镜已确认！正在渲染最终视频...' });

             // Simulate waiting
             setTimeout(() => {
                 // Generate segments from the confirmed storyboard
                 const segments: VideoSegment[] = finalStoryboard.map((img, idx) => ({
                     id: `seg-${idx}`,
                     thumbnail: img.src,
                     duration: ['5s', '10s', '8s'][idx] || '5s',
                     description: img.description
                 }));

                 addMsg({ 
                     role: 'agent', 
                     type: 'video_card', 
                     videoData: {
                         thumbnail: finalStoryboard[0].src, 
                         videoUrl: '#',
                         duration: '23s',
                         segments: segments
                     } 
                 });
             }, 2500);
         }, 500);

    } else if (action === 'open_script') {
      // Legacy action, kept just in case but likely replaced by inline edit
      setOverlay({ type: 'script_editor', data: data });

    } else if (action === 'save_script') {
        // Handle inline script save
        setMessages(prev => prev.map(m => 
            m.id === msgId && m.type === 'script_card' ? { ...m, scriptData: data } : m
        ));

    } else if (action === 'view_image') {
      // Data contains { initialImage, allImages }
      setOverlay({ type: 'image_viewer', data: data });

    } else if (action === 'view_character') {
        // Data contains { initialCharacter, allCharacters }
        setOverlay({ type: 'character_viewer', data: data });

    } else if (action === 'play_video') {
        setOverlay({ type: 'video_player', data: data });
    }
  }, [messages]);

  // Rename this to represent SAVING data, not next step
  const handleScriptSave = (newData: ScriptData) => {
    setOverlay({ type: 'none' });

    // Only update the message in chat history to reflect changes
    setMessages(prev => prev.map(m => 
       m.type === 'script_card' ? { ...m, scriptData: newData } : m
    ));
  };

  const handleAiScriptModification = (prompt: string, currentScript: ScriptData) => {
      setOverlay({ type: 'none' }); // Ensure overlay is closed

      // 1. Add User Message
      addMsg({ role: 'user', text: prompt, type: 'text' });

      // 2. Simulate Thinking
      setIsAgentThinking(true);
      const loadingId = 'loading-' + Date.now();
      setMessages(prev => [...prev, { id: loadingId, role: 'agent', type: 'text', isLoading: true, timestamp: Date.now() }]);

      // 3. Simulate Agent Response
      setTimeout(() => {
          setMessages(prev => prev.filter(m => m.id !== loadingId));
          setIsAgentThinking(false);

          // Create modified script data
          const newScript = {
              ...currentScript,
              lines: currentScript.lines.map((line, idx) => {
                  if (idx === 0) {
                      return { ...line, visual: line.visual + ` (根据"${prompt}"进行了优化)` };
                  }
                  return line;
              })
          };

          addMsg({ role: 'agent', text: '没问题，根据您的反馈，我优化了脚本内容：' });
          addMsg({ role: 'agent', type: 'script_card', scriptData: newScript });

      }, 2000);
  };

  const handleImageUpdate = (updatedImg: StoryboardImage) => {
     // Persist changes from ImageViewer back to the main chat
     setMessages(prev => prev.map(msg => {
         if (msg.type === 'storyboard_card' && msg.storyboardData) {
             return {
                 ...msg,
                 storyboardData: msg.storyboardData.map(img => 
                     img.id === updatedImg.id ? updatedImg : img
                 )
             };
         }
         return msg;
     }));
  };

  const handleCharacterUpdate = (updatedChar: CharacterDesign) => {
    // Persist changes from CharacterViewer back to the main chat
    setMessages(prev => prev.map(msg => {
        if (msg.type === 'character_card' && msg.characterData) {
            return {
                ...msg,
                characterData: msg.characterData.map(c => 
                    c.id === updatedChar.id ? updatedChar : c
                )
            };
        }
        return msg;
    }));
  };

  return (
    <div className="flex justify-center bg-black h-screen w-screen overflow-hidden">
      {/* Mobile Container */}
      <div className="w-full max-w-md h-full bg-black flex flex-col relative shadow-2xl overflow-hidden md:border-x border-gray-800">

        {/* Header */}
        <header className="flex items-center justify-between p-4 pt-6 bg-transparent absolute top-0 left-0 right-0 z-10">
           <button className="text-white/80 hover:text-white p-1 rounded-full active:bg-white/10 transition-colors">
              <ChevronLeft size={28} />
           </button>
           <button className="text-white/80 hover:text-white p-1 rounded-full active:bg-white/10 transition-colors">
              <Lightbulb size={24} />
           </button>
        </header>

        {/* Chat Area */}
        <ChatInterface 
          messages={messages} 
          onCardClick={handleCardClick} 
        />

        {/* Input Area */}
        <InputArea 
            onSendMessage={handleUserMessage} 
            disabled={isAgentThinking} 
        />

        {/* --- OVERLAYS --- */}
        {overlay.type === 'script_editor' && (
          <ScriptEditor 
            initialData={overlay.data} 
            onClose={() => setOverlay({ type: 'none' })}
            onConfirm={handleScriptSave} 
            onAiEditRequest={(prompt) => handleAiScriptModification(prompt, overlay.data)}
          />
        )}

        {overlay.type === 'image_viewer' && (
          <ImageViewer
            initialImage={overlay.data.initialImage}
            allImages={overlay.data.allImages}
            onClose={() => setOverlay({ type: 'none' })}
            onUpdate={handleImageUpdate}
          />
        )}

        {overlay.type === 'character_viewer' && (
            <CharacterViewer
                initialCharacter={overlay.data.initialCharacter}
                allCharacters={overlay.data.allCharacters}
                onClose={() => setOverlay({ type: 'none' })}
                onUpdate={handleCharacterUpdate}
            />
        )}

        {overlay.type === 'video_player' && (
            <VideoPlayer
                thumbnail={overlay.data.thumbnail}
                segments={overlay.data.segments}
                onClose={() => setOverlay({ type: 'none' })}
            />
        )}

      </div>
    </div>
  );
}

// Message Roles and Types
export type Role = 'user' | 'agent';
export type MessageType = 'text' | 'character_card' | 'script_card' | 'storyboard_card' | 'audio_selection' | 'video_card' | 'system_notification';

// Data Structures for Payload
export interface CharacterDesign {
  id: string;
  name: string;
  description: string;
  imageUrl: string;
}

export interface ScriptLine {
  id: string;
  scene: number;
  duration: string;
  visual: string;
  audio: string;
}

export interface ScriptData {
  title: string;
  totalDuration: string;
  sceneCount: number;
  lines: ScriptLine[];
}

export interface StoryboardImage {
  id: string;
  src: string;
  prompt: string;
  description: string;
  subtitle?: string;
}

export interface AudioOption {
  id: string;
  name: string;
  description: string;
  previewUrl: string; // Mock URL
  selected?: boolean;
}

export interface VideoSegment {
  id: string;
  thumbnail: string;
  duration: string;
  description: string;
}

// Main Message Interface
export interface Message {
  id: string;
  role: Role;
  type: MessageType;
  text?: string;
  thoughtProcess?: string; // Model thinking process log
  timestamp: number;
  isLoading?: boolean;

  // Specific Payloads
  characterData?: CharacterDesign[];
  scriptData?: ScriptData;
  storyboardData?: StoryboardImage[];
  audioOptions?: AudioOption[];
  videoData?: {
    thumbnail: string;
    videoUrl: string;
    duration: string;
    segments?: VideoSegment[];
  };
}

// Overlay State Management
export type OverlayType = 'none' | 'script_editor' | 'image_viewer' | 'video_player' | 'character_viewer';

export interface OverlayState {
  type: OverlayType;
  data?: any; // Context data for the overlay
}

import React, { useEffect, useRef, useState } from 'react';
import { Message } from '../types';
import { AVATAR_URL } from '../constants';
import { Brain, ChevronDown, ChevronRight } from 'lucide-react';
import { ScriptCard, StoryboardCard, AudioSelectionCard, VideoCard, CharacterSelectionCard } from './ImmersiveCards';

interface ChatInterfaceProps {
  messages: Message[];
  onCardClick: (msgId: string, action: string, data?: any) => void;
}

const MessageItem: React.FC<{ msg: Message; onCardClick: (msgId: string, action: string, data?: any) => void }> = ({ msg, onCardClick }) => {
    const [isThinkingExpanded, setIsThinkingExpanded] = useState(true);

    return (
        <div 
          className={`flex gap-3 w-full animate-in slide-in-from-bottom-2 duration-500 ${
            msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'
          }`}
        >
          {/* Avatar (Agent Only) */}
          {msg.role === 'agent' && (
            <div className="flex-shrink-0 w-8 h-8 rounded-full overflow-hidden mt-1 shadow-sm border border-white/10">
              <img src={AVATAR_URL} alt="Agent" className="w-full h-full object-cover" />
            </div>
          )}

          {/* Content Container */}
          <div className={`flex flex-col gap-2 max-w-full ${
            msg.role === 'user' ? 'items-end' : 'items-start'
          } flex-1 min-w-0`}>

            {/* Thinking Process Block */}
            {msg.thoughtProcess && (
                <div className="bg-gray-900/80 border border-white/10 rounded-2xl overflow-hidden max-w-[90%] mb-1">
                    <button 
                        onClick={() => setIsThinkingExpanded(!isThinkingExpanded)}
                        className="flex items-center gap-2 w-full px-4 py-2.5 bg-white/5 hover:bg-white/10 transition-colors text-xs font-bold text-gray-400 uppercase tracking-wide"
                    >
                        <Brain size={14} className={isThinkingExpanded ? "text-indigo-400" : "text-gray-500"} />
                        <span>深度思考过程</span>
                        {isThinkingExpanded ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
                    </button>

                    {isThinkingExpanded && (
                        <div className="px-4 py-3 bg-black/20 text-xs text-gray-400 leading-relaxed whitespace-pre-wrap font-mono border-t border-white/5">
                            {msg.thoughtProcess}
                        </div>
                    )}
                </div>
            )}

            {/* Text Bubble */}
            {msg.text && (
              <div 
                className={`px-4 py-2.5 rounded-2xl text-[15px] leading-relaxed max-w-[85%] shadow-sm border ${
                  msg.role === 'user' 
                    ? 'bg-indigo-600 text-white border-transparent rounded-br-none' 
                    : 'bg-gray-900 text-gray-100 border-white/10 rounded-bl-none'
                }`}
              >
                {msg.text}
              </div>
            )}

            {/* Loading Indicator */}
            {msg.isLoading && (
               <div className="bg-gray-900 px-4 py-3 rounded-2xl rounded-bl-none border border-white/10 shadow-sm flex items-center gap-1.5">
                  <div className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                  <div className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                  <div className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce"></div>
               </div>
            )}

            {/* Rich Cards based on Type */}
            {!msg.isLoading && msg.type === 'character_card' && msg.characterData && (
              <CharacterSelectionCard 
                characters={msg.characterData} 
                onConfirm={() => onCardClick(msg.id, 'confirm_characters')}
                onCharacterClick={(char) => onCardClick(msg.id, 'view_character', { initialCharacter: char, allCharacters: msg.characterData })}
              />
            )}

            {!msg.isLoading && msg.type === 'script_card' && msg.scriptData && (
              <ScriptCard 
                data={msg.scriptData} 
                onConfirm={() => onCardClick(msg.id, 'confirm_script', msg.scriptData)}
                onEdit={() => onCardClick(msg.id, 'open_script', msg.scriptData)}
              />
            )}

            {!msg.isLoading && msg.type === 'storyboard_card' && msg.storyboardData && (
              <StoryboardCard 
                images={msg.storyboardData} 
                onImageClick={(img) => onCardClick(msg.id, 'view_image', { initialImage: img, allImages: msg.storyboardData })}
                onConfirm={() => onCardClick(msg.id, 'confirm_storyboard', msg.storyboardData)}
              />
            )}

            {!msg.isLoading && msg.type === 'audio_selection' && msg.audioOptions && (
              <AudioSelectionCard 
                options={msg.audioOptions} 
                onSelect={(id) => onCardClick(msg.id, 'select_audio', id)}
              />
            )}

            {!msg.isLoading && msg.type === 'video_card' && msg.videoData && (
                <VideoCard 
                    thumbnail={msg.videoData.thumbnail}
                    duration={msg.videoData.duration}
                    segments={msg.videoData.segments}
                    onEdit={() => onCardClick(msg.id, 'play_video', msg.videoData)}
                />
            )}
          </div>
        </div>
    );
};

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ messages, onCardClick }) => {
  const bottomRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom on new message
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages.length, messages[messages.length - 1]?.isLoading]);

  return (
    <div className="flex-1 overflow-y-auto px-4 py-4 space-y-6 custom-scrollbar">
      {/* Intro Spacer */}
      <div className="h-4"></div>

      {messages.map((msg) => (
         <MessageItem key={msg.id} msg={msg} onCardClick={onCardClick} />
      ))}
      <div ref={bottomRef} />
    </div>
  );
};

