                currentThought += chunk;

                setMessages(prev => prev.map(m => 
                    m.id === agentMsgId 
                        ? { ...m, thoughtProcess: currentThought } 
                        : m
                ));
                i += chunkSize;
            } else {
                clearInterval(streamInterval);

                // 3. Finish Thinking -> Show Final Text
                setMessages(prev => prev.map(m => 
                    m.id === agentMsgId 
                        ? { ...m, thoughtProcess: fullThought, text: '收到！根据你的描述，我草拟了以下脚本结构：' } 
                        : m
                ));

                // 4. Append Script Card
                setTimeout(() => {
                    addMsg({ role: 'agent', type: 'script_card', scriptData: MOCK_SCRIPT });
                    setIsAgentThinking(false); // Enable input again
                }, 600);
            }
        }, 15); // Fast streaming speed

        return; // Return early to bypass default timeout logic below
