import { MOCK_SCRIPT, MOCK_STORYBOARD, MOCK_CHARACTERS } from './constants';

export default function App() {
  const [messages, setMessages] = useState<Message[]>([
    { 
      id: 'init', 
      role: 'agent', 
      type: 'text', 
      text: '嗨！今天想制作什么视频？', 
      timestamp: Date.now() 
    }
  ]);
  const [overlay, setOverlay] = useState<OverlayState>({ type: 'none' });
  const [isAgentThinking, setIsAgentThinking] = useState(false);

  // --- Helper to add message ---
  const addMsg = (msg: Partial<Message>) => {
    setMessages(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      role: 'agent',
      type: 'text',
      ...msg
    } as Message]);
  };

  // --- CORE GENERATION LOGIC ---
  const generateScript = (prompt: string, isRegeneration = false) => {
      const agentMsgId = `agent-${Date.now()}`;

      // 1. Prepare Thought Process Text
      const thoughtTitle = isRegeneration ? "Analysis Task: Script Optimization" : "Analysis Task: Video Script Generation";
      const inputSection = isRegeneration 
          ? `> Modification Request: "${prompt}"\n> Current State: Script Exists`
          : `> Inputs Detected: Cyberpunk, Vlog, Funny\n> Constraints: 30s duration`;

      const reasoningSection = isRegeneration
          ? `> Reasoning Chain:\n  1. Critique: User requested adjustments based on "${prompt}".\n  2. Adjustment: Refine visual descriptions and tighten pacing.\n  3. Tone Check: Ensure cyberpunk aesthetic matches new requirements.`
          : `> Reasoning Chain:\n  1. Style Fusion: Blend high-tech aesthetics with grounded pacing.\n  2. Pacing Strategy: 30s = 3 beats (Hook -> Action -> Punchline).\n  3. Visual Elements: Neon lights, rain, holographic overlays.`;

      const fullThought = `${thoughtTitle}
-----------------------------------
${inputSection}

${reasoningSection}

> Output Generation:
  - Title: Neon Hotpot (霓虹火锅) ${isRegeneration ? 'v2.0' : ''}
  - Scene Flow: Cityscape -> Food (Macro) -> Tech (Detail).`;

      // 2. Initialize Agent Message (Empty)
      setMessages(prev => [...prev, {
          id: agentMsgId,
          role: 'agent',
          type: 'text',
          thoughtProcess: '',
          text: '',
          timestamp: Date.now()
      }]);

      // 3. Stream Thought Process
      let currentThought = '';
      const chunkSize = 8;
      let i = 0;

      const streamInterval = setInterval(() => {
          if (i < fullThought.length) {
              currentThought += fullThought.slice(i, i + chunkSize);
              setMessages(prev => prev.map(m => m.id === agentMsgId ? { ...m, thoughtProcess: currentThought } : m));
              i += chunkSize;
          } else {
              clearInterval(streamInterval);

              // 4. Finalize
              const responseText = isRegeneration 
                  ? `没问题，根据您的要求"${prompt}"，我重新调整了脚本：`
                  : '收到！根据你的描述，我草拟了以下脚本结构：';

              // Create a slightly modified script for demo purposes
              const newScript = {
                  ...MOCK_SCRIPT,
                  title: isRegeneration ? `${MOCK_SCRIPT.title} (修改版)` : MOCK_SCRIPT.title,
                  lines: MOCK_SCRIPT.lines.map(l => ({
                      ...l,
                      visual: isRegeneration ? `${l.visual} (优化细节)` : l.visual
                  }))
              };

              setMessages(prev => prev.map(m => m.id === agentMsgId ? { ...m, thoughtProcess: fullThought, text: responseText } : m));

              setTimeout(() => {
                  addMsg({ role: 'agent', type: 'script_card', scriptData: newScript });
                  setIsAgentThinking(false);
              }, 600);
          }
      }, 10);
  };

  const handleUserMessage = async (text: string) => {
    // 1. Add User Message
    addMsg({ role: 'user', text, type: 'text' });

    // 2. Determine Context
    const lastAgentMsg = [...messages].reverse().find(m => m.role === 'agent' && m.type !== 'text'); // Find last rich card
    const lastAgentType = lastAgentMsg?.type;

    // 3. Routing Logic
    if (lastAgentType === 'script_card') {
        // CONTEXT: SCRIPT EXISTS -> TREAT INPUT AS MODIFICATION
        setIsAgentThinking(true);
        setTimeout(() => {
             generateScript(text, true);
        }, 800);
        return;
    }

    if (lastAgentType === 'character_card') {
         // CONTEXT: CHARACTERS EXIST -> TREAT INPUT AS CHARACTER MODIFICATION
         setIsAgentThinking(true);
         const loadingId = 'loading-' + Date.now();
         setMessages(prev => [...prev, { id: loadingId, role: 'agent', type: 'text', isLoading: true, timestamp: Date.now() }]);

         setTimeout(() => {
             setMessages(prev => prev.filter(m => m.id !== loadingId));

             // Analyze text to find target (Mock logic)
             let targetIndex = -1;
             if (text.includes('二') || text.includes('2')) targetIndex = 1;
             else if (text.includes('一') || text.includes('1')) targetIndex = 0;
             else if (text.includes('三') || text.includes('3')) targetIndex = 2;

             const currentChars = lastAgentMsg?.characterData || MOCK_CHARACTERS;
             const updatedChars = currentChars.map((char, idx) => {
                 if (targetIndex !== -1 && idx !== targetIndex) return char;
                 return {
                     ...char,
                     imageUrl: `https://picsum.photos/200/200?random=${Date.now() + idx}`,
                     description: `${char.description} (已根据要求优化)`
                 };
             });

             const responseText = targetIndex !== -1 
                ? `好的，已为您重新设计第 ${targetIndex + 1} 个角色。`
                : `没问题，根据您的反馈"${text}"，我调整了角色设计。`;

             addMsg({ role: 'agent', text: responseText });
             setTimeout(() => {
                 addMsg({ role: 'agent', type: 'character_card', characterData: updatedChars });
                 setIsAgentThinking(false);
             }, 500);
         }, 1500);
         return;
    }

    if (lastAgentType === 'storyboard_card') {
         // CONTEXT: STORYBOARD EXISTS -> TREAT INPUT AS IMAGE MODIFICATION
         setIsAgentThinking(true);
         const loadingId = 'loading-' + Date.now();
         setMessages(prev => [...prev, { id: loadingId, role: 'agent', type: 'text', isLoading: true, timestamp: Date.now() }]);

         setTimeout(() => {
             setMessages(prev => prev.filter(m => m.id !== loadingId));
             addMsg({ role: 'agent', text: '好的，正在根据您的反馈调整分镜画面...' });

             // Modify first image for demo
             const updatedStoryboard = (lastAgentMsg?.storyboardData || MOCK_STORYBOARD).map((img, idx) => {
                 if (idx === 0) return { ...img, description: `${img.description} (已修改: ${text})`, src: `https://picsum.photos/400/600?random=${Date.now()}` };
                 return img;
             });

             setTimeout(() => {
                 addMsg({ role: 'agent', type: 'storyboard_card', storyboardData: updatedStoryboard });
                 setIsAgentThinking(false);
             }, 1000);
         }, 1000);
         return;
    }

    // DEFAULT: NEW GENERATION
    setIsAgentThinking(true);
    const loadingId = 'loading-' + Date.now();
    setMessages(prev => [...prev, { id: loadingId, role: 'agent', type: 'text', isLoading: true, timestamp: Date.now() }]);

    setTimeout(() => {
      setMessages(prev => prev.filter(m => m.id !== loadingId));

      // If no context, start fresh script generation
      generateScript(text, false);

    }, 1500);
  };

  // --- INTERACTION HANDLERS ---
  const handleCardClick = useCallback((msgId: string, action: string, data?: any) => {
    if (action === 'regenerate_script') {
        // User clicked "Regenerate Script" button
        addMsg({ role: 'user', text: '重新生成脚本', type: 'text' });
        setIsAgentThinking(true);
        setTimeout(() => {
            generateScript("换一种风格", true);
        }, 1000);

    } else if (action === 'confirm_script') {
        // Step 2: Script Confirmed -> Proceed to Character Extraction
        const scriptData = data as ScriptData;
        setIsAgentThinking(true);
        setTimeout(() => {
            setIsAgentThinking(false);
            addMsg({ role: 'agent', text: '脚本已确认！基于此脚本，我提取了以下核心角色，请确认定妆照：' });
            addMsg({ role: 'agent', type: 'character_card', characterData: MOCK_CHARACTERS });
        }, 1000);

    } else if (action === 'confirm_characters') {
        // Step 3: Characters Confirmed -> Proceed to Storyboard Generation
        setIsAgentThinking(true);
        setTimeout(() => {
             setIsAgentThinking(false);
             const scriptMsg = [...messages].reverse().find(m => m.type === 'script_card');
             const scriptData = scriptMsg?.scriptData || MOCK_SCRIPT;

             addMsg({ role: 'agent', text: '角色已确认。正在根据脚本和角色设定生成分镜...' });

            const generatedStoryboard: StoryboardImage[] = scriptData.lines.map((line) => ({
                id: `img-${line.id}`,
                src: `https://picsum.photos/400/600?random=${line.id}-${Date.now()}`, 
                prompt: line.visual,
                description: line.visual.length > 50 ? line.visual.substring(0, 47) + '...' : line.visual,
                subtitle: line.audio
            }));

            setTimeout(() => {
                addMsg({ 
                    role: 'agent', 
                    type: 'storyboard_card', 
                    storyboardData: generatedStoryboard.length > 0 ? generatedStoryboard : MOCK_STORYBOARD 
                });
            }, 1500);
        }, 500);

    } else if (action === 'confirm_storyboard') {
        // Step 4: Storyboard Confirmed -> Proceed to Video Generation
         const finalStoryboard = (data as StoryboardImage[]) || MOCK_STORYBOARD;

         setIsAgentThinking(true);
         setTimeout(() => {
             setIsAgentThinking(false);
             addMsg({ role: 'agent', text: '分镜已确认！正在渲染最终视频...' });

             setTimeout(() => {
                 const segments: VideoSegment[] = finalStoryboard.map((img, idx) => ({
                     id: `seg-${idx}`,
                     thumbnail: img.src,
                     duration: ['5s', '10s', '8s'][idx] || '5s',
                     description: img.description
                 }));

                 addMsg({ 
                     role: 'agent', 
                     type: 'video_card', 
                     videoData: {
                         thumbnail: finalStoryboard[0].src, 
                         videoUrl: '#',
                         duration: '23s',
                         segments: segments
                     } 
                 });
             }, 2500);
         }, 500);

    } else if (action === 'open_script') {
      setOverlay({ type: 'script_editor', data: data });

    } else if (action === 'view_image') {
      setOverlay({ type: 'image_viewer', data: data });

    } else if (action === 'view_character') {
        setOverlay({ type: 'character_viewer', data: data });

    } else if (action === 'play_video') {
        setOverlay({ type: 'video_player', data: data });
    }
  }, [messages]);

  const handleScriptSave = (newData: ScriptData) => {
    setOverlay({ type: 'none' });
    setMessages(prev => prev.map(m => 
       m.type === 'script_card' ? { ...m, scriptData: newData } : m
    ));
  };

  const handleAiScriptModification = (prompt: string, currentScript: ScriptData) => {
      setOverlay({ type: 'none' });
      addMsg({ role: 'user', text: prompt, type: 'text' });
      setIsAgentThinking(true);
      setTimeout(() => {
          generateScript(prompt, true);
      }, 1000);
  };

  const handleImageUpdate = (updatedImg: StoryboardImage) => {
     setMessages(prev => prev.map(msg => {
         if (msg.type === 'storyboard_card' && msg.storyboardData) {
             return {
                 ...msg,
                 storyboardData: msg.storyboardData.map(img => 
                     img.id === updatedImg.id ? updatedImg : img
                 )
             };
         }
         return msg;
     }));
  };

  const handleCharacterUpdate = (updatedChar: CharacterDesign) => {
    setMessages(prev => prev.map(msg => {
        if (msg.type === 'character_card' && msg.characterData) {
            return {
                ...msg,
                characterData: msg.characterData.map(c => 
                    c.id === updatedChar.id ? updatedChar : c
                )
            };
        }
        return msg;
    }));
  };

  return (
    <div className="flex justify-center bg-black h-screen w-screen overflow-hidden">
      <div className="w-full max-w-md h-full bg-black flex flex-col relative shadow-2xl overflow-hidden md:border-x border-gray-800">

        <header className="flex items-center justify-between p-4 pt-6 bg-transparent absolute top-0 left-0 right-0 z-10">
           <button className="text-white/80 hover:text-white p-1 rounded-full active:bg-white/10 transition-colors">
              <ChevronLeft size={28} />
           </button>
           <button className="text-white/80 hover:text-white p-1 rounded-full active:bg-white/10 transition-colors">
              <Lightbulb size={24} />
           </button>
        </header>

        <ChatInterface 
          messages={messages} 
          onCardClick={handleCardClick} 
        />

        <InputArea 
            onSendMessage={handleUserMessage} 
            disabled={isAgentThinking} 
        />

        {overlay.type === 'script_editor' && (
          <ScriptEditor 
            initialData={overlay.data} 
            onClose={() => setOverlay({ type: 'none' })}
            onConfirm={handleScriptSave} 
            onAiEditRequest={(prompt) => handleAiScriptModification(prompt, overlay.data)}
          />
        )}

        {overlay.type === 'image_viewer' && (
          <ImageViewer
            initialImage={overlay.data.initialImage}
            allImages={overlay.data.allImages}
            onClose={() => setOverlay({ type: 'none' })}
            onUpdate={handleImageUpdate}
          />
        )}

        {overlay.type === 'character_viewer' && (
            <CharacterViewer
                initialCharacter={overlay.data.initialCharacter}
                allCharacters={overlay.data.allCharacters}
                onClose={() => setOverlay({ type: 'none' })}
                onUpdate={handleCharacterUpdate}
            />
        )}

        {overlay.type === 'video_player' && (
            <VideoPlayer
                thumbnail={overlay.data.thumbnail}
                segments={overlay.data.segments}
                onClose={() => setOverlay({ type: 'none' })}
            />
        )}

      </div>
    </div>
  );
}

