import { ScriptCard, StoryboardCard, AudioSelectionCard, VideoCard, CharacterSelectionCard } from './ImmersiveCards';

interface ChatInterfaceProps {
  messages: Message[];
  onCardClick: (msgId: string, action: string, data?: any) => void;
}

const MessageItem: React.FC<{ msg: Message; onCardClick: (msgId: string, action: string, data?: any) => void }> = ({ msg, onCardClick }) => {
    const [isThinkingExpanded, setIsThinkingExpanded] = useState(true);

    return (
        <div 
          className={`flex gap-3 w-full animate-in slide-in-from-bottom-4 duration-700 ${
            msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'
          }`}
        >
          {/* Avatar (Agent Only) */}
          {msg.role === 'agent' && (
            <div className="flex-shrink-0 w-8 h-8 rounded-full overflow-hidden mt-1 shadow-[0_0_10px_rgba(255,255,255,0.2)] border border-white/20">
              <img src={AVATAR_URL} alt="Agent" className="w-full h-full object-cover scale-110" />
            </div>
          )}

          {/* Content Container */}
          <div className={`flex flex-col gap-2 max-w-full ${
            msg.role === 'user' ? 'items-end' : 'items-start'
          } flex-1 min-w-0`}>

            {/* Thinking Process Block (Cyberpunk Terminal Style) */}
            {msg.thoughtProcess && (
                <div className="bg-black/40 border border-indigo-500/20 rounded-xl overflow-hidden max-w-[95%] mb-2 backdrop-blur-md shadow-lg group">
                    <button 
                        onClick={() => setIsThinkingExpanded(!isThinkingExpanded)}
                        className="flex items-center gap-2 w-full px-3 py-2 bg-white/5 hover:bg-white/10 transition-colors text-[10px] font-bold text-indigo-300 uppercase tracking-widest select-none"
                    >
                        <Terminal size={12} className={isThinkingExpanded ? "text-indigo-400 animate-pulse" : "text-gray-500"} />
                        <span>AI_KERNEL_PROCESS</span>
                        <div className="flex-1 h-px bg-indigo-500/20 mx-2" />
                        {isThinkingExpanded ? <ChevronDown size={12} /> : <ChevronRight size={12} />}
                    </button>

                    {isThinkingExpanded && (
                        <div className="px-4 py-3 bg-black/30 text-[11px] text-indigo-100/70 leading-relaxed whitespace-pre-wrap font-mono border-t border-white/5 min-h-[40px] shadow-inner relative">
                            <div className="absolute top-0 left-0 w-1 h-full bg-indigo-500/20" />
                            {msg.thoughtProcess}
                            {!msg.text && (
                                <span className="inline-block w-1.5 h-3 bg-indigo-400 ml-1 animate-pulse align-middle" />
                            )}
                        </div>
                    )}
                </div>
            )}

            {/* Text Bubble */}
            {msg.text && (
              <div 
                className={`px-5 py-3 rounded-2xl text-[15px] leading-relaxed max-w-[85%] shadow-lg border backdrop-blur-md ${
                  msg.role === 'user' 
                    ? 'bg-gradient-to-br from-indigo-600 to-purple-600 text-white border-transparent rounded-br-none' 
                    : 'glass-bubble-agent text-gray-100 rounded-bl-none border-white/10'
                }`}
              >
                {msg.text}
              </div>
            )}

            {/* Loading Indicator */}
            {msg.isLoading && (
               <div className="glass-bubble-agent px-4 py-3 rounded-2xl rounded-bl-none shadow-lg flex items-center gap-1.5 max-w-[80px]">
                  <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-[bounce_1s_infinite_-0.3s]"></div>
                  <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-[bounce_1s_infinite_-0.15s]"></div>
                  <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-[bounce_1s_infinite]"></div>
               </div>
            )}

            {/* Rich Cards */}
            {!msg.isLoading && (
                <div className="w-full animate-in fade-in zoom-in-95 duration-500 slide-in-from-bottom-2">
                    {msg.type === 'character_card' && msg.characterData && (
                    <CharacterSelectionCard 
                        characters={msg.characterData} 
                        onConfirm={() => onCardClick(msg.id, 'confirm_characters')}
                        onCharacterClick={(char) => onCardClick(msg.id, 'view_character', { initialCharacter: char, allCharacters: msg.characterData })}
                    />
                    )}

                    {msg.type === 'script_card' && msg.scriptData && (
                    <ScriptCard 
                        data={msg.scriptData} 
                        onConfirm={() => onCardClick(msg.id, 'confirm_script', msg.scriptData)}
                        onEdit={() => onCardClick(msg.id, 'open_script', msg.scriptData)}
                    />
                    )}

                    {msg.type === 'storyboard_card' && msg.storyboardData && (
                    <StoryboardCard 
                        images={msg.storyboardData} 
                        onImageClick={(img) => onCardClick(msg.id, 'view_image', { initialImage: img, allImages: msg.storyboardData })}
                        onConfirm={() => onCardClick(msg.id, 'confirm_storyboard', msg.storyboardData)}
                    />
                    )}

                    {msg.type === 'audio_selection' && msg.audioOptions && (
                    <AudioSelectionCard 
                        options={msg.audioOptions} 
                        onSelect={(id) => onCardClick(msg.id, 'select_audio', id)}
                    />
                    )}

                    {msg.type === 'video_card' && msg.videoData && (
                        <VideoCard 
                            thumbnail={msg.videoData.thumbnail}
                            duration={msg.videoData.duration}
                            segments={msg.videoData.segments}
                            onEdit={() => onCardClick(msg.id, 'play_video', msg.videoData)}
                        />
                    )}
                </div>
            )}
          </div>
        </div>
    );
};

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ messages, onCardClick }) => {
  const bottomRef = useRef<HTMLDivElement>(null);
  const lastMsg = messages[messages.length - 1];

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages.length, lastMsg?.isLoading, lastMsg?.thoughtProcess?.length]);

  return (
    <div className="flex-1 overflow-y-auto px-4 py-4 space-y-6 custom-scrollbar z-10 pt-20">
        {/* Date / Time Separator Idea */}
        <div className="flex justify-center mb-4 opacity-0 animate-in fade-in duration-1000">
            <span className="text-[10px] font-mono text-white/20 uppercase tracking-widest bg-white/5 px-2 py-1 rounded-full backdrop-blur-sm">
                Session Start: {new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
            </span>
        </div>

      {messages.map((msg) => (
         <MessageItem key={msg.id} msg={msg} onCardClick={onCardClick} />
      ))}
      <div ref={bottomRef} className="h-4" />
    </div>
  );
};

import React, { useState } from 'react';
import { ArrowUp, Smartphone, Square, Monitor, Film, Sparkles } from 'lucide-react';
import { INITIAL_CHIPS } from '../constants';

interface InputAreaProps {
  onSendMessage: (text: string) => void;
  disabled?: boolean;
}

export const InputArea: React.FC<InputAreaProps> = ({ onSendMessage, disabled }) => {
  const [inputValue, setInputValue] = useState('');
  const [aspectRatio, setAspectRatio] = useState<'9:16' | '16:9' | '1:1'>('9:16');
  const [resolution, setResolution] = useState<'1080P' | '4K'>('1080P');

  const handleSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (inputValue.trim() && !disabled) {
      onSendMessage(inputValue);
      setInputValue('');
    }
  };

  const handleChipClick = (chip: string) => {
    setInputValue((prev) => prev ? `${prev} ${chip}` : chip);
  };

  const toggleRatio = () => {
    const map: Record<string, '9:16' | '16:9' | '1:1'> = { '9:16': '16:9', '16:9': '1:1', '1:1': '9:16' };
    setAspectRatio(map[aspectRatio]);
  };

  const toggleResolution = () => {
    setResolution(prev => prev === '1080P' ? '4K' : '1080P');
  };

  return (
    <div className="flex-shrink-0 z-20 w-full px-4 mb-safe-bottom pb-4 pt-2 bg-gradient-to-t from-black via-black/80 to-transparent">

      {/* Chips Row (Floating) */}
      <div className="overflow-x-auto no-scrollbar py-2 flex gap-2 mb-2 mask-linear-fade">
        {INITIAL_CHIPS.map((chip) => (
          <button
            key={chip}
            onClick={() => handleChipClick(chip)}
            disabled={disabled}
            className="flex-shrink-0 px-3 py-1.5 bg-white/5 backdrop-blur-md text-gray-300 text-[11px] font-medium rounded-full border border-white/10 hover:bg-indigo-500/20 hover:border-indigo-500/30 hover:text-indigo-200 active:scale-95 transition-all shadow-sm"
          >
            {chip}
          </button>
        ))}
      </div>

      {/* Floating Composer Bar */}
      <div className="glass-panel rounded-[26px] p-1.5 pr-2 flex items-end gap-2 shadow-2xl relative overflow-hidden group">

        {/* Subtle glow effect */}
        <div className="absolute inset-0 bg-gradient-to-r from-indigo-500/5 to-purple-500/5 pointer-events-none" />

        {/* Text Input */}
        <div className="flex-1 relative min-h-[44px] flex items-center">
            <textarea
                className="w-full bg-transparent border-none focus:ring-0 p-3 text-[15px] text-white placeholder-gray-500 resize-none outline-none leading-relaxed max-h-24 custom-scrollbar"
                placeholder="描述画面或修改意见..."
                rows={1}
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                        e.preventDefault();
                        handleSubmit();
                    }
                }}
                disabled={disabled}
                style={{ height: 'auto', minHeight: '44px' }}
            />
        </div>

        {/* Action Toolbar */}
        <div className="flex items-center gap-1.5 mb-1">
            {/* Aspect Ratio Toggle */}
            <button 
                onClick={toggleRatio}
                disabled={disabled}
                className="h-9 px-2.5 rounded-xl bg-white/5 hover:bg-white/10 flex items-center justify-center text-gray-400 hover:text-gray-200 transition-colors border border-white/5"
                title="Aspect Ratio"
            >
                {aspectRatio === '9:16' && <Smartphone size={16} />}
                {aspectRatio === '16:9' && <Monitor size={16} />}
                {aspectRatio === '1:1' && <Square size={16} />}
                <span className="text-[10px] font-bold ml-1.5">{aspectRatio}</span>
            </button>

             {/* Resolution Toggle */}
             <button 
                onClick={toggleResolution}
                disabled={disabled}
                className={`h-9 px-2.5 rounded-xl bg-white/5 hover:bg-white/10 flex items-center justify-center transition-colors border border-white/5 ${resolution === '4K' ? 'text-purple-300 border-purple-500/20 bg-purple-500/10' : 'text-gray-400'}`}
                title="Resolution"
            >
                <Film size={16} />
                <span className="text-[10px] font-bold ml-1.5">{resolution}</span>
            </button>

            {/* Send Button */}
            <button
                onClick={() => handleSubmit()}
                disabled={disabled || !inputValue.trim()}
                className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg transition-all active:scale-95 ml-1 ${
                    inputValue.trim() 
                    ? 'bg-indigo-600 text-white hover:bg-indigo-500 shadow-[0_0_15px_rgba(79,70,229,0.4)]' 
                    : 'bg-white/10 text-white/20 cursor-not-allowed'
                }`}
            >
                {disabled ? (
                    <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                ) : (
                    <ArrowUp size={20} strokeWidth={2.5} />
                )}
            </button>
        </div>
      </div>
    </div>
  );
};

