/* --- VIDEO RESULT CARD --- */
interface VideoCardProps {
  thumbnail: string;
  duration: string;
  segments?: VideoSegment[];
  onEdit: () => void;
}

export const VideoCard: React.FC<VideoCardProps> = ({ thumbnail, duration, segments = [], onEdit }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentThumb, setCurrentThumb] = useState(thumbnail);

  const slides = segments.length > 0 ? segments.map(s => s.thumbnail) : [thumbnail];

  useEffect(() => {
    let interval: any;
    if (isPlaying && slides.length > 1) {
      let idx = slides.indexOf(currentThumb);
      if (idx === -1) idx = 0;

      interval = setInterval(() => {
        idx = (idx + 1) % slides.length;
        setCurrentThumb(slides[idx]);
      }, 600);
    } else {
        setCurrentThumb(thumbnail);
    }
    return () => clearInterval(interval);
  }, [isPlaying, slides, thumbnail]);

  return (
    <div className="w-full max-w-[75%] relative group select-none">
      {/* Glow Effect */}
      <div className="absolute -inset-1 bg-gradient-to-tr from-indigo-500 to-purple-500 rounded-3xl blur opacity-30 group-hover:opacity-50 transition-opacity duration-700" />

      <div 
        onClick={() => setIsPlaying(!isPlaying)}
        className="relative aspect-[9/16] rounded-2xl overflow-hidden bg-black border border-white/10 cursor-pointer shadow-2xl"
      >
        <img 
            src={currentThumb} 
            alt="Video Preview" 
            className="w-full h-full object-cover transition-all duration-300 group-hover:scale-105" 
        />

        {/* Play Button Overlay */}
        {!isPlaying && (
          <div className="absolute inset-0 flex items-center justify-center bg-black/20 backdrop-blur-[2px]">
            <div className="w-16 h-16 rounded-full bg-white/10 backdrop-blur-md flex items-center justify-center border border-white/30 shadow-[0_0_20px_rgba(0,0,0,0.5)] scale-100 active:scale-95 transition-all group-hover:bg-white/20">
               <Play size={32} fill="white" className="text-white ml-1" />
            </div>
          </div>
        )}

        <div className="absolute top-3 left-3 flex gap-2">
            <div className="bg-[#10B981]/90 backdrop-blur px-2.5 py-1 rounded-lg text-[10px] text-white font-bold tracking-wide shadow-lg border border-white/10 flex items-center gap-1">
                <span>RENDERED</span>
            </div>
        </div>

        <div className="absolute bottom-3 right-3 bg-black/70 px-2.5 py-1 rounded-lg text-xs text-white/90 font-mono backdrop-blur-md border border-white/10">
          {duration}
        </div>
      </div>

      <button 
        onClick={(e) => {
            e.stopPropagation(); 
            onEdit();
        }}
        className="absolute -right-4 -bottom-2 p-3 bg-white text-black rounded-full shadow-xl hover:bg-gray-200 transition-all active:scale-95 z-20"
      >
        <Edit3 size={18} />
      </button>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { X, Check, ArrowLeft, Send, Sparkles, GripVertical, Trash2, Play, RefreshCw, Wand2, Film, MessageSquare, ChevronRight, ChevronLeft, Type, MoreHorizontal } from 'lucide-react';
import { ScriptData, ScriptLine, StoryboardImage, VideoSegment, CharacterDesign } from '../types';

/* --- FULLSCREEN SCRIPT EDITOR --- */
interface ScriptEditorProps {
  initialData: ScriptData;
  onClose: () => void;
  onConfirm: (newData: ScriptData) => void;
  onAiEditRequest: (prompt: string) => void;
}

export const ScriptEditor: React.FC<ScriptEditorProps> = ({ initialData, onClose, onConfirm, onAiEditRequest }) => {
  const [lines, setLines] = useState<ScriptLine[]>(initialData.lines);
  const [isClosing, setIsClosing] = useState(false);
  const [aiPrompt, setAiPrompt] = useState('');
  const [isAiProcessing, setIsAiProcessing] = useState(false);

  const handleClose = () => {
    setIsClosing(true);
    setTimeout(onClose, 300);
  };

  const handleSave = () => {
    setIsClosing(true);
    setTimeout(() => onConfirm({ ...initialData, lines }), 300);
  };

  const handleTextChange = (id: string, field: 'visual' | 'audio', val: string) => {
    setLines(lines.map(l => l.id === id ? { ...l, [field]: val } : l));
  };

  const handleDeleteLine = (id: string) => {
    setLines(lines.filter(l => l.id !== id));
  };

  const handleAiEdit = () => {
      if (!aiPrompt.trim()) return;
      setIsClosing(true);
      setTimeout(() => {
          onClose();
          onAiEditRequest(aiPrompt);
      }, 300);
  };

  return (
    <div className={`fixed inset-0 z-50 bg-black/95 backdrop-blur-xl flex flex-col transition-all duration-300 ${isClosing ? 'opacity-0 translate-y-10' : 'opacity-100 translate-y-0'}`}>

      {/* Immersive Header */}
      <div className="flex items-center justify-between p-4 pt-safe z-10 border-b border-white/5 bg-black/40 backdrop-blur-md">
        <button 
            onClick={handleClose} 
            className="p-2 -ml-2 text-gray-400 hover:text-white rounded-full transition-colors active:scale-95"
        >
          <ChevronLeft size={28} />
        </button>

        <div className="flex flex-col items-center">
            <span className="font-bold text-gray-100 text-sm tracking-wide">脚本编辑</span>
            <span className="text-[10px] text-gray-500 font-mono">{initialData.totalDuration} • {lines.length} Shots</span>
        </div>

        <button 
            onClick={handleSave} 
            className="px-4 py-1.5 bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-bold rounded-full transition-all shadow-lg active:scale-95 flex items-center gap-1"
        >
            <span>保存</span>
        </button>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto p-4 space-y-6 pb-32 custom-scrollbar">
          {lines.map((line, index) => (
            <div key={line.id} className="relative pl-8 group animate-in slide-in-from-bottom-4 duration-500" style={{ animationDelay: `${index * 50}ms` }}>

              {/* Timeline Connector */}
              <div className="absolute left-3.5 top-8 bottom-[-24px] w-px bg-white/10 group-last:hidden" />

              {/* Scene Number Bubble */}
              <div className="absolute left-0 top-0 w-7 h-7 rounded-full bg-gray-800 border border-white/10 flex items-center justify-center z-10 shadow-sm">
                  <span className="text-[10px] font-mono font-bold text-gray-400">{String(index + 1).padStart(2, '0')}</span>
              </div>

              <div className="flex flex-col gap-3 bg-white/5 rounded-2xl p-4 border border-white/5 hover:border-white/10 transition-colors relative">

                {/* Visual Field */}
                <div className="space-y-1.5">
                    <div className="flex items-center justify-between">
                         <label className="text-[10px] font-bold text-blue-400 tracking-wider uppercase flex items-center gap-1.5">
                            <div className="w-1.5 h-1.5 rounded-full bg-blue-500 shadow-[0_0_8px_rgba(59,130,246,0.5)]"></div>
                            Visual
                         </label>
                         <button onClick={() => handleDeleteLine(line.id)} className="opacity-0 group-hover:opacity-100 transition-opacity text-gray-600 hover:text-red-400 p-1">
                             <Trash2 size={12} />
                         </button>
                    </div>
                    <textarea 
                      value={line.visual}
                      onChange={(e) => handleTextChange(line.id, 'visual', e.target.value)}
                      className="w-full bg-black/20 rounded-xl p-3 text-sm text-gray-200 border border-transparent focus:border-blue-500/30 focus:bg-black/40 focus:ring-0 resize-none min-h-[60px] leading-relaxed transition-all placeholder-gray-600"
                      placeholder="描述画面细节..."
                    />
                </div>

                {/* Audio Field */}
                <div className="space-y-1.5">
                    <label className="text-[10px] font-bold text-orange-400 tracking-wider uppercase flex items-center gap-1.5">
                        <div className="w-1.5 h-1.5 rounded-full bg-orange-500 shadow-[0_0_8px_rgba(249,115,22,0.5)]"></div>
                        Audio
                    </label>
                    <textarea 
                      value={line.audio}
                      onChange={(e) => handleTextChange(line.id, 'audio', e.target.value)}
                      className="w-full bg-black/20 rounded-xl p-3 text-xs text-gray-400 font-mono border border-transparent focus:border-orange-500/30 focus:bg-black/40 focus:ring-0 resize-none min-h-[48px] leading-relaxed italic transition-all placeholder-gray-600"
                      placeholder="旁白或音效..."
                    />
                </div>
              </div>
            </div>
          ))}

           {/* Add Button Hint */}
           <div className="flex justify-center pt-4 opacity-50">
               <span className="text-xs text-gray-600">到底了 ~</span>
           </div>
      </div>

      {/* AI Floating Bar */}
      <div className="absolute bottom-0 left-0 right-0 p-4 pb-8 bg-gradient-to-t from-black via-black/95 to-transparent z-20">
           <div className={`flex items-center gap-3 bg-[#1C1C1E] border border-white/10 rounded-2xl px-3 py-2 pl-4 shadow-2xl transition-all ${isAiProcessing ? 'opacity-80' : ''}`}>
              <Wand2 size={18} className={`text-indigo-400 ${isAiProcessing ? 'animate-spin' : ''}`} />
              <input 
                 type="text"
                 value={aiPrompt}
                 onChange={(e) => setAiPrompt(e.target.value)}
                 onKeyDown={(e) => e.key === 'Enter' && handleAiEdit()}
                 placeholder="输入 AI 指令 (例如: 让节奏更紧凑...)"
                 disabled={isAiProcessing}
                 className="flex-1 bg-transparent border-none text-sm text-gray-200 placeholder:text-gray-500 focus:ring-0 p-0 h-10"
              />
              <button 
                onClick={handleAiEdit}
                disabled={!aiPrompt || isAiProcessing}
                className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${aiPrompt && !isAiProcessing ? 'bg-indigo-600 text-white shadow-lg scale-100' : 'bg-white/5 text-gray-500 scale-95'}`}
              >
                 <ArrowLeft size={18} className={`rotate-90 ${aiPrompt ? 'text-white' : 'text-gray-500'}`} />
              </button>
           </div>
      </div>
    </div>
  );
};

/* --- FULLSCREEN IMAGE EDITOR --- */
interface ImageViewerProps {
  initialImage: StoryboardImage;
  allImages?: StoryboardImage[];
  onClose: () => void;
  onUpdate: (newImg: StoryboardImage) => void;
}

export const ImageViewer: React.FC<ImageViewerProps> = ({ initialImage, allImages = [], onClose, onUpdate }) => {
  const [prompt, setPrompt] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showSubtitles, setShowSubtitles] = useState(true);

  // Track the full list locally so we can update other thumbnails if needed, though mostly for display navigation
  const [sessionImages, setSessionImages] = useState<StoryboardImage[]>(allImages.length ? allImages : [initialImage]);
  const [currentIdx, setCurrentIdx] = useState(0);

  // Init index
  useEffect(() => {
    const idx = sessionImages.findIndex(img => img.id === initialImage.id);
    if (idx !== -1) setCurrentIdx(idx);
  }, []);

  const currentImg = sessionImages[currentIdx];

  const handleMagicEdit = () => {
    if (!prompt) return;
    setIsLoading(true);
    // Simulate generation
    setTimeout(() => {
      const newImg = {
        ...currentImg,
        src: `https://picsum.photos/400/600?random=${Date.now()}`, // Force new image
        description: prompt // Update description to match user intent
      };

      // Update local session state
      const newSessionImages = [...sessionImages];
      newSessionImages[currentIdx] = newImg;
      setSessionImages(newSessionImages);

      // Persist to parent
      onUpdate(newImg);

      setIsLoading(false);
      setPrompt('');
    }, 1500);
  };

  const handleSwitchImage = (idx: number) => {
      setCurrentIdx(idx);
      setPrompt(''); // Clear prompt input on switch
  };

  return (
    <div className="fixed inset-0 z-50 bg-black flex flex-col animate-in fade-in duration-300 overflow-hidden">

      {/* Blurred Background for Immersive Feel */}
      <div className="absolute inset-0 z-0 overflow-hidden">
        <img 
            src={currentImg?.src} 
            className="w-full h-full object-cover blur-3xl opacity-30 scale-110" 
            alt="Background blur"
        />
        <div className="absolute inset-0 bg-black/40" /> 
      </div>

      {/* Top Bar */}
      <div className="absolute top-0 left-0 right-0 p-4 pt-safe z-20 flex justify-between items-center bg-gradient-to-b from-black/60 to-transparent">
        <button onClick={onClose} className="text-white/90 hover:text-white p-2 bg-black/20 backdrop-blur-md rounded-full transition-colors">
          <ArrowLeft size={24} />
        </button>

        {/* Title (Optional) */}
        {/* <span className="text-white font-medium text-sm drop-shadow-md">分镜编辑器</span> */}

        <div className="flex items-center gap-3">
            <button 
                onClick={() => setShowSubtitles(!showSubtitles)}
                className={`p-2 rounded-full transition-all backdrop-blur-md ${
                    showSubtitles 
                    ? 'bg-white/20 text-white' 
                    : 'bg-black/20 text-white/60 hover:bg-black/40 hover:text-white'
                }`}
            >
                <Type size={20} />
            </button>
            <button 
                onClick={onClose} 
                className="text-black bg-white px-5 py-2 rounded-full text-xs font-bold hover:bg-gray-200 transition-colors shadow-lg"
            >
                完成
            </button>
        </div>
      </div>

      {/* Main Image Area */}
      <div className="flex-1 flex items-center justify-center relative w-full h-full pb-20 z-10">
         {isLoading && (
            <div className="absolute inset-0 z-30 flex flex-col items-center justify-center bg-black/60 backdrop-blur-sm">
                <RefreshCw className="w-8 h-8 text-indigo-500 animate-spin mb-3" />
                <p className="text-white text-sm font-medium animate-pulse">正在重新生成...</p>
            </div>
         )}

         <div className="relative w-full h-full flex items-center justify-center p-4">
             <img 
                src={currentImg?.src} 
                alt="Full view" 
                className={`max-w-full max-h-full object-contain shadow-2xl transition-opacity duration-500 ${isLoading ? 'opacity-50' : 'opacity-100'}`}
             />

             {/* Subtitle Overlay */}
             {showSubtitles && currentImg.subtitle && (
                <div className="absolute bottom-[15%] left-6 right-6 text-center pointer-events-none z-20 animate-in fade-in slide-in-from-bottom-2">
                    <span className="inline-block bg-black/60 backdrop-blur-md px-4 py-3 rounded-xl text-white text-sm md:text-base font-medium shadow-lg leading-relaxed border border-white/10">
                        {currentImg.subtitle}
                    </span>
                </div>
             )}
         </div>
      </div>

      {/* Bottom Floating Input (Magic Edit) */}
      <div className="absolute bottom-0 left-0 right-0 z-20 bg-gradient-to-t from-black via-black/80 to-transparent pt-10 pb-safe px-4">
        <div className="flex flex-col gap-3 max-w-md mx-auto w-full">
            {/* Thumbnails Navigation */}
            {sessionImages.length > 1 && (
                <div className="flex gap-2 overflow-x-auto no-scrollbar pb-2 justify-center px-4">
                    {sessionImages.map((img, idx) => (
                        <div 
                            key={img.id}
                            onClick={() => handleSwitchImage(idx)}
                            className={`relative w-11 h-16 flex-shrink-0 rounded-lg overflow-hidden border-2 cursor-pointer transition-all shadow-md ${currentIdx === idx ? 'border-indigo-500 scale-105 opacity-100' : 'border-white/20 opacity-60 hover:opacity-100'}`}
                        >
                            <img src={img.src} className="w-full h-full object-cover" />
                        </div>
                    ))}
                </div>
            )}

           {/* Prompt Peek */}
           <div className="flex items-center gap-2 px-1">
               <div className="bg-indigo-500/20 text-indigo-300 text-[10px] font-bold px-1.5 py-0.5 rounded border border-indigo-500/30">PROMPT</div>
               <div className="text-xs text-white/70 truncate flex-1 font-mono">
                  {currentImg?.prompt}
               </div>
           </div>

           {/* Input Bar */}
           <div className="flex items-center gap-2 bg-[#1C1C1E]/90 backdrop-blur-xl border border-white/10 rounded-full px-2 py-1.5 pl-4 shadow-2xl mb-2">
              <Sparkles size={18} className="text-indigo-400 shrink-0" />
              <input 
                type="text"
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="修改画面 (例如: 赛博朋克风格...)"
                className="flex-1 bg-transparent border-none text-white text-sm focus:ring-0 placeholder:text-white/30 h-10 min-w-0"
              />
              <button 
                onClick={handleMagicEdit}
                disabled={!prompt || isLoading}
                className={`w-9 h-9 rounded-full flex items-center justify-center shrink-0 transition-colors ${prompt ? 'bg-indigo-600 text-white shadow-lg' : 'bg-white/5 text-white/20'}`}
              >
                <Send size={16} className={prompt ? "ml-0.5" : ""} />
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

