      const inputSection = isRegeneration 
          ? `>> INPUT_MODIFIER: "${prompt}"\n>> STATUS: REVISING...`
          : `>> KEYWORDS_DETECTED: Cyberpunk, Vlog, Viral\n>> DURATION_CONSTRAINT: 30s`;

      const reasoningSection = isRegeneration
          ? `>> EXECUTION_PLAN:\n   [1] CRITIQUE: Analyze user feedback on tone/pacing.\n   [2] ADJUST: Enhance visual descriptors, tighten dialogue.\n   [3] VERIFY: Cyberpunk aesthetic integrity check.`
          : `>> EXECUTION_PLAN:\n   [1] CONCEPT: Fusion of High-Tech & Lo-Fi Life.\n   [2] STRUCTURE: 3-Act Micro-Narrative (Hook > Conflict > Resolution).\n   [3] AESTHETICS: Neon noir, rain-slicked streets, glitch effects.`;

      const fullThought = `${thoughtTitle}
-----------------------------------
${inputSection}

${reasoningSection}

>> OUTPUT_GENERATION:
   > Title: Neon Hotpot (霓虹火锅) ${isRegeneration ? 'v2.0' : ''}
   > Scene Flow: Cityscape -> Food (Macro) -> Tech (Detail).`;

      setMessages(prev => [...prev, {
          id: agentMsgId,
          role: 'agent',
          type: 'text',
          thoughtProcess: '',
          text: '',
          timestamp: Date.now()
      }]);

      let currentThought = '';
      const chunkSize = 8;
      let i = 0;

      const streamInterval = setInterval(() => {
          if (i < fullThought.length) {
              currentThought += fullThought.slice(i, i + chunkSize);
              setMessages(prev => prev.map(m => m.id === agentMsgId ? { ...m, thoughtProcess: currentThought } : m));
              i += chunkSize;
          } else {
              clearInterval(streamInterval);

              const responseText = isRegeneration 
                  ? `没问题，根据您的要求"${prompt}"，我重新调整了脚本：`
                  : '收到！根据你的描述，我为你构思了以下脚本结构：';

              const newScript = {
                  ...MOCK_SCRIPT,
                  title: isRegeneration ? `${MOCK_SCRIPT.title} (修改版)` : MOCK_SCRIPT.title,
                  lines: MOCK_SCRIPT.lines.map(l => ({
                      ...l,
                      visual: isRegeneration ? `${l.visual} (优化细节)` : l.visual
                  }))
              };

              setMessages(prev => prev.map(m => m.id === agentMsgId ? { ...m, thoughtProcess: fullThought, text: responseText } : m));

              setTimeout(() => {
                  addMsg({ role: 'agent', type: 'script_card', scriptData: newScript });
                  setIsAgentThinking(false);
              }, 600);
          }
      }, 10);
  };

  const handleUserMessage = async (text: string) => {
    addMsg({ role: 'user', text, type: 'text' });

    const lastAgentMsg = [...messages].reverse().find(m => m.role === 'agent' && m.type !== 'text');
    const lastAgentType = lastAgentMsg?.type;

    if (lastAgentType === 'script_card') {
        setIsAgentThinking(true);
        setTimeout(() => { generateScript(text, true); }, 800);
        return;
    }

    if (lastAgentType === 'character_card') {
         setIsAgentThinking(true);
         const loadingId = 'loading-' + Date.now();
         setMessages(prev => [...prev, { id: loadingId, role: 'agent', type: 'text', isLoading: true, timestamp: Date.now() }]);

         setTimeout(() => {
             setMessages(prev => prev.filter(m => m.id !== loadingId));

             let targetIndex = -1;
             if (text.includes('二') || text.includes('2')) targetIndex = 1;
             else if (text.includes('一') || text.includes('1')) targetIndex = 0;
             else if (text.includes('三') || text.includes('3')) targetIndex = 2;

             const currentChars = lastAgentMsg?.characterData || MOCK_CHARACTERS;
             const updatedChars = currentChars.map((char, idx) => {
                 if (targetIndex !== -1 && idx !== targetIndex) return char;
                 return {
                     ...char,
                     imageUrl: `https://picsum.photos/200/200?random=${Date.now() + idx}`,
                     description: `${char.description} (已根据要求优化)`
                 };
             });

             const responseText = targetIndex !== -1 
                ? `好的，已为您重新设计第 ${targetIndex + 1} 个角色。`
                : `没问题，根据您的反馈"${text}"，我调整了角色设计。`;

             addMsg({ role: 'agent', text: responseText });
             setTimeout(() => {
                 addMsg({ role: 'agent', type: 'character_card', characterData: updatedChars });
                 setIsAgentThinking(false);
             }, 500);
         }, 1500);
         return;
    }

    if (lastAgentType === 'storyboard_card') {
         setIsAgentThinking(true);
         const loadingId = 'loading-' + Date.now();
         setMessages(prev => [...prev, { id: loadingId, role: 'agent', type: 'text', isLoading: true, timestamp: Date.now() }]);

         setTimeout(() => {
             setMessages(prev => prev.filter(m => m.id !== loadingId));
             addMsg({ role: 'agent', text: '好的，正在根据您的反馈调整分镜画面...' });

             const updatedStoryboard = (lastAgentMsg?.storyboardData || MOCK_STORYBOARD).map((img, idx) => {
                 if (idx === 0) return { ...img, description: `${img.description} (已修改: ${text})`, src: `https://picsum.photos/400/600?random=${Date.now()}` };
                 return img;
             });

             setTimeout(() => {
                 addMsg({ role: 'agent', type: 'storyboard_card', storyboardData: updatedStoryboard });
                 setIsAgentThinking(false);
             }, 1000);
         }, 1000);
         return;
    }

    // Default
    setIsAgentThinking(true);
    const loadingId = 'loading-' + Date.now();
    setMessages(prev => [...prev, { id: loadingId, role: 'agent', type: 'text', isLoading: true, timestamp: Date.now() }]);

    setTimeout(() => {
      setMessages(prev => prev.filter(m => m.id !== loadingId));
      generateScript(text, false);
    }, 1500);
  };

  // --- INTERACTION HANDLERS ---
  const handleCardClick = useCallback((msgId: string, action: string, data?: any) => {
    if (action === 'confirm_script') {
        const scriptData = data as ScriptData;
        setIsAgentThinking(true);
        setTimeout(() => {
            setIsAgentThinking(false);
            addMsg({ role: 'agent', text: '脚本确认。已提取核心角色设定，请确认定妆风格：' });
            addMsg({ role: 'agent', type: 'character_card', characterData: MOCK_CHARACTERS });
        }, 1000);

    } else if (action === 'confirm_characters') {
        setIsAgentThinking(true);
        setTimeout(() => {
             setIsAgentThinking(false);
             const scriptMsg = [...messages].reverse().find(m => m.type === 'script_card');
             const scriptData = scriptMsg?.scriptData || MOCK_SCRIPT;

             addMsg({ role: 'agent', text: '角色定妆完成。正在生成动态分镜...' });

            const generatedStoryboard: StoryboardImage[] = scriptData.lines.map((line) => ({
                id: `img-${line.id}`,
                src: `https://picsum.photos/400/600?random=${line.id}-${Date.now()}`, 
                prompt: line.visual,
                description: line.visual.length > 50 ? line.visual.substring(0, 47) + '...' : line.visual,
                subtitle: line.audio
            }));

            setTimeout(() => {
                addMsg({ 
                    role: 'agent', 
                    type: 'storyboard_card', 
                    storyboardData: generatedStoryboard.length > 0 ? generatedStoryboard : MOCK_STORYBOARD 
                });
            }, 1500);
        }, 500);

    } else if (action === 'confirm_storyboard') {
         const finalStoryboard = (data as StoryboardImage[]) || MOCK_STORYBOARD;

         setIsAgentThinking(true);
         setTimeout(() => {
             setIsAgentThinking(false);
             addMsg({ role: 'agent', text: '分镜确认。正在进行最终渲染...' });

             setTimeout(() => {
                 const segments: VideoSegment[] = finalStoryboard.map((img, idx) => ({
                     id: `seg-${idx}`,
                     thumbnail: img.src,
                     duration: ['5s', '10s', '8s'][idx] || '5s',
                     description: img.description
                 }));

                 addMsg({ 
                     role: 'agent', 
                     type: 'video_card', 
                     videoData: {
                         thumbnail: finalStoryboard[0].src, 
                         videoUrl: '#',
                         duration: '23s',
                         segments: segments
                     } 
                 });
             }, 2500);
         }, 500);

    } else if (action === 'open_script') {
      setOverlay({ type: 'script_editor', data: data });

    } else if (action === 'view_image') {
      setOverlay({ type: 'image_viewer', data: data });

    } else if (action === 'view_character') {
        setOverlay({ type: 'character_viewer', data: data });

    } else if (action === 'play_video') {
        setOverlay({ type: 'video_player', data: data });
    }
  }, [messages]);

  const handleScriptSave = (newData: ScriptData) => {
    setOverlay({ type: 'none' });
    setMessages(prev => prev.map(m => 
       m.type === 'script_card' ? { ...m, scriptData: newData } : m
    ));
  };

  const handleAiScriptModification = (prompt: string, currentScript: ScriptData) => {
      setOverlay({ type: 'none' });
      addMsg({ role: 'user', text: prompt, type: 'text' });
      setIsAgentThinking(true);
      setTimeout(() => {
          generateScript(prompt, true);
      }, 1000);
  };

  const handleImageUpdate = (updatedImg: StoryboardImage) => {
     setMessages(prev => prev.map(msg => {
         if (msg.type === 'storyboard_card' && msg.storyboardData) {
             return {
                 ...msg,
                 storyboardData: msg.storyboardData.map(img => 
                     img.id === updatedImg.id ? updatedImg : img
                 )
             };
         }
         return msg;
     }));
  };

  const handleCharacterUpdate = (updatedChar: CharacterDesign) => {
    setMessages(prev => prev.map(msg => {
        if (msg.type === 'character_card' && msg.characterData) {
            return {
                ...msg,
                characterData: msg.characterData.map(c => 
                    c.id === updatedChar.id ? updatedChar : c
                )
            };
        }
        return msg;
    }));
  };

  return (
    <div className="flex justify-center h-screen w-screen overflow-hidden text-gray-100">
      <div className="w-full max-w-md h-full flex flex-col relative md:border-x border-white/5 bg-transparent">

        {/* Ambient Gradient Overlay in Container */}
        <div className="absolute inset-0 bg-gradient-to-b from-indigo-900/10 to-transparent pointer-events-none z-0" />

        {/* TOP GRADIENT MASK for smooth scrolling under header */}
        <div className="absolute top-0 left-0 right-0 h-32 bg-gradient-to-b from-black via-black/80 to-transparent pointer-events-none z-10" />

        <header className="flex items-center justify-between p-4 pt-6 absolute top-0 left-0 right-0 z-20">
           <button className="text-white/70 hover:text-white p-2 rounded-full hover:bg-white/10 transition-colors backdrop-blur-md">
              <ChevronLeft size={24} />
           </button>
           <span className="text-sm font-bold tracking-widest uppercase opacity-80 drop-shadow-md text-white/90">Creative Studio</span>
           <button className="text-white/70 hover:text-white p-2 rounded-full hover:bg-white/10 transition-colors backdrop-blur-md">
              <MoreHorizontal size={24} />
           </button>
        </header>

        <ChatInterface 
          messages={messages} 
          onCardClick={handleCardClick} 
        />

        <InputArea 
            onSendMessage={handleUserMessage} 
            disabled={isAgentThinking} 
        />

        {overlay.type === 'script_editor' && (
          <ScriptEditor 
            initialData={overlay.data} 
            onClose={() => setOverlay({ type: 'none' })}
            onConfirm={handleScriptSave} 
            onAiEditRequest={(prompt) => handleAiScriptModification(prompt, overlay.data)}
          />
        )}

        {overlay.type === 'image_viewer' && (
          <ImageViewer
            initialImage={overlay.data.initialImage}
            allImages={overlay.data.allImages}
            onClose={() => setOverlay({ type: 'none' })}
            onUpdate={handleImageUpdate}
          />
        )}

        {overlay.type === 'character_viewer' && (
            <CharacterViewer
                initialCharacter={overlay.data.initialCharacter}
                allCharacters={overlay.data.allCharacters}
                onClose={() => setOverlay({ type: 'none' })}
                onUpdate={handleCharacterUpdate}
            />
        )}

        {overlay.type === 'video_player' && (
            <VideoPlayer
                thumbnail={overlay.data.thumbnail}
                segments={overlay.data.segments}
                onClose={() => setOverlay({ type: 'none' })}
            />
        )}

      </div>
    </div>
  );
}

import React, { useEffect, useRef, useState } from 'react';
import { Message } from '../types';
import { AVATAR_URL } from '../constants';
import { Terminal, ChevronDown, ChevronRight, Sparkles } from 'lucide-react';
import { ScriptCard, StoryboardCard, AudioSelectionCard, VideoCard, CharacterSelectionCard } from './ImmersiveCards';

interface ChatInterfaceProps {
  messages: Message[];
  onCardClick: (msgId: string, action: string, data?: any) => void;
}

const MessageItem: React.FC<{ msg: Message; onCardClick: (msgId: string, action: string, data?: any) => void }> = ({ msg, onCardClick }) => {
    const [isThinkingExpanded, setIsThinkingExpanded] = useState(true);

    return (
        <div 
          className={`flex gap-3 w-full animate-in slide-in-from-bottom-4 duration-700 ${
            msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'
          }`}
        >
          {/* Avatar (Agent Only) */}
          {msg.role === 'agent' && (
            <div className="flex-shrink-0 w-8 h-8 rounded-full overflow-hidden mt-1 shadow-[0_0_10px_rgba(255,255,255,0.2)] border border-white/20">
              <img src={AVATAR_URL} alt="Agent" className="w-full h-full object-cover scale-110" />
            </div>
          )}

          {/* Content Container */}
          <div className={`flex flex-col gap-2 max-w-full ${
            msg.role === 'user' ? 'items-end' : 'items-start'
          } flex-1 min-w-0`}>

            {/* Thinking Process Block (Cyberpunk Terminal Style) */}
            {msg.thoughtProcess && (
                <div className="bg-black/40 border border-indigo-500/20 rounded-xl overflow-hidden max-w-[95%] mb-2 backdrop-blur-md shadow-lg group">
                    <button 
                        onClick={() => setIsThinkingExpanded(!isThinkingExpanded)}
                        className="flex items-center gap-2 w-full px-3 py-2 bg-white/5 hover:bg-white/10 transition-colors text-[10px] font-bold text-indigo-300 uppercase tracking-widest select-none"
                    >
                        <Terminal size={12} className={isThinkingExpanded ? "text-indigo-400 animate-pulse" : "text-gray-500"} />
                        <span>AI_KERNEL_PROCESS</span>
                        <div className="flex-1 h-px bg-indigo-500/20 mx-2" />
                        {isThinkingExpanded ? <ChevronDown size={12} /> : <ChevronRight size={12} />}
                    </button>

                    {isThinkingExpanded && (
                        <div className="px-4 py-3 bg-black/30 text-[11px] text-indigo-100/70 leading-relaxed whitespace-pre-wrap font-mono border-t border-white/5 min-h-[40px] shadow-inner relative">
                            <div className="absolute top-0 left-0 w-1 h-full bg-indigo-500/20" />
                            {msg.thoughtProcess}
                            {!msg.text && (
                                <span className="inline-block w-1.5 h-3 bg-indigo-400 ml-1 animate-pulse align-middle" />
                            )}
                        </div>
                    )}
                </div>
            )}

            {/* Text Bubble */}
            {msg.text && (
              <div 
                className={`px-5 py-3 rounded-2xl text-[15px] leading-relaxed max-w-[85%] shadow-lg border backdrop-blur-md ${
                  msg.role === 'user' 
                    ? 'bg-gradient-to-br from-indigo-600 to-purple-600 text-white border-transparent rounded-br-none' 
                    : 'glass-bubble-agent text-gray-100 rounded-bl-none border-white/10'
                }`}
              >
                {msg.text}
              </div>
            )}

            {/* Loading Indicator */}
            {msg.isLoading && (
               <div className="glass-bubble-agent px-4 py-3 rounded-2xl rounded-bl-none shadow-lg flex items-center gap-1.5 max-w-[80px]">
                  <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-[bounce_1s_infinite_-0.3s]"></div>
                  <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-[bounce_1s_infinite_-0.15s]"></div>
                  <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-[bounce_1s_infinite]"></div>
               </div>
            )}

            {/* Rich Cards */}
            {!msg.isLoading && (
                <div className="w-full animate-in fade-in zoom-in-95 duration-500 slide-in-from-bottom-2">
                    {msg.type === 'character_card' && msg.characterData && (
                    <CharacterSelectionCard 
                        characters={msg.characterData} 
                        onConfirm={() => onCardClick(msg.id, 'confirm_characters')}
                        onCharacterClick={(char) => onCardClick(msg.id, 'view_character', { initialCharacter: char, allCharacters: msg.characterData })}
                    />
                    )}

                    {msg.type === 'script_card' && msg.scriptData && (
                    <ScriptCard 
                        data={msg.scriptData} 
                        onConfirm={() => onCardClick(msg.id, 'confirm_script', msg.scriptData)}
                        onEdit={() => onCardClick(msg.id, 'open_script', msg.scriptData)}
                    />
                    )}

                    {msg.type === 'storyboard_card' && msg.storyboardData && (
                    <StoryboardCard 
                        images={msg.storyboardData} 
                        onImageClick={(img) => onCardClick(msg.id, 'view_image', { initialImage: img, allImages: msg.storyboardData })}
                        onConfirm={() => onCardClick(msg.id, 'confirm_storyboard', msg.storyboardData)}
                    />
                    )}

                    {msg.type === 'audio_selection' && msg.audioOptions && (
                    <AudioSelectionCard 
                        options={msg.audioOptions} 
                        onSelect={(id) => onCardClick(msg.id, 'select_audio', id)}
                    />
                    )}

                    {msg.type === 'video_card' && msg.videoData && (
                        <VideoCard 
                            thumbnail={msg.videoData.thumbnail}
                            duration={msg.videoData.duration}
                            segments={msg.videoData.segments}
                            onEdit={() => onCardClick(msg.id, 'play_video', msg.videoData)}
                        />
                    )}
                </div>
            )}
          </div>
        </div>
    );
};

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ messages, onCardClick }) => {
  const bottomRef = useRef<HTMLDivElement>(null);
  const lastMsg = messages[messages.length - 1];

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages.length, lastMsg?.isLoading, lastMsg?.thoughtProcess?.length]);

  return (
    <div className="flex-1 overflow-y-auto px-4 py-4 space-y-6 custom-scrollbar z-10 pt-32">
        {/* Date / Time Separator Idea */}
        <div className="flex justify-center mb-4 opacity-0 animate-in fade-in duration-1000">
            <span className="text-[10px] font-mono text-white/20 uppercase tracking-widest bg-white/5 px-2 py-1 rounded-full backdrop-blur-sm">
                Session Start: {new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
            </span>
        </div>

      {messages.map((msg) => (
         <MessageItem key={msg.id} msg={msg} onCardClick={onCardClick} />
      ))}
      <div ref={bottomRef} className="h-4" />
    </div>
  );
};

import React, { useState, useCallback } from 'react';
import { ChevronLeft, MoreHorizontal } from 'lucide-react';
import { Message, OverlayState, ScriptData, StoryboardImage, VideoSegment, CharacterDesign } from './types';
import { ChatInterface } from './components/ChatInterface';
import { InputArea } from './components/InputArea';
import { ScriptEditor, ImageViewer, VideoPlayer, CharacterViewer } from './components/Overlays';
import { MOCK_SCRIPT, MOCK_STORYBOARD, MOCK_CHARACTERS } from './constants';

export default function App() {
  const [messages, setMessages] = useState<Message[]>([
    { 
      id: 'init', 
      role: 'agent', 
      type: 'text', 
      text: '嗨！我是你的创意导演。今天想拍一段什么样的视频？', 
      timestamp: Date.now() 
    }
  ]);
  const [overlay, setOverlay] = useState<OverlayState>({ type: 'none' });
  const [isAgentThinking, setIsAgentThinking] = useState(false);

  // --- Helper to add message ---
  const addMsg = (msg: Partial<Message>) => {
    setMessages(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: Date.now(),
      role: 'agent',
      type: 'text',
      ...msg
    } as Message]);
  };

  // --- CORE GENERATION LOGIC ---
  const generateScript = (prompt: string, isRegeneration = false) => {
      const agentMsgId = `agent-${Date.now()}`;

      const thoughtTitle = isRegeneration ? "TASK: OPTIMIZE_SCRIPT_V2" : "TASK: INIT_CREATIVE_DIRECTION";
      const inputSection = isRegeneration 
          ? `>> INPUT_MODIFIER: "${prompt}"\n>> STATUS: REVISING...`
          : `>> KEYWORDS_DETECTED: Cyberpunk, Vlog, Viral\n>> DURATION_CONSTRAINT: 30s`;

      const reasoningSection = isRegeneration
          ? `>> EXECUTION_PLAN:\n   [1] CRITIQUE: Analyze user feedback on tone/pacing.\n   [2] ADJUST: Enhance visual descriptors, tighten dialogue.\n   [3] VERIFY: Cyberpunk aesthetic integrity check.`
          : `>> EXECUTION_PLAN:\n   [1] CONCEPT: Fusion of High-Tech & Lo-Fi Life.\n   [2] STRUCTURE: 3-Act Micro-Narrative (Hook > Conflict > Resolution).\n   [3] AESTHETICS: Neon noir, rain-slicked streets, glitch effects.`;

      const fullThought = `${thoughtTitle}
-----------------------------------
${inputSection}

${reasoningSection}

>> OUTPUT_GENERATION:
   > Title: Neon Hotpot (霓虹火锅) ${isRegeneration ? 'v2.0' : ''}
   > Scene Flow: Cityscape -> Food (Macro) -> Tech (Detail).`;

      setMessages(prev => [...prev, {
          id: agentMsgId,
          role: 'agent',
          type: 'text',
          thoughtProcess: '',
          text: '',
          timestamp: Date.now()
      }]);

      let currentThought = '';
      const chunkSize = 8;
      let i = 0;

      const streamInterval = setInterval(() => {
          if (i < fullThought.length) {
              currentThought += fullThought.slice(i, i + chunkSize);
              setMessages(prev => prev.map(m => m.id === agentMsgId ? { ...m, thoughtProcess: currentThought } : m));
              i += chunkSize;
          } else {
              clearInterval(streamInterval);

              const responseText = isRegeneration 
                  ? `没问题，根据您的要求"${prompt}"，我重新调整了脚本：`
                  : '收到！根据你的描述，我为你构思了以下脚本结构：';

              const newScript = {
                  ...MOCK_SCRIPT,
                  title: isRegeneration ? `${MOCK_SCRIPT.title} (修改版)` : MOCK_SCRIPT.title,
                  lines: MOCK_SCRIPT.lines.map(l => ({
                      ...l,
                      visual: isRegeneration ? `${l.visual} (优化细节)` : l.visual
                  }))
              };

              setMessages(prev => prev.map(m => m.id === agentMsgId ? { ...m, thoughtProcess: fullThought, text: responseText } : m));

              setTimeout(() => {
                  addMsg({ role: 'agent', type: 'script_card', scriptData: newScript });
                  setIsAgentThinking(false);
              }, 600);
          }
      }, 10);
  };

  const handleUserMessage = async (text: string) => {
    addMsg({ role: 'user', text, type: 'text' });

    const lastAgentMsg = [...messages].reverse().find(m => m.role === 'agent' && m.type !== 'text');
    const lastAgentType = lastAgentMsg?.type;

    if (lastAgentType === 'script_card') {
        setIsAgentThinking(true);
        setTimeout(() => { generateScript(text, true); }, 800);
        return;
    }

    if (lastAgentType === 'character_card') {
         setIsAgentThinking(true);
         const loadingId = 'loading-' + Date.now();
         setMessages(prev => [...prev, { id: loadingId, role: 'agent', type: 'text', isLoading: true, timestamp: Date.now() }]);

         setTimeout(() => {
             setMessages(prev => prev.filter(m => m.id !== loadingId));

             let targetIndex = -1;
             if (text.includes('二') || text.includes('2')) targetIndex = 1;
             else if (text.includes('一') || text.includes('1')) targetIndex = 0;
             else if (text.includes('三') || text.includes('3')) targetIndex = 2;

             const currentChars = lastAgentMsg?.characterData || MOCK_CHARACTERS;
             const updatedChars = currentChars.map((char, idx) => {
                 if (targetIndex !== -1 && idx !== targetIndex) return char;
                 return {
                     ...char,
                     imageUrl: `https://picsum.photos/200/200?random=${Date.now() + idx}`,
                     description: `${char.description} (已根据要求优化)`
                 };
             });

             const responseText = targetIndex !== -1 
                ? `好的，已为您重新设计第 ${targetIndex + 1} 个角色。`
                : `没问题，根据您的反馈"${text}"，我调整了角色设计。`;

             addMsg({ role: 'agent', text: responseText });
             setTimeout(() => {
                 addMsg({ role: 'agent', type: 'character_card', characterData: updatedChars });
                 setIsAgentThinking(false);
             }, 500);
         }, 1500);
         return;
    }

    if (lastAgentType === 'storyboard_card') {
         setIsAgentThinking(true);
         const loadingId = 'loading-' + Date.now();
         setMessages(prev => [...prev, { id: loadingId, role: 'agent', type: 'text', isLoading: true, timestamp: Date.now() }]);

         setTimeout(() => {
             setMessages(prev => prev.filter(m => m.id !== loadingId));
             addMsg({ role: 'agent', text: '好的，正在根据您的反馈调整分镜画面...' });

             const updatedStoryboard = (lastAgentMsg?.storyboardData || MOCK_STORYBOARD).map((img, idx) => {
                 if (idx === 0) return { ...img, description: `${img.description} (已修改: ${text})`, src: `https://picsum.photos/400/600?random=${Date.now()}` };
                 return img;
             });

             setTimeout(() => {
                 addMsg({ role: 'agent', type: 'storyboard_card', storyboardData: updatedStoryboard });
                 setIsAgentThinking(false);
             }, 1000);
         }, 1000);
         return;
    }

    // Default
    setIsAgentThinking(true);
    const loadingId = 'loading-' + Date.now();
    setMessages(prev => [...prev, { id: loadingId, role: 'agent', type: 'text', isLoading: true, timestamp: Date.now() }]);

    setTimeout(() => {
      setMessages(prev => prev.filter(m => m.id !== loadingId));
      generateScript(text, false);
    }, 1500);
  };

  // --- INTERACTION HANDLERS ---
  const handleCardClick = useCallback((msgId: string, action: string, data?: any) => {
    if (action === 'confirm_script') {
        const scriptData = data as ScriptData;
        setIsAgentThinking(true);
        setTimeout(() => {
            setIsAgentThinking(false);
            addMsg({ role: 'agent', text: '脚本确认。已提取核心角色设定，请确认定妆风格：' });
            addMsg({ role: 'agent', type: 'character_card', characterData: MOCK_CHARACTERS });
        }, 1000);

    } else if (action === 'confirm_characters') {
        setIsAgentThinking(true);
        setTimeout(() => {
             setIsAgentThinking(false);
             const scriptMsg = [...messages].reverse().find(m => m.type === 'script_card');
             const scriptData = scriptMsg?.scriptData || MOCK_SCRIPT;

             addMsg({ role: 'agent', text: '角色定妆完成。正在生成动态分镜...' });

            const generatedStoryboard: StoryboardImage[] = scriptData.lines.map((line) => ({
                id: `img-${line.id}`,
                src: `https://picsum.photos/400/600?random=${line.id}-${Date.now()}`, 
                prompt: line.visual,
                description: line.visual.length > 50 ? line.visual.substring(0, 47) + '...' : line.visual,
                subtitle: line.audio
            }));

            setTimeout(() => {
                addMsg({ 
                    role: 'agent', 
                    type: 'storyboard_card', 
                    storyboardData: generatedStoryboard.length > 0 ? generatedStoryboard : MOCK_STORYBOARD 
                });
            }, 1500);
        }, 500);

    } else if (action === 'confirm_storyboard') {
         const finalStoryboard = (data as StoryboardImage[]) || MOCK_STORYBOARD;

         setIsAgentThinking(true);
         setTimeout(() => {
             setIsAgentThinking(false);
             addMsg({ role: 'agent', text: '分镜确认。正在进行最终渲染...' });

             setTimeout(() => {
                 const segments: VideoSegment[] = finalStoryboard.map((img, idx) => ({
                     id: `seg-${idx}`,
                     thumbnail: img.src,
                     duration: ['5s', '10s', '8s'][idx] || '5s',
                     description: img.description
                 }));

                 addMsg({ 
                     role: 'agent', 
                     type: 'video_card', 
                     videoData: {
                         thumbnail: finalStoryboard[0].src, 
                         videoUrl: '#',
                         duration: '23s',
                         segments: segments
                     } 
                 });
             }, 2500);
         }, 500);

    } else if (action === 'open_script') {
      setOverlay({ type: 'script_editor', data: data });

    } else if (action === 'view_image') {
      setOverlay({ type: 'image_viewer', data: data });

    } else if (action === 'view_character') {
        setOverlay({ type: 'character_viewer', data: data });

    } else if (action === 'play_video') {
        setOverlay({ type: 'video_player', data: data });
    }
  }, [messages]);

  const handleScriptSave = (newData: ScriptData) => {
    setOverlay({ type: 'none' });
    setMessages(prev => prev.map(m => 
       m.type === 'script_card' ? { ...m, scriptData: newData } : m
    ));
  };

  const handleAiScriptModification = (prompt: string, currentScript: ScriptData) => {
      setOverlay({ type: 'none' });
      addMsg({ role: 'user', text: prompt, type: 'text' });
      setIsAgentThinking(true);
      setTimeout(() => {
          generateScript(prompt, true);
      }, 1000);
  };

  const handleImageUpdate = (updatedImg: StoryboardImage) => {
     setMessages(prev => prev.map(msg => {
         if (msg.type === 'storyboard_card' && msg.storyboardData) {
             return {
                 ...msg,
                 storyboardData: msg.storyboardData.map(img => 
                     img.id === updatedImg.id ? updatedImg : img
                 )
             };
         }
         return msg;
     }));
  };

  const handleCharacterUpdate = (updatedChar: CharacterDesign) => {
    setMessages(prev => prev.map(msg => {
        if (msg.type === 'character_card' && msg.characterData) {
            return {
                ...msg,
                characterData: msg.characterData.map(c => 
                    c.id === updatedChar.id ? updatedChar : c
                )
            };
        }
        return msg;
    }));
  };

  return (
    <div className="flex justify-center h-screen w-screen overflow-hidden text-gray-100">
      <div className="w-full max-w-md h-full flex flex-col relative md:border-x border-white/5 bg-transparent">

        {/* Ambient Gradient Overlay in Container */}
        <div className="absolute inset-0 bg-gradient-to-b from-indigo-900/10 to-transparent pointer-events-none z-0" />

        {/* TOP GRADIENT MASK for smooth scrolling under header (High Z-Index) */}
        <div className="absolute top-0 left-0 right-0 h-40 bg-gradient-to-b from-black via-black/90 to-transparent pointer-events-none z-20" />

        <header className="flex items-center justify-between p-4 pt-6 absolute top-0 left-0 right-0 z-30">
           <button className="text-white/70 hover:text-white p-2 rounded-full hover:bg-white/10 transition-colors backdrop-blur-md">
              <ChevronLeft size={24} />
           </button>
           <span className="text-sm font-bold tracking-widest uppercase opacity-80 drop-shadow-md text-white/90">Creative Studio</span>
           <button className="text-white/70 hover:text-white p-2 rounded-full hover:bg-white/10 transition-colors backdrop-blur-md">
              <MoreHorizontal size={24} />
           </button>
        </header>

        <ChatInterface 
          messages={messages} 
          onCardClick={handleCardClick} 
        />

        <InputArea 
            onSendMessage={handleUserMessage} 
            disabled={isAgentThinking} 
        />

        {overlay.type === 'script_editor' && (
          <ScriptEditor 
            initialData={overlay.data} 
            onClose={() => setOverlay({ type: 'none' })}
            onConfirm={handleScriptSave} 
            onAiEditRequest={(prompt) => handleAiScriptModification(prompt, overlay.data)}
          />
        )}

        {overlay.type === 'image_viewer' && (
          <ImageViewer
            initialImage={overlay.data.initialImage}
            allImages={overlay.data.allImages}
            onClose={() => setOverlay({ type: 'none' })}
            onUpdate={handleImageUpdate}
          />
        )}

        {overlay.type === 'character_viewer' && (
            <CharacterViewer
                initialCharacter={overlay.data.initialCharacter}
                allCharacters={overlay.data.allCharacters}
                onClose={() => setOverlay({ type: 'none' })}
                onUpdate={handleCharacterUpdate}
            />
        )}

        {overlay.type === 'video_player' && (
            <VideoPlayer
                thumbnail={overlay.data.thumbnail}
                segments={overlay.data.segments}
                onClose={() => setOverlay({ type: 'none' })}
            />
        )}

      </div>
    </div>
  );
}

import React, { useEffect, useRef, useState } from 'react';
import { Message } from '../types';
import { AVATAR_URL } from '../constants';
import { Terminal, ChevronDown, ChevronRight, Sparkles } from 'lucide-react';
import { ScriptCard, StoryboardCard, AudioSelectionCard, VideoCard, CharacterSelectionCard } from './ImmersiveCards';

interface ChatInterfaceProps {
  messages: Message[];
  onCardClick: (msgId: string, action: string, data?: any) => void;
}

const MessageItem: React.FC<{ msg: Message; onCardClick: (msgId: string, action: string, data?: any) => void }> = ({ msg, onCardClick }) => {
    const [isThinkingExpanded, setIsThinkingExpanded] = useState(true);

    return (
        <div 
          className={`flex gap-3 w-full animate-in slide-in-from-bottom-4 duration-700 ${
            msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'
          }`}
        >
          {/* Avatar (Agent Only) */}
          {msg.role === 'agent' && (
            <div className="flex-shrink-0 w-8 h-8 rounded-full overflow-hidden mt-1 shadow-[0_0_10px_rgba(255,255,255,0.2)] border border-white/20">
              <img src={AVATAR_URL} alt="Agent" className="w-full h-full object-cover scale-110" />
            </div>
          )}

          {/* Content Container */}
          <div className={`flex flex-col gap-2 max-w-full ${
            msg.role === 'user' ? 'items-end' : 'items-start'
          } flex-1 min-w-0`}>

            {/* Thinking Process Block (Cyberpunk Terminal Style) */}
            {msg.thoughtProcess && (
                <div className="bg-black/40 border border-indigo-500/20 rounded-xl overflow-hidden max-w-[95%] mb-2 backdrop-blur-md shadow-lg group">
                    <button 
                        onClick={() => setIsThinkingExpanded(!isThinkingExpanded)}
                        className="flex items-center gap-2 w-full px-3 py-2 bg-white/5 hover:bg-white/10 transition-colors text-[10px] font-bold text-indigo-300 uppercase tracking-widest select-none"
                    >
                        <Terminal size={12} className={isThinkingExpanded ? "text-indigo-400 animate-pulse" : "text-gray-500"} />
                        <span>AI_KERNEL_PROCESS</span>
                        <div className="flex-1 h-px bg-indigo-500/20 mx-2" />
                        {isThinkingExpanded ? <ChevronDown size={12} /> : <ChevronRight size={12} />}
                    </button>

                    {isThinkingExpanded && (
                        <div className="px-4 py-3 bg-black/30 text-[11px] text-indigo-100/70 leading-relaxed whitespace-pre-wrap font-mono border-t border-white/5 min-h-[40px] shadow-inner relative">
                            <div className="absolute top-0 left-0 w-1 h-full bg-indigo-500/20" />
                            {msg.thoughtProcess}
                            {!msg.text && (
                                <span className="inline-block w-1.5 h-3 bg-indigo-400 ml-1 animate-pulse align-middle" />
                            )}
                        </div>
                    )}
                </div>
            )}

            {/* Text Bubble */}
            {msg.text && (
              <div 
                className={`px-5 py-3 rounded-2xl text-[15px] leading-relaxed max-w-[85%] shadow-lg border backdrop-blur-md ${
                  msg.role === 'user' 
                    ? 'bg-gradient-to-br from-indigo-600 to-purple-600 text-white border-transparent rounded-br-none' 
                    : 'glass-bubble-agent text-gray-100 rounded-bl-none border-white/10'
                }`}
              >
                {msg.text}
              </div>
            )}

            {/* Loading Indicator */}
            {msg.isLoading && (
               <div className="glass-bubble-agent px-4 py-3 rounded-2xl rounded-bl-none shadow-lg flex items-center gap-1.5 max-w-[80px]">
                  <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-[bounce_1s_infinite_-0.3s]"></div>
                  <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-[bounce_1s_infinite_-0.15s]"></div>
                  <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-[bounce_1s_infinite]"></div>
               </div>
            )}

            {/* Rich Cards */}
            {!msg.isLoading && (
                <div className="w-full animate-in fade-in zoom-in-95 duration-500 slide-in-from-bottom-2">
                    {msg.type === 'character_card' && msg.characterData && (
                    <CharacterSelectionCard 
                        characters={msg.characterData} 
                        onConfirm={() => onCardClick(msg.id, 'confirm_characters')}
                        onCharacterClick={(char) => onCardClick(msg.id, 'view_character', { initialCharacter: char, allCharacters: msg.characterData })}
                    />
                    )}

                    {msg.type === 'script_card' && msg.scriptData && (
                    <ScriptCard 
                        data={msg.scriptData} 
                        onConfirm={() => onCardClick(msg.id, 'confirm_script', msg.scriptData)}
                        onEdit={() => onCardClick(msg.id, 'open_script', msg.scriptData)}
                    />
                    )}

                    {msg.type === 'storyboard_card' && msg.storyboardData && (
                    <StoryboardCard 
                        images={msg.storyboardData} 
                        onImageClick={(img) => onCardClick(msg.id, 'view_image', { initialImage: img, allImages: msg.storyboardData })}
                        onConfirm={() => onCardClick(msg.id, 'confirm_storyboard', msg.storyboardData)}
                    />
                    )}

                    {msg.type === 'audio_selection' && msg.audioOptions && (
                    <AudioSelectionCard 
                        options={msg.audioOptions} 
                        onSelect={(id) => onCardClick(msg.id, 'select_audio', id)}
                    />
                    )}

                    {msg.type === 'video_card' && msg.videoData && (
                        <VideoCard 
                            thumbnail={msg.videoData.thumbnail}
                            duration={msg.videoData.duration}
                            segments={msg.videoData.segments}
                            onEdit={() => onCardClick(msg.id, 'play_video', msg.videoData)}
                        />
                    )}
                </div>
            )}
          </div>
        </div>
    );
};

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ messages, onCardClick }) => {
  const bottomRef = useRef<HTMLDivElement>(null);
  const lastMsg = messages[messages.length - 1];

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages.length, lastMsg?.isLoading, lastMsg?.thoughtProcess?.length]);

  return (
    <div className="flex-1 overflow-y-auto px-4 py-4 space-y-6 custom-scrollbar pt-32">
        {/* Date / Time Separator Idea */}
        <div className="flex justify-center mb-4 opacity-0 animate-in fade-in duration-1000">
            <span className="text-[10px] font-mono text-white/20 uppercase tracking-widest bg-white/5 px-2 py-1 rounded-full backdrop-blur-sm">
                Session Start: {new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
            </span>
        </div>

      {messages.map((msg) => (
         <MessageItem key={msg.id} msg={msg} onCardClick={onCardClick} />
      ))}
      <div ref={bottomRef} className="h-4" />
    </div>
  );
};
